"""
ToonEngine 2D  v2 — CPU-only engine for cartoon action scenes.

Drawn from code with Cairo (vector, antialiased, CPU), simulated with simple
physics, encoded with ffmpeg. No GPU, no image generators, no paid services.

v2 upgrades (from free/open techniques & tools):
  * Two-bone IK legs with planted feet (law of cosines, as in Godot TwoBoneIK)
    -> no foot sliding when walking/running/sneaking
  * Disney principles: anticipation, follow-through & overlapping action via
    damped springs (head lag, ponytail, hair), volume-preserving squash &
    stretch (characters and ball), speed lines and ball motion trail
  * Lip sync with the 6+1 Hanna-Barbera / Rhubarb mouth shapes (A-F, X):
      - from a Rhubarb Lip Sync TSV (free, MIT)        say(..., cues="x.tsv")
      - from any voice file (ElevenLabs, Piper ...)    say(..., audio="x.mp3")
      - or from the text alone                          say("Hello!", t)
  * Voices mixed into the soundtrack, music ducks under dialogue
  * Characters look at each other / the ball (eye targets)
  * Fredoka (SIL Open Font License) for bubbles & captions, falls back to DejaVu
  * Optional folder of CC0 sound effects (e.g. Kenney packs): step.wav,
    jump.wav, land.wav, kick.wav ... override the built-in synth sounds
  * Multi-core rendering (multiprocessing) for VPS / big resolutions
  * JSON scene files (scene_from_json) so scenes can be generated by AI/Leo
"""
import math, random, subprocess, wave, os, sys, json, pickle, copy, tempfile
import multiprocessing as mp
import numpy as np
import cairo

G = 1800.0


def lerp(a: float, b: float, t: float) -> float:
    """Linear interpolation."""
    return a + (b - a) * t


def clamp(v: float, a: float, b: float) -> float:
    """Clamp v into [a, b]."""
    return max(a, min(b, v))


def ease(t: float) -> float:
    """Smoothstep ease-in-out on [0, 1]."""
    t = clamp(t, 0, 1)
    return t * t * (3 - 2 * t)


def hex2rgb(h: str) -> tuple:
    """'#rrggbb' -> (r, g, b) floats in 0..1."""
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))


def shade(rgb: tuple, k: float) -> tuple:
    """Multiply a colour by k (clamped)."""
    return tuple(clamp(c * k, 0, 1) for c in rgb)


INK = hex2rgb("#2b2233")
FONT = "Fredoka"


def pick_font():
    global FONT
    try:
        out = subprocess.run(["fc-list", ":family"], capture_output=True, text=True).stdout
        FONT = "Fredoka" if "Fredoka" in out else "DejaVu Sans"
    except Exception:
        FONT = "DejaVu Sans"


pick_font()

HATS = ("cap", "beanie", "top_hat", "chef", "straw", "bow", "headscarf")
GLASSES = ("round", "square", "sun")
FACIAL_HAIR = ("mustache", "beard", "both")

STAND = dict(torso=0.03, head=0.0, thighF=0.05, kneeF=0.05, thighB=-0.05, kneeB=0.05,
             armUF=0.12, elbowF=0.2, armUB=-0.1, elbowB=0.2, hip=0.0)


class Spring:
    """Damped spring for follow-through / overlapping action."""

    def __init__(self, k=140.0, d=11.0):
        self.x, self.v, self.k, self.d = 0.0, 0.0, k, d

    def update(self, target, dt):
        a = self.k * (target - self.x) - self.d * self.v
        self.v += a * dt
        self.x += self.v * dt
        return self.x


def ik2(hip: tuple, foot: tuple, l1: float, l2: float) -> tuple:
    """Two-bone IK (law of cosines). Angles: 0 = straight down, + = forward.
    Knee bends forward. Returns (thigh_angle, knee_bend)."""
    dx, dy = foot[0] - hip[0], foot[1] - hip[1]
    L = clamp(math.hypot(dx, dy), abs(l1 - l2) + 1e-3, l1 + l2 - 1e-3)
    base = math.atan2(dx, dy)
    a = math.acos(clamp((l1 * l1 + L * L - l2 * l2) / (2 * l1 * L), -1, 1))
    th = base + a
    kx, ky = hip[0] + l1 * math.sin(th), hip[1] + l1 * math.cos(th)
    shin = math.atan2(foot[0] - kx, foot[1] - ky)
    return th, th - shin


def arm_ik(shoulder: tuple, target: tuple, l1: float, l2: float) -> tuple:
    """Two-bone IK for an arm (same angle convention as legs: 0 = down, + = forward).
    The elbow bends backwards/down (natural arm). Unreachable targets give a straight
    arm pointing at the target. Returns (upper_arm_angle, elbow_bend)."""
    dx, dy = target[0] - shoulder[0], target[1] - shoulder[1]
    L = clamp(math.hypot(dx, dy), abs(l1 - l2) + 1e-3, l1 + l2 - 1e-3)
    base = math.atan2(dx, dy)
    a = math.acos(clamp((l1 * l1 + L * L - l2 * l2) / (2 * l1 * L), -1, 1))
    th = base - a
    ex, ey = shoulder[0] + l1 * math.sin(th), shoulder[1] + l1 * math.cos(th)
    if math.hypot(dx, dy) >= l1 + l2 - 1e-3:  # out of reach: straight arm along the target direction
        return base, 0.0
    fore = math.atan2(target[0] - ex, target[1] - ey)
    el = (fore - th + math.pi) % (2 * math.pi) - math.pi
    return th, el


class Chain:
    """Verlet rope/chain in world space (y up): scarf ends, long hair, antennae, ropes, tails.
    Point 0 is pinned to an anchor every step. `stiff` pulls points toward a rest shape
    along `rest_dir` (antennae), gravity is px/s^2 (negative = down). Picklable (plain lists)."""

    def __init__(self, n=6, seg=9.0, gravity=-900.0, damping=0.06, stiff=0.0, iters=6):
        self.n, self.seg, self.gravity, self.damping, self.stiff, self.iters = n, seg, gravity, damping, stiff, iters
        self.pts, self.prev = None, None

    def reset(self, anchor, rest_dir=(0.0, -1.0)):
        dx, dy = rest_dir
        self.pts = [(anchor[0] + dx * self.seg * i, anchor[1] + dy * self.seg * i) for i in range(self.n)]
        self.prev = list(self.pts)

    def update(self, anchor, dt, wind=0.0, rest_dir=(0.0, -1.0)):
        if self.pts is None:
            self.reset(anchor, rest_dir)
        dt = max(1e-4, dt)
        keep = 1.0 - self.damping
        pts, prev = self.pts, self.prev
        new = [tuple(anchor)]
        for i in range(1, self.n):
            x, y = pts[i]
            px, py = prev[i]
            ax, ay = wind, self.gravity
            if self.stiff:
                rx, ry = anchor[0] + rest_dir[0] * self.seg * i, anchor[1] + rest_dir[1] * self.seg * i
                ax += self.stiff * (rx - x)
                ay += self.stiff * (ry - y)
            new.append((x + (x - px) * keep + ax * dt * dt, y + (y - py) * keep + ay * dt * dt))
        self.prev = list(pts)
        self.prev[0] = tuple(anchor)
        for _ in range(self.iters):  # length constraints (point 0 pinned)
            for i in range(1, self.n):
                (x0, y0), (x1, y1) = new[i - 1], new[i]
                dx, dy = x1 - x0, y1 - y0
                d = math.hypot(dx, dy) or 1e-6
                diff = (d - self.seg) / d
                if i == 1:
                    new[i] = (x1 - dx * diff, y1 - dy * diff)
                else:
                    new[i - 1] = (x0 + dx * diff * 0.5, y0 + dy * diff * 0.5)
                    new[i] = (x1 - dx * diff * 0.5, y1 - dy * diff * 0.5)
            new[0] = tuple(anchor)
        self.pts = new
        return new

    def length(self):
        return sum(math.hypot(self.pts[i][0] - self.pts[i - 1][0], self.pts[i][1] - self.pts[i - 1][1])
                   for i in range(1, self.n)) if self.pts else 0.0


# ---------------------------------------------------------------- actions
class Action:
    duration = 0.0
    blend = 16.0

    def start(self, c, scene):
        self.t = 0.0

    def update(self, c, dt, scene):
        self.t += dt
        return self.t >= self.duration

    def pose(self, c):
        p = dict(STAND)
        p["hip"] = 1.5 * math.sin(c.clock * 2.2)
        p["armUF"] += 0.03 * math.sin(c.clock * 2.2)
        p["armUB"] -= 0.03 * math.sin(c.clock * 2.2 + 1)
        return p


class Wait(Action):
    def __init__(self, d):
        self.duration = d


class Turn(Action):
    """Turn to face +1/-1: tiny squash (anticipation), flip, stretch (follow-through)."""

    def __init__(self, face, style=None, d=None):
        """style: None = the character's turn_style (default classic squash flip), "paper" =
        Paper-Mario flip (#58): the body flattens to a sliver, flips, and opens again (d s,
        default 0.34) with a tiny whoosh."""
        self.face, self.duration = face, 0.18
        self.style, self.d = style, d

    def start(self, c, scene):
        super().start(c, scene)
        self.flipped = c.face == self.face
        self.paper = (self.style or getattr(c, "turn_style", None)) == "paper"
        if self.paper:
            self.duration = float(self.d) if self.d else PAPER_FLIP_D
            if not self.flipped:
                c._start_xflip(scene, self.duration, PAPER_FLIP_MIN, face=int(self.face))
            self.flipped = True
            return
        if not self.flipped:
            c.squash = 0.08

    def update(self, c, dt, scene):
        self.t += dt
        if getattr(self, "paper", False):
            return self.t >= self.duration
        if not self.flipped and self.t >= 0.07:
            self.flipped = True
            c.face = self.face
            c.squash = -0.06
        return self.t >= self.duration


class Look(Action):
    """Make the character's eyes (and facing, if face=True) follow a target."""

    def __init__(self, target, face=True):
        self.target, self.face, self.duration = target, face, 0.0

    def start(self, c, scene):
        super().start(c, scene)
        c.look_at = self.target
        if self.face and self.target is not None:
            c.face = 1 if self.target.x >= c.x else -1


class MoveTo(Action):
    # speed, stride (per full cycle), hip height, foot lift, torso lean
    GAITS = {"walk": (140, 80, 67, 10, 0.07), "run": (330, 128, 62, 26, 0.3),
             "sneak": (70, 64, 56, 12, 0.38)}
    blend = 40.0

    def __init__(self, x, gait="walk", speed=None):
        self.x, self.gait = x, gait
        sp, self.stride, self.hipH, self.lift, self.lean = self.GAITS[gait]
        self.speed = speed or sp

    def start(self, c, scene):
        super().start(c, scene)
        c.face = 1 if self.x >= c.x else -1
        self.last_half = math.floor(c.phase / math.pi)

    def update(self, c, dt, scene):
        self.t += dt
        d = self.x - c.x
        if self.gait == "run" and self.t < 0.12:  # anticipation: lean back before sprint
            return False
        ramp = ease(self.t / 0.25) * 0.7 + 0.3
        step = self.speed * ramp * dt
        if abs(d) <= step:
            c.x = self.x
            return True
        c.x += math.copysign(step, d)
        c.phase += step / (self.stride * c.leg_k()) * math.pi * 2
        half = math.floor(c.phase / math.pi)
        if half != self.last_half:
            self.last_half = half
            scene.event("step" if self.gait != "run" else "runstep", c.x)
            if self.gait == "run":
                scene.particles.dust(c.x - c.face * 10, _ground(scene, c.x), 3, c.face)
        return False

    def foot(self, q, k=1.0):
        u = (q % (2 * math.pi)) / (2 * math.pi)
        S = self.stride * k
        if u < 0.5:  # swing: foot travels forward in an arc
            e = ease(u / 0.5)
            return lerp(-S / 4, S / 4, e), -self.lift * k * math.sin(math.pi * u / 0.5)
        e = (u - 0.5) / 0.5  # stance: planted on the ground (moves back at body speed)
        return lerp(S / 4, -S / 4, e), 0.0

    def pose(self, c):
        q = c.phase
        p = dict(STAND)
        k = c.leg_k()
        bob = (5 if self.gait == "run" else 2.5) * math.cos(2 * q) * k
        hip = (0.0, -(self.hipH * k + bob))
        L1, L2 = c.THIGH, c.SHIN
        fxF, fyF = self.foot(q, k)
        fxB, fyB = self.foot(q + math.pi, k)
        T = getattr(c, "_terrain", None)
        drop, lean = 0.0, 0.0
        if T is not None and abs(c.y - T.at(c.x)) < 2.0:  # walking on terrain (#61): plant feet on h(x)
            g0 = T.at(c.x)
            dF = (T.at(c.x + c.face * fxF * c.scale) - g0) / c.scale
            dB = (T.at(c.x + c.face * fxB * c.scale) - g0) / c.scale
            fyF, fyB = fyF - dF, fyB - dB
            drop = max(0.0, -min(dF, dB))
            hip = (0.0, hip[1] + drop)
            lean = clamp(0.6 * math.atan(T.slope(c.x) * c.face), -0.22, 0.22)
        p["thighF"], p["kneeF"] = ik2(hip, (fxF, fyF), L1, L2)
        p["thighB"], p["kneeB"] = ik2(hip, (fxB, fyB), L1, L2)
        p["hip"] = -100  # flag: hip height comes from IK (see Character.draw)
        p["hipIK"] = self.hipH * k + bob - drop
        A = {"walk": 0.5, "run": 0.9, "sneak": 0.35}[self.gait]
        p["armUF"] = -A * math.sin(q)
        p["armUB"] = -A * math.sin(q + math.pi)
        p["torso"] = self.lean + lean
        if self.gait == "run":
            p["elbowF"] = p["elbowB"] = 1.5
            p["head"] = -0.18
            if self.t < 0.12:
                p["torso"], p["armUF"], p["armUB"] = -0.15, -0.8, -0.9
        elif self.gait == "sneak":
            p["elbowF"] = p["elbowB"] = 1.9
            p["armUF"] += 0.6
            p["armUB"] += 0.6
        else:
            p["elbowF"] = p["elbowB"] = 0.35
        return p


class Chase(MoveTo):
    """Run/walk after a moving object (ball, other character) until within reach."""

    def __init__(self, obj, gait="run", reach=38, timeout=8.0, speed=None):
        super().__init__(obj.x, gait, speed)
        self.obj, self.reach, self.timeout = obj, reach, timeout

    def start(self, c, scene):
        super().start(c, scene)
        c.look_at = self.obj

    def update(self, c, dt, scene):
        side = -1 if c.x < self.obj.x else 1          # stay on the side we come from
        goal = self.obj.x + side * self.reach
        if abs(goal - c.x) < 6 or self.t > self.timeout:
            c.face = 1 if self.obj.x >= c.x else -1    # end facing the target
            return True
        self.x = goal
        c.face = 1 if goal >= c.x else -1
        return MoveTo.update(self, c, dt, scene)


class Jump(Action):
    abs_y = True

    def __init__(self, dx=0.0, height=90.0):
        self.dx, self.h = dx, height

    def start(self, c, scene):
        super().start(c, scene)
        self.stage = "crouch"
        self.ground = c.y - _ground(scene, c.x)  # height above the terrain where we started
        if self.dx:
            c.face = 1 if self.dx > 0 else -1

    def update(self, c, dt, scene):
        self.t += dt
        if self.stage == "crouch" and self.t > 0.18:
            vy = math.sqrt(2 * G * self.h)
            self.vx = self.dx / (2 * vy / G)
            c.vy, c.y = vy, self.ground + 0.01
            self.stage = "air"
            scene.event("jump", c.x)
            scene.particles.dust(c.x, _ground(scene, c.x), 5, 0)
        elif self.stage == "air":
            c.x += self.vx * dt
            c.vy -= G * dt
            c.y += c.vy * dt
            gl = self.ground + _ground(scene, c.x)
            if c.y <= gl:
                c.y, c.vy = gl, 0
                c.squash = 0.24
                self.stage, self.t = "land", 0
                scene.event("land", c.x)
                scene.particles.dust(c.x, _ground(scene, c.x), 8, 0)
                scene.camera.shake(4)
        elif self.stage == "land" and self.t > 0.22:
            return True
        return False

    def pose(self, c):
        p = dict(STAND)
        if self.stage in ("crouch", "land"):
            k = 1 - ease(self.t / 0.22) if self.stage == "land" else ease(self.t / 0.18)
            p.update(thighF=0.75 * k, kneeF=1.5 * k, thighB=0.55 * k, kneeB=1.3 * k,
                     torso=0.32 * k, armUF=-0.8 * k, armUB=-1.0 * k, elbowF=0.3, elbowB=0.3)
        else:
            up = c.vy > 0
            p.update(thighF=0.9, kneeF=1.3 if up else 0.6, thighB=-0.2 if up else 0.3,
                     kneeB=0.9, torso=0.12, armUF=2.6 if up else 1.6, armUB=2.3 if up else 1.2,
                     elbowF=0.3, elbowB=0.3, head=-0.1)
        return p


class Kick(Action):
    def __init__(self, ball, power=700, lift=0.55):
        self.ball, self.power, self.lift = ball, power, lift
        self.duration = 0.5
        self.blend = 26.0

    def start(self, c, scene):
        super().start(c, scene)
        self.hit = False
        if self.ball:
            c.face = 1 if self.ball.x >= c.x else -1
            c.look_at = self.ball

    def update(self, c, dt, scene):
        self.t += dt
        if not self.hit and self.t > 0.22:
            self.hit = True
            b = self.ball
            if b and abs(b.x - (c.x + c.face * 35)) < 70 and b.y < 60:
                b.vx = c.face * self.power
                b.vy = self.power * self.lift
                b.spin = -c.face * 12
                b.squash = -0.35
                scene.event("kick", b.x)
                scene.particles.sparkle(b.x, b.y, 7)
                scene.camera.shake(6)
                c.smear = 0.12
        return self.t >= self.duration

    def pose(self, c):
        p = dict(STAND)
        t = self.t
        if t < 0.2:  # anticipation
            k = ease(t / 0.2)
            p.update(thighF=-0.8 * k, kneeF=1.3 * k, torso=-0.12 * k, armUF=1.0 * k, armUB=-0.7 * k)
        elif t < 0.3:  # action (fast)
            k = ease((t - 0.2) / 0.1)
            p.update(thighF=lerp(-0.8, 1.5, k), kneeF=lerp(1.3, 0.05, k), torso=-0.22,
                     armUF=lerp(1.0, -0.6, k), armUB=lerp(-0.7, 1.0, k))
        else:  # follow-through
            k = ease((t - 0.3) / 0.2)
            p.update(thighF=lerp(1.5, 0.05, k), kneeF=0.1, torso=lerp(-0.22, 0.03, k))
        return p


class Wave(Action):
    def __init__(self, d=1.2):
        self.duration = d

    def pose(self, c):
        p = Action.pose(self, c)
        if self.t < 0.14:  # anticipation: the arm dips before swinging up
            p.update(armUF=-0.3, elbowF=0.4, head=0.0)
            return p
        p.update(armUF=2.7, elbowF=0.5 + 0.45 * math.sin(self.t * 13), head=0.08)
        return p


class Point(Action):
    """Point forward, or at `target` (object or (x, y) world point) with arm IK."""

    def __init__(self, d=1.0, target=None):
        self.duration, self.target = d, target
        self.hand_target = ("point", target) if target is not None else None

    def start(self, c, scene):
        super().start(c, scene)
        if self.target is not None and hasattr(self.target, "x"):
            c.face = 1 if self.target.x >= c.x else -1
            c.look_at = self.target

    def pose(self, c):
        p = Action.pose(self, c)
        p.update(armUF=1.55, elbowF=0.0, torso=0.08)
        return p


class Think(Action):
    def __init__(self, d=1.5):
        self.duration = d

    def pose(self, c):
        p = Action.pose(self, c)
        p.update(armUF=0.55, elbowF=2.5, armUB=0.4, elbowB=1.6, head=-0.18 + 0.05 * math.sin(self.t * 3))
        return p


class Laugh(Action):
    def __init__(self, d=1.2):
        self.duration = d

    def pose(self, c):
        p = Action.pose(self, c)
        s = math.sin(self.t * 22)
        p.update(torso=0.15 + 0.06 * s, head=-0.3 + 0.08 * s, armUF=0.5, elbowF=1.9,
                 armUB=0.4, elbowB=1.9, hip=-3 + 2 * s)
        return p


class Cheer(Action):
    def __init__(self, d=1.6, hops=True):
        self.duration, self.hops = d, hops

    def start(self, c, scene):
        super().start(c, scene)
        self.n = 0
        self.base_y = c.y

    def update(self, c, dt, scene):
        self.t += dt
        if self.hops:
            c.y = self.base_y + 28 * abs(math.sin(self.t * 7))
            n = int(self.t * 7 / math.pi)
            if n != self.n:
                self.n = n
                scene.event("hop", c.x)
                c.squash = 0.12
        if self.t >= self.duration:
            c.y = self.base_y
            return True
        return False

    def pose(self, c):
        p = dict(STAND)
        w = math.sin(self.t * 14)
        p.update(armUF=2.9 + 0.15 * w, armUB=2.6 - 0.15 * w, elbowF=0.2, elbowB=0.2,
                 thighF=0.25, kneeF=0.5, thighB=-0.1, kneeB=0.5, head=-0.12)
        return p


class Dance(Action):
    def __init__(self, d=2.0):
        self.duration = d

    def pose(self, c):
        t = self.t * 8
        p = dict(STAND)
        s = math.sin(t)
        p.update(torso=0.12 * s, head=-0.15 * s, armUF=1.6 + 0.9 * s, elbowF=1.2,
                 armUB=1.6 - 0.9 * s, elbowB=1.2, thighF=0.3 * max(0, s), kneeF=0.6 * max(0, s),
                 thighB=0.3 * max(0, -s), kneeB=0.6 * max(0, -s), hip=-6 + 5 * abs(s))
        return p


class Slip(Action):
    """Comedic slip: feet fly up, land on the bottom, dizzy, get up."""
    duration = 1.9
    blend = 22.0

    def start(self, c, scene):
        super().start(c, scene)
        self.thud = False
        scene.event("slip", c.x)

    def update(self, c, dt, scene):
        self.t += dt
        if not self.thud and self.t > 0.28:
            self.thud = True
            c.squash = 0.2
            scene.event("thud", c.x)
            scene.particles.dust(c.x, _ground(scene, c.x), 10, 0)
            scene.camera.shake(7)
            c.emote("dizzy", scene.time, 1.1)
        return self.t >= self.duration

    def pose(self, c):
        t = self.t
        p = dict(STAND)
        fall = dict(torso=-1.15, head=0.25, thighF=1.5, kneeF=0.2, thighB=1.3, kneeB=0.4,
                    armUF=2.2, elbowF=0.6, armUB=2.6, elbowB=0.6, hip=-45)
        sit = dict(torso=-0.35, head=0.1, thighF=1.45, kneeF=0.3, thighB=1.4, kneeB=0.5,
                   armUF=-0.6, elbowF=0.2, armUB=-0.7, elbowB=0.2, hip=-58)
        if t < 0.28:
            k = ease(t / 0.28)
            for key in p:
                p[key] = lerp(STAND[key], fall[key], k)
        elif t < 1.35:
            k = ease((t - 0.28) / 0.2)
            for key in p:
                p[key] = lerp(fall[key], sit[key], k)
            p["head"] += 0.12 * math.sin(t * 9)
        else:
            k = ease((t - 1.35) / 0.55)
            for key in p:
                p[key] = lerp(sit[key], STAND[key], k)
        return p


# ---------------------------------------------------------------- motion library (#21)
def _hold(t, d, tin=0.3, tout=0.35):
    """0 -> 1 -> 0 envelope: ease in over tin, hold, ease out over the last tout seconds."""
    if d <= 0:
        return 1.0
    return ease(min(t / max(tin, 1e-6), (d - t) / max(tout, 1e-6), 1.0))


def _mix(a, b, k):
    return {key: lerp(a[key], b.get(key, a[key]), k) for key in a}


SIT_GROUND = dict(torso=-0.08, head=0.05, thighF=1.45, kneeF=0.35, thighB=1.4, kneeB=0.55,
                  armUF=-0.45, elbowF=0.15, armUB=-0.6, elbowB=0.15, hip=-12)


class Sit(Action):
    """Sit down for d seconds (ground, or on a seat of height `seat`), then stand up.
    d=None keeps sitting until the next action."""
    blend = 14.0

    def __init__(self, d=2.0, seat=0.0):
        self.d, self.seat = d, seat
        self.duration = d if d is not None else 0.6

    def start(self, c, scene):
        super().start(c, scene)
        c.squash = 0.06

    def update(self, c, dt, scene):
        self.t += dt
        if self.d is None:
            return False
        return self.t >= self.duration

    def target(self, c):
        if self.seat and self.seat > 8:  # chair: thighs level, shins down, hips at seat height
            ext = c.THIGH * math.cos(1.5) + c.SHIN * math.cos(0.0)
            return dict(STAND, torso=0.05, head=0.0, thighF=1.5, kneeF=1.5, thighB=1.45, kneeB=1.45,
                        armUF=0.6, elbowF=0.9, armUB=0.5, elbowB=0.9, hip=self.seat - ext)
        return dict(SIT_GROUND)

    def pose(self, c):
        base = Action.pose(self, c)
        k = _hold(self.t, self.duration if self.d is not None else 1e9, 0.35, 0.4)
        p = _mix(base, self.target(c), k)
        p["torso"] += 0.02 * math.sin(c.clock * 1.6)  # breathing while seated
        return p


class Sleep(Sit):
    """Doze off sitting, head drooping, slow breathing, 'z z' (sleepy expression)."""

    def __init__(self, d=3.0, seat=0.0):
        super().__init__(d, seat)

    def start(self, c, scene):
        super().start(c, scene)
        c.emote("sleepy", scene.time, (self.d or 4.0))

    def pose(self, c):
        p = Sit.pose(self, c)
        k = _hold(self.t, self.duration if self.d is not None else 1e9, 0.8, 0.4)
        s = math.sin(c.clock * 1.3)
        p["torso"] += k * (0.22 + 0.04 * s)
        p["head"] += k * (0.45 + 0.05 * s)
        p["armUF"] = lerp(p["armUF"], 0.15, k)
        p["armUB"] = lerp(p["armUB"], 0.05, k)
        return p


class Cry(Action):
    """Cry: hands to the eyes, shoulders shaking, streams of tears (expression 'crying')."""

    def __init__(self, d=2.0):
        self.duration = d

    def start(self, c, scene):
        super().start(c, scene)
        c.emote("crying", scene.time, self.duration + 0.4)

    def pose(self, c):
        p = Action.pose(self, c)
        k = _hold(self.t, self.duration, 0.3, 0.35)
        sob = math.sin(self.t * 24) * (0.5 + 0.5 * abs(math.sin(self.t * 2.3)))
        cry = dict(torso=0.18 + 0.035 * sob, head=0.32 + 0.04 * sob, armUF=0.62, elbowF=2.45,
                   armUB=0.5, elbowB=2.35, hip=-2 + 1.5 * sob)
        return _mix(p, cry, k)


class Clap(Action):
    """Applause: both hands meet in front, a 'clap' sound on every hit."""

    def __init__(self, d=1.5, rate=4.0):
        self.duration, self.rate = d, rate

    def start(self, c, scene):
        super().start(c, scene)
        self.n = 0

    def update(self, c, dt, scene):
        self.t += dt
        n = int(max(0.0, self.t - 0.2) * self.rate)
        if n != self.n and self.t < self.duration - 0.2:
            self.n = n
            scene.event("clap", c.x, gain=0.8)
        return self.t >= self.duration

    def pose(self, c):
        p = Action.pose(self, c)
        k = _hold(self.t, self.duration, 0.2, 0.25)
        ph = math.cos(max(0.0, self.t - 0.2) * self.rate * 2 * math.pi)  # 1 = hands together
        o = 0.22 * (1 - ph) / 2
        clap = dict(armUF=1.05 + o, elbowF=1.05 - o, armUB=1.05 - o, elbowB=1.1 + o, head=-0.08, torso=0.04)
        return _mix(p, clap, k)


class Stomp(Action):
    """Angry stomping: lift a foot (anticipation) and slam it down with dust + thud."""
    blend = 24.0

    def __init__(self, d=1.6, period=0.42):
        self.duration, self.period = d, period

    def start(self, c, scene):
        super().start(c, scene)
        self.hits = 0
        c.emote("angry", scene.time, self.duration + 0.3)

    def update(self, c, dt, scene):
        self.t += dt
        n = int(self.t / self.period)
        if (self.t % self.period) > self.period * 0.55 and n >= self.hits and self.t < self.duration - 0.1:
            self.hits = n + 1
            scene.event("thud", c.x, gain=0.55)
            scene.particles.dust(c.x + c.face * (12 if n % 2 == 0 else -6), _ground(scene, c.x), 5, 0)
            scene.camera.shake(3)
            c.squash = 0.1
        return self.t >= self.duration

    def pose(self, c):
        p = Action.pose(self, c)
        u = (self.t % self.period) / self.period
        n = int(self.t / self.period)
        lift = ease(u / 0.55) if u < 0.55 else max(0.0, 1 - (u - 0.55) / 0.12)
        leg_t, leg_k = ("thighF", "kneeF") if n % 2 == 0 else ("thighB", "kneeB")
        p.update(torso=0.12, head=0.1, armUF=-0.25, elbowF=1.7, armUB=-0.3, elbowB=1.7)
        p[leg_t] = 0.9 * lift
        p[leg_k] = 1.3 * lift
        return p


class Carry(Action):
    """Hold a prop (Ball or Box) in front with both arms for d seconds.
    To carry while walking use Character.carry(obj, t, d) instead (layered)."""

    def __init__(self, obj, d=2.0, drop=True):
        self.obj, self.duration, self.drop = obj, d, drop

    def start(self, c, scene):
        super().start(c, scene)
        c.carry(self.obj, scene.time, self.duration if self.drop else None)


class Push(Action):
    """Lean in and push with both arms; with obj (Box/Ball) both move forward slowly."""

    def __init__(self, d=2.0, obj=None, speed=45.0):
        self.duration, self.obj, self.speed = d, obj, speed

    def update(self, c, dt, scene):
        self.t += dt
        if self.obj is not None and 0.35 < self.t < self.duration - 0.2:
            step = c.face * self.speed * dt
            c.x += step
            self.obj.x = c.x + c.face * (getattr(self.obj, "w", 2 * getattr(self.obj, "r", 17)) / 2 + 38 * c.scale)
            c.phase += abs(step) / 60 * math.pi * 2
            if int(c.phase / math.pi) != int((c.phase - abs(step) / 60 * math.pi * 2) / math.pi):
                scene.event("step", c.x, gain=0.6)
        return self.t >= self.duration

    def pose(self, c):
        p = Action.pose(self, c)
        k = _hold(self.t, self.duration, 0.35, 0.3)
        s = math.sin(c.phase)
        push = dict(torso=0.48, head=-0.3, armUF=1.5, elbowF=0.2, armUB=1.45, elbowB=0.25,
                    thighF=0.45 + 0.2 * s, kneeF=0.7, thighB=-0.45 - 0.15 * s, kneeB=0.15, hip=-4)
        if self.t < 0.25:  # anticipation: crouch and pull back before the shove
            push = dict(push, torso=0.2, armUF=1.1, elbowF=1.0, armUB=1.0, elbowB=1.0, hip=-8)
        return _mix(p, push, k)


class Bow(Action):
    """Polite bow: small lean back (anticipation), bow down, hold, come back up."""

    def __init__(self, d=1.6):
        self.duration = d

    def pose(self, c):
        p = Action.pose(self, c)
        t, d = self.t, self.duration
        if t < 0.18:
            return _mix(p, dict(torso=-0.08), ease(t / 0.18))
        k = _hold(t - 0.18, d - 0.18, 0.35, 0.45)
        return _mix(p, dict(torso=0.95, head=0.35, armUF=0.35, elbowF=0.3, armUB=0.3, elbowB=0.3), k)


class Nod(Action):
    """Nod yes a few times."""

    def __init__(self, d=1.0, times=3):
        self.duration, self.times = d, times

    def pose(self, c):
        p = Action.pose(self, c)
        k = _hold(self.t, self.duration, 0.1, 0.15)
        p["head"] += k * 0.28 * abs(math.sin(self.t / self.duration * self.times * math.pi))
        return p


class HeadShake(Action):
    """Shake the head no: the eyes swing left/right with a small head wobble."""

    def __init__(self, d=1.0, times=3):
        self.duration, self.times = d, times

    def update(self, c, dt, scene):
        self.t += dt
        s = math.sin(self.t / self.duration * self.times * 2 * math.pi)
        c._look_override = (s, -0.05) if self.t < self.duration else None
        if self.t >= self.duration:
            c._look_override = None
            return True
        return False

    def pose(self, c):
        p = Action.pose(self, c)
        s = math.sin(self.t / self.duration * self.times * 2 * math.pi)
        p["head"] += 0.1 * s
        p["torso"] += 0.02 * s
        return p


class Facepalm(Action):
    """Raise the hand (anticipation), slap the forehead, hold, sigh."""

    def __init__(self, d=1.6):
        self.duration = d

    def start(self, c, scene):
        super().start(c, scene)
        self.hit = False

    def update(self, c, dt, scene):
        self.t += dt
        if not self.hit and self.t > 0.3:
            self.hit = True
            scene.event("clap", c.x, gain=0.5)
            c.squash = 0.05
        return self.t >= self.duration

    def pose(self, c):
        p = Action.pose(self, c)
        t = self.t
        if t < 0.25:
            return _mix(p, dict(armUF=1.4, elbowF=1.6, head=-0.1), ease(t / 0.25))
        k = _hold(t - 0.25, self.duration - 0.25, 0.06, 0.4)
        return _mix(p, dict(armUF=0.6, elbowF=2.6, head=0.32, torso=0.1), k)


class JumpSpin(Action):
    """Celebration: crouch, jump and spin (two quick facing flips) in the air, land."""

    def __init__(self, height=80.0):
        self.h = height

    def start(self, c, scene):
        super().start(c, scene)
        self.stage, self.ground, self.flips = "crouch", c.y, 0

    def update(self, c, dt, scene):
        self.t += dt
        if self.stage == "crouch" and self.t > 0.16:
            c.vy = math.sqrt(2 * G * self.h)
            self.air_t, self.stage = 2 * c.vy / G, "air"
            self.t0 = self.t
            scene.event("jump", c.x)
            scene.event("whoosh", c.x, gain=0.7)
        elif self.stage == "air":
            c.vy -= G * dt
            c.y += c.vy * dt
            f = (self.t - self.t0) / self.air_t
            if self.flips < 2 and f > (0.25 if self.flips == 0 else 0.6):
                self.flips += 1
                c.face = -c.face
                c.squash = -0.12
            if c.y <= self.ground:
                c.y, c.vy = self.ground, 0.0
                c.squash = 0.22
                self.stage, self.t = "land", 0.0
                scene.event("land", c.x)
                scene.particles.dust(c.x, _ground(scene, c.x), 6, 0)
        elif self.stage == "land" and self.t > 0.22:
            return True
        return False

    def pose(self, c):
        p = dict(STAND)
        if self.stage in ("crouch", "land"):
            k = ease(self.t / 0.16) if self.stage == "crouch" else 1 - ease(self.t / 0.22)
            p.update(thighF=0.7 * k, kneeF=1.4 * k, thighB=0.5 * k, kneeB=1.2 * k, torso=0.3 * k,
                     armUF=-0.6 * k, armUB=-0.8 * k)
        else:
            p.update(armUF=2.8, elbowF=0.3, armUB=2.6, elbowB=0.3, thighF=0.5, kneeF=1.0, thighB=0.2,
                     kneeB=1.0, head=-0.15)
        return p


class Throw(Action):
    """Wind up and throw `obj` (Ball or Prop) at `angle` degrees with `power` px/s.
    The object is put in the front hand for the wind-up, released at 0.28 s."""
    blend = 24.0

    def __init__(self, obj, power=520.0, angle=50.0, d=0.75, spin=8.0):
        self.obj, self.power, self.angle, self.duration, self.spin = obj, power, angle, d, spin

    def start(self, c, scene):
        super().start(c, scene)
        self.released = False
        c._held = self.obj
        self.obj.carried = True
        c.look_at = None

    def update(self, c, dt, scene):
        self.t += dt
        if not self.released and self.t >= 0.28:
            self.released = True
            o = self.obj
            c._held = None
            o.carried = False
            a = math.radians(self.angle)
            o.vx = c.face * self.power * math.cos(a)
            o.vy = self.power * math.sin(a)
            if hasattr(o, "omega"):
                o.omega = -c.face * self.spin
            if hasattr(o, "spin"):
                o.spin = -c.face * self.spin
            o._release = (o.x, o.y, o.vx, o.vy)
            scene.event("whoosh", c.x, gain=0.6)
        return self.t >= self.duration

    def pose(self, c):
        p = dict(STAND)
        t = self.t
        if t < 0.22:  # anticipation: arm back, lean back
            k = ease(t / 0.22)
            p.update(armUF=lerp(0.1, -1.1, k), elbowF=lerp(0.2, 1.2, k), torso=-0.12 * k,
                     thighF=0.25 * k, kneeF=0.3 * k, armUB=0.5 * k)
        elif t < 0.34:  # release
            k = ease((t - 0.22) / 0.12)
            p.update(armUF=lerp(-1.1, 2.2, k), elbowF=lerp(1.2, 0.1, k), torso=lerp(-0.12, 0.22, k),
                     armUB=lerp(0.5, -0.4, k))
        else:  # follow-through
            k = ease((t - 0.34) / max(0.05, self.duration - 0.34))
            p.update(armUF=lerp(2.2, 0.6, k), elbowF=lerp(0.1, 0.3, k), torso=lerp(0.22, 0.03, k))
        return p


class Catch(Action):
    """Reach for `obj` with the front hand (arm IK) and grab it when it comes within
    `reach`; the caught object is then held (carry) for `hold` seconds."""

    def __init__(self, obj, d=2.5, reach=55.0, hold=1.2):
        self.obj, self.duration, self.reach, self.hold = obj, d, reach, hold
        self.hand_target = ("reach", obj)

    def start(self, c, scene):
        super().start(c, scene)
        self.caught = False
        c.look_at = self.obj

    def update(self, c, dt, scene):
        self.t += dt
        o = self.obj
        if not self.caught and not getattr(o, "carried", False):
            hx, hy = c.hand_world(True)
            if math.hypot(o.x - hx, o.y - hy) < self.reach * c.scale:
                self.caught = True
                self.hand_target = None
                c.carry(o, scene.time, self.hold)
                scene.event("bounce", o.x, gain=0.35)
                c.squash = 0.06
                self.duration = min(self.duration, self.t + 0.4)
        if o.x != c.x and not self.caught:
            c.face = 1 if o.x >= c.x else -1
        return self.t >= self.duration


class Reach(Action):
    """Touch / reach toward an object or world point with the front hand (arm IK)."""

    def __init__(self, target, d=1.2):
        self.target, self.duration = target, d
        self.hand_target = ("reach", target)

    def start(self, c, scene):
        super().start(c, scene)
        tx = self.target.x if hasattr(self.target, "x") else self.target[0]
        if abs(tx - c.x) > 1:
            c.face = 1 if tx > c.x else -1

    def pose(self, c):
        p = Action.pose(self, c)
        p["torso"] += 0.12
        return p

# ---------------------------------------------------------------- head turns & keyframe poses
class FaceCamera(Action):
    """Turn the head to the audience (yaw 0) for d seconds while standing; the body keeps its
    profile. yaw: 0 front, 0.5 three-quarter, 1 profile, -1 looking back. hold=True keeps the
    head turned after the action (until another head key) and does not block the timeline."""

    def __init__(self, d=1.5, yaw=0.0, hold=False):
        self.d, self.yaw, self.hold = d, clamp(float(yaw), -1.0, 1.0), bool(hold)
        self.duration = 0.0 if (hold or d is None) else float(d)

    def start(self, c, scene):
        super().start(c, scene)
        c.turn_head(scene.time, self.yaw, None if (self.hold or self.d is None) else self.d)

    def pose(self, c):
        return c._idle_pose()


def _ease_out_back(t):
    c1 = 1.70158
    return 1 + (c1 + 1) * (t - 1) ** 3 + c1 * (t - 1) ** 2


def _ease_out_elastic(t):
    if t <= 0 or t >= 1:
        return clamp(t, 0, 1)
    return 2 ** (-10 * t) * math.sin((t * 10 - 0.75) * (2 * math.pi / 3)) + 1


EASES = {"linear": lambda t: t, "in_out": ease, "in": lambda t: t * t,
         "out": lambda t: 1 - (1 - t) ** 2, "out_back": _ease_out_back, "out_elastic": _ease_out_elastic}

POSE_KEYS = ("torso", "head", "thighF", "kneeF", "thighB", "kneeB", "armUF", "elbowF", "armUB", "elbowB", "hip")

# Full-body pose presets (#22), usable as Pose("victory") / {"preset": "victory"}.
# Angles in radians: 0 = limb straight down, + = forward / up in front; elbows & knees bend.
POSES = {
    "stand": dict(STAND),
    "thinking": dict(STAND, torso=0.05, head=-0.2, armUF=0.55, elbowF=2.5, armUB=-0.5, elbowB=2.2),
    "victory": dict(STAND, torso=-0.06, head=-0.18, armUF=2.75, elbowF=0.25, armUB=2.55, elbowB=0.3,
                    thighF=0.18, kneeF=0.05, thighB=-0.18, kneeB=0.05),
    "shy": dict(STAND, torso=0.14, head=0.32, armUF=0.32, elbowF=1.9, armUB=0.22, elbowB=1.95,
                thighF=0.12, kneeF=0.3, thighB=-0.02, kneeB=0.05),
    "superhero": dict(STAND, torso=-0.12, head=-0.12, armUF=-0.55, elbowF=2.25, armUB=-0.5, elbowB=2.2,
                      thighF=0.26, kneeF=0.04, thighB=-0.26, kneeB=0.04),
    "sit_cross": dict(STAND, torso=0.02, head=0.05, thighF=1.45, kneeF=2.75, thighB=1.35, kneeB=2.85,
                      armUF=0.55, elbowF=0.55, armUB=0.45, elbowB=0.6, hip=0.0),
    "point_up": dict(STAND, torso=-0.04, head=-0.3, armUF=3.0, elbowF=0.05, armUB=-0.25, elbowB=0.3),
    "cheer": dict(STAND, torso=-0.08, head=-0.15, armUF=2.4, elbowF=0.9, armUB=2.2, elbowB=0.9),
    "shrug": dict(STAND, head=0.15, armUF=0.35, elbowF=1.7, armUB=0.25, elbowB=1.7),
    "hands_hips": dict(STAND, torso=0.0, armUF=-0.55, elbowF=2.25, armUB=-0.5, elbowB=2.2),
    "bow": dict(STAND, torso=0.75, head=0.25, armUF=-0.1, elbowF=0.2, armUB=-0.2, elbowB=0.2),
    "kneel": dict(STAND, torso=0.05, thighF=1.4, kneeF=1.45, thighB=-0.2, kneeB=1.55, armUF=0.5, elbowF=0.6),
    "facepalm": dict(STAND, torso=0.1, head=0.28, armUF=0.6, elbowF=2.6),
    "run_pose": dict(STAND, torso=0.3, thighF=1.0, kneeF=1.2, thighB=-0.6, kneeB=1.4, armUF=-0.6,
                     elbowF=1.6, armUB=1.0, elbowB=1.4),
}


def _pose_key(k, default_t):
    """Normalise one key -> (t, partial pose, ease name, is_preset)."""
    if isinstance(k, str):
        k = {"preset": k}
    if isinstance(k, (tuple, list)):
        t, body = k[0], k[1]
        ez = k[2] if len(k) > 2 else None
        if isinstance(body, str):
            body = {"preset": body}
        k = dict(body, t=t)
        if ez:
            k["ease"] = ez
    k = dict(k)
    t = float(k.pop("t", default_t))
    ez = k.pop("ease", None)
    preset = k.pop("preset", None)
    body = dict(k.pop("pose", {}))
    body.update({j: v for j, v in k.items() if j in POSE_KEYS})
    if preset is not None:
        if preset not in POSES:
            raise ValueError(f"unknown pose preset {preset!r}; valid: {', '.join(sorted(POSES))}")
        full = dict(POSES[preset])
        full.update(body)
        return t, full, ez, True
    bad = [j for j in body if j not in POSE_KEYS]
    if bad:
        raise ValueError(f"unknown pose joint(s) {bad}; valid: {', '.join(POSE_KEYS)}")
    return t, body, ez, False


class Pose(Action):
    """Keyframed full-body pose (#22), blended from the current pose; leg IK is off meanwhile.
    keys: a preset name ("victory"), a pose dict ({"preset": "victory"} or joint angles), or a
      list of keys, each (t, pose_or_preset[, ease]) or {"t": .., "preset"|"pose"|joints.., "ease": ..}.
      Partial poses keep the joints of the previous key; presets start from STAND.
    d: total duration (None = last key time + hold).  loop: repeat the key cycle until d.
    ease: default easing - in_out | linear | out_back | out_elastic | in | out."""
    blend = 1000.0  # the keys are the motion: follow them exactly

    def __init__(self, keys, d=None, loop=False, ease="in_out", hold=0.8):
        if isinstance(keys, (str, dict)):
            keys = [keys]
        if ease not in EASES:
            raise ValueError(f"unknown ease {ease!r}; valid: {', '.join(EASES)}")
        self.ease, self.loop = ease, bool(loop)
        self.keys = []
        for i, k in enumerate(keys):
            t, body, ez, pre = _pose_key(k, 0.45 * (i + 1))
            ez = ez or ease
            if ez not in EASES:
                raise ValueError(f"unknown ease {ez!r}; valid: {', '.join(EASES)}")
            self.keys.append((t, body, ez, pre))
        self.keys.sort(key=lambda k: k[0])
        if not self.keys:
            raise ValueError("Pose needs at least one key")
        last = self.keys[-1][0]
        if d is None:
            d = last * 3 if (self.loop and last > 0) else last + hold
        self.d = self.duration = float(d)

    def start(self, c, scene):
        super().start(c, scene)
        cur = {j: c.pose.get(j, STAND.get(j, 0.0)) for j in POSE_KEYS}
        if c.pose.get("ik", 0) > 0.5:
            cur["hip"] = 0.0
        frames, prev = [(0.0, cur, "linear")], cur
        for t, body, ez, pre in self.keys:
            full = dict(STAND if pre else prev)
            full.update(body)
            full = {j: full.get(j, STAND.get(j, 0.0)) for j in POSE_KEYS}
            if t <= 0:
                frames[0] = (0.0, full, ez)
            else:
                frames.append((t, full, ez))
            prev = full
        self.frames = frames

    def target_at(self, tt):
        fr = self.frames
        if self.loop and fr[-1][0] > 0:
            period = fr[-1][0]
            cycle, tt = divmod(tt, period)
            if cycle >= 1:  # later cycles start from the last key, not the original pose
                fr = [(0.0, fr[-1][1], "linear")] + fr[1:]
        if tt >= fr[-1][0]:
            return dict(fr[-1][1])
        for (t0, a, _), (t1, b, ez) in zip(fr, fr[1:]):
            if t0 <= tt < t1:
                w = EASES[ez](clamp((tt - t0) / max(t1 - t0, 1e-6), 0, 1))
                return {j: a[j] + (b[j] - a[j]) * w for j in POSE_KEYS}
        return dict(fr[0][1])

    def pose(self, c):
        p = self.target_at(getattr(self, "t", 0.0))
        p["hip"] = p.get("hip", 0.0) + 0.8 * math.sin(c.clock * 2.2)  # keep a breath of life
        return p


# ---------------------------------------------------------------- motion library part 2 (#21), face (#33), ragdoll (#43)
STAND_H = 37 * math.cos(0.05) + 35 * math.cos(0.0)  # hip height of STAND for a standard rig (non-IK)


def _ground(scene, x):
    """Terrain height at x (0 when the scene is flat or has no ground_at)."""
    f = getattr(scene, "ground_at", None)
    return f(x) if f is not None else 0.0


def _stand_h(c):
    return max(c.leg_extent(STAND["thighF"], STAND["kneeF"]), c.leg_extent(STAND["thighB"], STAND["kneeB"]))


def _wrap(a):
    return (a + math.pi) % (2 * math.pi) - math.pi


def _loc(c, wx, wy, hip_h=None):
    """World point -> character-local (x forward, y down) for an upright (unrotated) body."""
    return ((wx - c.x) / (c.face * c.scale), -(wy - c.y) / c.scale)


def _ik_pose(c, P, hip_h, feet=None, hands=None):
    """Fill leg / arm angles of P so feet / hands reach local targets (two-bone IK)."""
    hip = (0.0, -hip_h)
    if feet:
        if feet[0] is not None:
            P["thighF"], P["kneeF"] = ik2(hip, feet[0], c.THIGH, c.SHIN)
        if feet[1] is not None:
            P["thighB"], P["kneeB"] = ik2(hip, feet[1], c.THIGH, c.SHIN)
    if hands and getattr(c, "style", "toon") not in ("quadruped", "bird"):
        sk = c._skeleton(dict(P, ik=1.0, hipIK=hip_h))
        if hands[0] is not None:
            P["armUF"], P["elbowF"] = arm_ik(sk["shoulderF"], hands[0], c.UARM, c.LARM)
        if hands[1] is not None:
            P["armUB"], P["elbowB"] = arm_ik(sk["shoulderB"], hands[1], c.UARM, c.LARM)
    return P


def _ik_mix(c, P, k, hip_h):
    """Blend STAND -> P by k with the hip height carried by the IK flag (seamless at k=0)."""
    out = _mix(dict(STAND), P, k)
    out["hip"] = -100
    out["hipIK"] = lerp(_stand_h(c), hip_h, k)
    return out


class Ladder:
    """Wooden ladder prop (scene extra). x: centre, y: foot (world, y up), height, rung spacing."""

    def __init__(self, x=0.0, height=260.0, spacing=28.0, width=36.0, color="#b9834f", y=0.0):
        self.x, self.y, self.height, self.spacing, self.width = float(x), float(y), float(height), float(spacing), width
        self.color = hex2rgb(color)

    def update(self, dt, scene):
        pass

    def draw(self, ctx, now):
        w, x0 = self.width, self.x
        top = self.y + self.height + self.spacing * 0.8
        ctx.save()
        ctx.set_line_cap(cairo.LINE_CAP_ROUND)
        n = int(self.height / self.spacing + 0.5)
        for i in range(1, n + 1):  # rungs
            yy = -(self.y + i * self.spacing)
            for lw, col in ((9, INK), (5, shade(self.color, 0.9))):
                ctx.move_to(x0 - w / 2, yy)
                ctx.line_to(x0 + w / 2, yy)
                ctx.set_line_width(lw)
                ctx.set_source_rgb(*col)
                ctx.stroke()
        for sx in (-w / 2, w / 2):  # rails
            for lw, col in ((11, INK), (6.5, self.color)):
                ctx.move_to(x0 + sx, -self.y + 2)
                ctx.line_to(x0 + sx, -top)
                ctx.set_line_width(lw)
                ctx.set_source_rgb(*col)
                ctx.stroke()
        ctx.restore()


class Bed:
    """Bed prop (scene extra) for SleepInBed: frame, mattress, pillow at the `head` end (-1 left /
    +1 right) and a blanket that covers the sleeper (draw_front) while `occupied`."""

    def __init__(self, x=0.0, w=210.0, h=44.0, head=-1, color="#8d5a3b", blanket="#5aa9e6",
                 pillow="#fff8e8", sheet="#f4f1ea", y=0.0):
        self.x, self.y, self.w, self.h, self.head = float(x), float(y), float(w), float(h), (1 if head > 0 else -1)
        self.color, self.blanket, self.pillow, self.sheet = (hex2rgb(color), hex2rgb(blanket),
                                                             hex2rgb(pillow), hex2rgb(sheet))
        self.occupied = 0.0  # 0..1 blanket pulled over the sleeper
        self.breath = 0.0

    def top(self):
        return self.y + self.h + 14.0

    def pillow_x(self):
        return self.x + self.head * (self.w / 2 - 34)

    def update(self, dt, scene):
        self.breath = math.sin(scene.time * 1.3 * 2 * math.pi / 2.6)

    @staticmethod
    def _ink(ctx, col, lw=3.0):
        ctx.set_source_rgb(*col)
        ctx.fill_preserve()
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(lw)
        ctx.stroke()

    def _rrect(self, ctx, x, y, w, h, r):
        r = min(r, w / 2, h / 2)
        ctx.new_sub_path()
        ctx.arc(x + w - r, y + r, r, -math.pi / 2, 0)
        ctx.arc(x + w - r, y + h - r, r, 0, math.pi / 2)
        ctx.arc(x + r, y + h - r, r, math.pi / 2, math.pi)
        ctx.arc(x + r, y + r, r, math.pi, 1.5 * math.pi)
        ctx.close_path()

    def draw(self, ctx, now):
        x0, w, y, h = self.x - self.w / 2, self.w, -self.y, self.h
        ctx.save()
        ctx.translate(self.x, y)
        ctx.scale(self.w * 0.55, 7)
        ctx.arc(0, 0, 1, 0, 2 * math.pi)
        ctx.restore()
        ctx.set_source_rgba(0, 0, 0, 0.16)
        ctx.fill()
        hx = self.x + self.head * (w / 2 - 4)
        fx = self.x - self.head * (w / 2 - 4)
        self._rrect(ctx, hx - 9, y - h - 78, 18, h + 78, 7)  # headboard
        self._ink(ctx, self.color)
        self._rrect(ctx, fx - 8, y - h - 30, 16, h + 30, 6)  # footboard
        self._ink(ctx, shade(self.color, 0.92))
        self._rrect(ctx, x0 + 6, y - h, w - 12, h - 8, 6)  # frame
        self._ink(ctx, self.color)
        self._rrect(ctx, x0 + 10, y - h - 16, w - 20, 22, 9)  # mattress
        self._ink(ctx, self.sheet, 2.6)
        px = self.pillow_x()
        ctx.save()
        ctx.translate(px, y - h - 20)
        ctx.scale(30, 13)
        ctx.arc(0, 0, 1, 0, 2 * math.pi)
        ctx.restore()
        self._ink(ctx, self.pillow, 2.6)
        if self.occupied < 0.5:  # folded blanket at the foot end
            bx = self.x - self.head * (w / 2 - 50)
            self._rrect(ctx, bx - 38, y - h - 26, 76, 16, 7)
            self._ink(ctx, self.blanket, 2.6)

    def draw_front(self, ctx, now):
        if self.occupied < 0.5:
            return
        w, y, h = self.w, -self.y, self.h
        a = clamp((self.occupied - 0.5) * 2, 0, 1)
        start = self.pillow_x() - self.head * 24   # blanket from the shoulders to the foot end
        end = self.x - self.head * (w / 2 - 12)
        xa, xb = min(start, end), max(start, end)
        bump = 3.0 * self.breath
        top = y - h - 64 - bump
        ctx.new_path()
        ctx.move_to(xa, y - h - 8)
        ctx.curve_to(xa - 4, top + 8, xa + 18, top, xa + 30, top)
        ctx.line_to(xb - 18, top + 6)
        ctx.curve_to(xb - 4, top + 6, xb + 4, top + 16, xb + 2, y - h - 8)
        ctx.line_to(xb + 4, y - h + 6)
        ctx.line_to(xa - 4, y - h + 6)
        ctx.close_path()
        ctx.set_source_rgba(*self.blanket, a)
        ctx.fill_preserve()
        ctx.set_source_rgba(*INK, a)
        ctx.set_line_width(3)
        ctx.stroke()
        hx = start - self.head * 12  # folded hem under the chin
        ctx.move_to(hx, top + 14)
        ctx.line_to(hx, y - h + 2)
        ctx.set_source_rgba(*shade(self.blanket, 0.75), a)
        ctx.set_line_width(4)
        ctx.stroke()


class Water:
    """Pond / sea strip (scene extra): deep water behind the characters and a translucent front
    layer with a wavy surface over them (draw_front), so swimmers look half under water.
    x0..x1: extent, y: surface (world, y up), depth: how far it goes down."""

    def __init__(self, x0=-300.0, x1=300.0, y=0.0, depth=160.0, color="#3d9be9", alpha=0.62):
        self.x0, self.x1, self.y, self.depth = float(x0), float(x1), float(y), float(depth)
        self.color, self.alpha = hex2rgb(color), alpha
        self._now = 0.0

    def contains(self, x):
        return self.x0 <= x <= self.x1

    def update(self, dt, scene):
        self._now = scene.time

    def _surface(self, ctx, now, k=1.0):
        n = max(8, int((self.x1 - self.x0) / 18))
        for i in range(n + 1):
            x = self.x0 + (self.x1 - self.x0) * i / n
            yy = -(self.y + k * (3.0 * math.sin(x * 0.045 + now * 3.1) + 1.5 * math.sin(x * 0.11 - now * 4.3)))
            ctx.line_to(x, yy) if i else ctx.move_to(x, yy)

    def draw(self, ctx, now):
        g = cairo.LinearGradient(0, -self.y, 0, -self.y + self.depth)
        g.add_color_stop_rgb(0, *self.color)
        g.add_color_stop_rgb(1, *shade(self.color, 0.55))
        self._rrect = None
        ctx.new_path()
        ctx.move_to(self.x0 - 10, -self.y + 4)
        ctx.curve_to(self.x0 - 4, -self.y + self.depth, self.x1 + 4, -self.y + self.depth, self.x1 + 10, -self.y + 4)
        ctx.close_path()
        ctx.set_source(g)
        ctx.fill_preserve()
        ctx.set_source_rgba(*INK, 0.6)
        ctx.set_line_width(3)
        ctx.stroke()

    def draw_front(self, ctx, now):
        ctx.save()
        ctx.new_path()
        self._surface(ctx, now)
        ctx.line_to(self.x1 + 10, -self.y + 4)
        ctx.curve_to(self.x1 + 4, -self.y + self.depth, self.x0 - 4, -self.y + self.depth, self.x0 - 10, -self.y + 4)
        ctx.close_path()
        ctx.set_source_rgba(*shade(self.color, 1.05), self.alpha)
        ctx.fill()
        ctx.new_path()
        self._surface(ctx, now)
        ctx.set_source_rgba(1, 1, 1, 0.85)
        ctx.set_line_width(3)
        ctx.set_line_cap(cairo.LINE_CAP_ROUND)
        ctx.stroke()
        ctx.restore()


class Climb(Action):
    """Climb a ladder / wall up (height > 0) or down (height < 0) with alternating hand and foot IK:
    the opposite hand and foot move one rung at a time while the body rises in surges.
    obj: a Ladder (snaps to it, uses its spacing and height); rungs: rungs to climb when no height;
    speed: rungs per second."""
    blend = 1000.0
    abs_y = True

    def __init__(self, height=None, rungs=8, speed=1.7, obj=None, spacing=28.0):
        self.height, self.rungs, self.speed, self.obj, self.spacing = height, rungs, float(speed), obj, float(spacing)

    def start(self, c, scene):
        super().start(c, scene)
        o = self.obj
        if o is not None:
            self.spacing = float(getattr(o, "spacing", self.spacing))
            c.face = 1 if o.x >= c.x else -1
            if self.height is None:
                self.height = getattr(o, "y", 0.0) + getattr(o, "height", self.rungs * self.spacing) - c.y
        if self.height is None:
            self.height = self.rungs * self.spacing
        self.dirn = 1 if self.height >= 0 else -1
        self.n = abs(self.height) / self.spacing
        self.y0, self.x0 = c.y, c.x
        s = c.scale
        rail = (getattr(o, "width", 36.0) / 2 - 4) if o is not None else 0.0
        self.lx = (o.x - c.face * rail) if o is not None else c.x + c.face * 18 * s  # rail the hands grab
        self.xt = (o.x - c.face * 30 * s) if o is not None else c.x
        self.climb_t = self.n / max(self.speed, 0.05)
        self.duration = self.climb_t + 0.5
        self.last = 0
        self.hip_h = 44.0

    def _prog(self):
        tp = clamp(self.t - 0.25, 0.0, self.climb_t)
        p = tp * self.speed
        i = math.floor(p)
        return min(self.n, i + ease(p - i))

    def update(self, c, dt, scene):
        self.t += dt
        k = ease(self.t / 0.25)
        pe = self._prog()
        c.y = self.y0 + self.dirn * pe * self.spacing
        c.x = lerp(self.x0, self.xt, k)
        c.vy = 0.0
        if int(pe) != self.last:
            self.last = int(pe)
            scene.event("step", c.x, gain=0.4)
        return self.t >= self.duration

    def _lev(self, u, o):
        q = u + o
        kk = math.floor(q)
        fr = q - kk
        return kk + (ease((fr - 0.55) / 0.45) if fr > 0.55 else 0.0), (fr > 0.55)

    def pose(self, c):
        if getattr(c, "style", "toon") in ("quadruped", "bird"):
            return Action.pose(self, c)
        sp, s, H = self.spacing, c.scale, self.hip_h
        u = (c.y - self.y0) / sp
        hb = round((H + 0.82 * c.TORSO + 18) / (sp / s)) * sp / s  # hand rest height (local units, on a rung)
        lx = (self.lx - c.x) * c.face / s
        feet, hands = [], []
        for o in (0.5, 0.0):  # front foot, back foot
            lv, mv = self._lev(u, o)
            fy = (self.y0 + lv * sp - c.y) / s
            feet.append((lx - 9 - (5 if mv else 0), -fy - 1))
        for o in (0.0, 0.5):  # front hand, back hand (opposite to the feet)
            lv, mv = self._lev(u, o)
            hy = (self.y0 + lv * sp - c.y) / s + hb
            hands.append((lx - 2 - (7 if mv else 0), -hy))
        P = dict(STAND, torso=0.1, head=-0.32)
        _ik_pose(c, P, H, feet, hands)
        k = _hold(self.t, self.duration, 0.25, 0.25)
        return _ik_mix(c, P, k, H)


class Swim(Action):
    """Front-crawl swimming: body tilted horizontal, alternating arm strokes with splashes, flutter
    kick and bobbing at the water line. x: where to swim to (None = d seconds forward), water: the
    surface height (world y, default the current height), speed px/s, rate strokes per second."""
    blend = 1000.0
    abs_y = True

    def __init__(self, x=None, d=None, speed=85.0, water=None, rate=1.1):
        self.x, self.d, self.speed, self.water, self.rate = x, d, float(speed), water, float(rate)

    def start(self, c, scene):
        super().start(c, scene)
        self.y0, self.x0 = c.y, c.x
        self.wy = float(self.water) if self.water is not None else c.y
        tx = self.x if self.x is not None else c.x + c.face * self.speed * (self.d or 3.0)
        self.tx = float(tx)
        if abs(self.tx - c.x) > 1:
            c.face = 1 if self.tx > c.x else -1
        self.duration = self.d if self.d is not None else abs(self.tx - c.x) / max(self.speed, 1) + 1.0
        self.ph = 0.0
        self.shadow = getattr(c, "draw_shadow", True)
        c.draw_shadow = False
        self.hip_h = 50.0

    def update(self, c, dt, scene):
        self.t += dt
        k = _hold(self.t, self.duration, 0.45, 0.45)
        if self.t > 0.3:
            step = self.speed * dt * clamp(k * 1.3, 0.2, 1.0)
            d = self.tx - c.x
            c.x = self.tx if abs(d) <= step else c.x + math.copysign(step, d)
        old = self.ph
        self.ph += 2 * math.pi * self.rate * dt
        s = c.scale
        c.body_rot = 1.3 * k + 0.05 * math.sin(self.ph) * k
        sy = self.wy - 12 * s - self.hip_h * s + 3 * s * math.sin(2 * self.ph)
        c.y = lerp(self.y0, sy, k) + 18 * s * math.sin(math.pi * k) * (1 - k)
        c.vy = 0.0
        # a hand enters the water once per half stroke (arm passes over the head)
        if k > 0.7 and int((old + math.pi / 2) / math.pi) != int((self.ph + math.pi / 2) / math.pi):
            hx, hy = c.hand_world(int((self.ph + math.pi / 2) / math.pi) % 2 == 0)
            scene.particles.splash(hx + c.face * 10 * s, self.wy, 7, 0.45)
            scene.event("splash", hx, gain=0.3)
        if self.t >= self.duration:
            c.body_rot, c.y = 0.0, self.y0
            c.draw_shadow = self.shadow
            for key in ("armUF", "armUB"):
                c.pose[key] = _wrap(c.pose[key])
            return True
        return False

    def pose(self, c):
        ph = self.ph
        k = _hold(self.t, self.duration, 0.45, 0.45)
        a = -(ph % (2 * math.pi))           # arm angle: back -> up (air) -> over the head -> pull under
        b = -((ph + math.pi) % (2 * math.pi))
        el = lambda x: 0.25 + 0.9 * max(0.0, math.sin(-x))  # high elbow while recovering in the air
        kick = math.sin(ph * 3.2)
        P = dict(STAND, torso=0.0, head=-1.05 + 0.08 * math.sin(2 * ph),
                 armUF=a, elbowF=el(a), armUB=b, elbowB=el(b),
                 thighF=-0.05 + 0.22 * kick, kneeF=0.25 + 0.15 * max(0, kick),
                 thighB=-0.05 - 0.22 * kick, kneeB=0.25 + 0.15 * max(0, -kick))
        if k < 0.999:  # entering / leaving: take the short way round to the standing arm angles
            for key in ("armUF", "armUB"):
                P[key] = STAND[key] + _wrap(P[key] - STAND[key])
        return _ik_mix(c, P, k, self.hip_h)


class Ride(Action):
    """Sit on a moving anchor object (vehicle, animal, swing...): any object with x, y (world, y up)
    and optional seat=(dx, dy) / grip=(dx, dy) world offsets (already including its facing),
    pedal_phase (rad, feet circle on pedals), pedal=(dx, dy), pedal_r, footrest=(dx, dy) and face.
    Hands go to the grip, feet to pedals / footrest. d=None rides until the end of the scene."""
    blend = 1000.0
    abs_y = True

    def __init__(self, obj, d=None, lean=None):
        self.obj, self.d, self.lean = obj, d, lean
        self.duration = d if d is not None else 1e9

    def start(self, c, scene):
        super().start(c, scene)
        self.x0, self.y0 = c.x, c.y
        self.shadow = getattr(c, "draw_shadow", True)
        self.hip_h = 34.0

    def _pt(self, name, default):
        o = self.obj
        v = getattr(o, name, None)
        if callable(v):
            v = v()
        px, py = getattr(self, "_pred", (0.0, 0.0))  # the anchor updates after us: extrapolate one step
        v = default if v is None else v
        return (o.x + px + v[0], o.y + py + v[1])

    def _anchors(self, c):
        o, s = self.obj, c.scale
        fa = getattr(o, "face", c.face) or c.face
        fa = 1 if fa > 0 else -1
        seat = self._pt("seat", (0.0, 40 * s))
        sdx, sdy = seat[0] - o.x, seat[1] - o.y
        grip = self._pt("grip", (sdx + fa * 38 * s, sdy + 36 * s))
        ph = getattr(o, "pedal_phase", None)
        if ph is not None:
            cx, cy = self._pt("pedal", (sdx + fa * 10 * s, sdy - 46 * s))
            r = getattr(o, "pedal_r", 13.0) * s
            feet = [(cx + fa * r * math.cos(ph), cy + r * math.sin(ph)),
                    (cx - fa * r * math.cos(ph), cy - r * math.sin(ph))]
        else:
            f = self._pt("footrest", (sdx + fa * 22 * s, sdy - 40 * s))
            feet = [f, (f[0] - fa * 6 * s, f[1])]
        return fa, seat, grip, feet

    def update(self, c, dt, scene):
        self.t += dt
        o = self.obj
        last = getattr(self, "_last", None)
        self._pred = (o.x - last[0], o.y - last[1]) if last is not None else (0.0, 0.0)
        self._last = (o.x, o.y)
        fa, seat, _, _ = self._anchors(c)
        c.face = fa
        k = _hold(self.t, self.duration, 0.35, 0.35) if self.d is not None else ease(self.t / 0.35)
        tx, ty = seat[0], seat[1] - self.hip_h * c.scale
        if self.d is not None and self.t > self.duration - 0.35:  # dismount next to the vehicle
            gx = self.x1 if hasattr(self, "x1") else None
            if gx is None:
                self.x1 = tx - fa * 46 * c.scale
            c.x = lerp(self.x1, tx, k)
            c.y = lerp(_ground(scene, self.x1), ty, k) + 40 * c.scale * math.sin(math.pi * k) * (1 - k)
        else:
            c.x = lerp(self.x0, tx, k)
            c.y = lerp(self.y0, ty, k) + 40 * c.scale * math.sin(math.pi * k) * (1 - k)
        c.vy = 0.0
        c.draw_shadow = self.shadow if k < 0.3 else False
        if self.t >= self.duration:
            c.draw_shadow = self.shadow
            return True
        return False

    def pose(self, c):
        if getattr(c, "style", "toon") in ("quadruped", "bird"):
            return Action.pose(self, c)
        fa, seat, grip, feet = self._anchors(c)
        s, H = c.scale, self.hip_h
        oy = seat[1] - H * s  # where the body origin sits once mounted (pose uses mounted geometry)
        L = lambda w: ((w[0] - seat[0]) * c.face / s, -(w[1] - oy) / s)
        g = L(grip)
        lean = self.lean if self.lean is not None else clamp(math.atan2(g[0], H + 0.82 * c.TORSO - (-g[1])) * 0.6
                                                             - 0.05, -0.15, 0.75)
        P = dict(STAND, torso=lean, head=-0.12 - 0.5 * max(0.0, lean - 0.2))
        _ik_pose(c, P, H, [L(feet[0]), L(feet[1])], [g, (g[0] - 3, g[1] + 1)])
        k = _hold(self.t, self.duration, 0.35, 0.35) if self.d is not None else ease(self.t / 0.35)
        return _ik_mix(c, P, k, H)


class SleepInBed(Sleep):
    """Get into bed (obj: a Bed, or lie down on the spot), lie on the back with slow breathing,
    closed eyes (face lids) and rising 'Z' particles, then get up after d seconds."""
    blend = 1000.0
    abs_y = True

    def __init__(self, d=4.0, obj=None):
        super().__init__(d, 0.0)
        self.obj = obj

    def start(self, c, scene):
        Action.start(self, c, scene)
        self.duration = self.d if self.d is not None else 1e9
        o, s = self.obj, c.scale
        self.x0, self.y0, self.f0 = c.x, c.y, c.face
        self.hip_h = 40.0
        lift = 20 * s - self.hip_h * s
        if o is not None:
            c.face = -getattr(o, "head", -1)  # lying on the back puts the head behind the facing
            surf = o.top() if hasattr(o, "top") else getattr(o, "y", 0.0) + getattr(o, "h", 40.0)
            head_off = (c.TORSO + c.head_r - 6) * s
            self.hx = o.pillow_x() + c.face * head_off if hasattr(o, "pillow_x") else o.x
        else:
            surf = c.y
            self.hx = c.x
        self.ly = surf + lift
        self.shadow = getattr(c, "draw_shadow", True)
        if o is not None:
            c.draw_shadow = False
        t = scene.time
        c.face(t + 0.5, 0.5, lids=1.0, mouth_curve=0.15)
        if self.d is not None:
            c.face(t + self.d - 0.7, 0.35, lids=0.0, mouth_curve=0.0)
        self.zt = 1.0

    def _k(self):
        return _hold(self.t, self.duration, 0.6, 0.6)

    def update(self, c, dt, scene):
        self.t += dt
        k = self._k()
        c.body_rot = -math.pi / 2 * k
        c.x = lerp(self.x0, self.hx, k)
        c.y = lerp(self.y0, self.ly, k) + 34 * c.scale * math.sin(math.pi * min(1.0, k))  * (1 - k)
        c.vy = 0.0
        if self.obj is not None and hasattr(self.obj, "occupied"):
            self.obj.occupied = clamp((k - 0.5) * 2 + 0.5, 0.0, 1.0) if k > 0.5 else 0.0
        if k > 0.95:
            self.zt += dt
            if self.zt > 1.2:
                self.zt = 0.0
                sk = c._skeleton()
                if sk is not None:
                    hx, hy = c.to_world(sk["head"])
                    scene.particles.zzz(hx, hy + c.head_r * c.scale * 0.6)
        if self.t >= self.duration:
            c.body_rot, c.x, c.y = 0.0, self.x0, self.y0
            c.face = self.f0
            c.draw_shadow = self.shadow
            if self.obj is not None and hasattr(self.obj, "occupied"):
                self.obj.occupied = 0.0
            return True
        return False

    def pose(self, c):
        k = self._k()
        b = math.sin(c.clock * 2 * math.pi / 2.6)
        lie = dict(STAND, torso=0.015 * b, head=-0.2 + 0.02 * b, thighF=0.04, kneeF=0.06, thighB=-0.02,
                   kneeB=0.1, armUF=0.06 + 0.02 * b, elbowF=0.2, armUB=0.0, elbowB=0.15)
        out = _ik_mix(c, lie, k, self.hip_h)
        return out


class Eat(Action):
    """Eat: hand-to-mouth bites (mouth opens wide, 'chomp'), chewing mouth shapes between bites.
    obj: optional Prop held in the front hand (gets bite marks; finish=True: eaten at the end)."""

    def __init__(self, d=2.4, obj=None, bites=None, finish=True):
        self.duration, self.obj, self.finish = float(d), obj, finish
        self.bites = bites
        self.hand_target = None

    def start(self, c, scene):
        super().start(c, scene)
        self.n = int(self.bites or max(1, round(self.duration / 1.1)))
        self.period = max(0.5, (self.duration - 0.3) / self.n)
        self.done = 0
        o = self.obj
        if o is not None:
            c._held = o
            o.carried = True
            o.rot = 0.0
            o.bites = getattr(o, "bites", 0)
            o.bite_side = -c.face
        c.look_at = None

    def _mouth_world(self, c):
        sk = c._skeleton()
        if sk is None:
            return c.x + c.face * 40 * c.scale, c.y + 60 * c.scale
        hd, hr = sk["head"], sk["head_r"]
        if getattr(c, "style", "toon") == "blob":
            r = hr * 0.62
            loc = (hd[0] + 0.33 * r - 4, hd[1] + 0.14 * hr + 6)
        else:
            loc = (hd[0] + 0.48 * hr - 6, hd[1] + 0.42 * hr + 8)
        return c.to_world(loc)

    def update(self, c, dt, scene):
        self.t += dt
        t, P = self.t - 0.3, self.period
        sk = c._skeleton()
        if t < 0:
            u = -1.0
        else:
            u = (t % P) / P
        n = int(t / P) if t >= 0 else -1
        mx, my = self._mouth_world(c)
        if sk is not None:
            hip = c.to_world(sk["hip"])
            rest = (c.x + c.face * 30 * c.scale, hip[1] + 32 * c.scale)
        else:
            rest = (mx, my)
        if 0 <= n < self.n and u < 0.5:
            w = ease(u / 0.3) if u < 0.3 else 1 - ease((u - 0.36) / 0.14) if u > 0.36 else 1.0
        else:
            w = 0.0
        self.hand_target = ("reach", (lerp(rest[0], mx, w), lerp(rest[1], my, w)))
        if 0 <= n < self.n and n >= self.done and u >= 0.3:
            self.done = n + 1
            scene.event("chomp", c.x, gain=0.8)
            c.squash = 0.04
            if self.obj is not None:
                self.obj.bites = min(4, getattr(self.obj, "bites", 0) + 1)
        # mouth: open wide before the bite, then chew (A/B/C/A...) until the next one
        if 0 <= n < self.n and 0.15 < u < 0.3:
            c._mouth_override = "D"
        elif n >= 0 and (n < self.n and u >= 0.3 or n >= self.n and t - self.n * P < 0.8) and self.t < self.duration - 0.1:
            c._mouth_override = "ABCB"[int(self.t * 9) % 4]
        else:
            c._mouth_override = None
        if self.t >= self.duration:
            c._mouth_override = None
            self.hand_target = None
            o = self.obj
            if o is not None:
                c._held = None
                o.carried = False
                if self.finish:
                    o.hidden = True
                    scene.event("pop", c.x, gain=0.3)
                else:
                    o.vx, o.vy = 0.0, 0.0
            return True
        return False

    def pose(self, c):
        p = Action.pose(self, c)
        t = self.t - 0.3
        u = (t % self.period) / self.period if t >= 0 else 0.0
        chew = 0.03 * math.sin(self.t * 18) if t >= 0 else 0.0
        p["head"] += (0.1 * math.sin(math.pi * u / 0.5) if u < 0.5 else 0.0) + chew - 0.04
        p["torso"] += 0.04
        p["armUB"], p["elbowB"] = 0.35, 1.2
        return p


FACE_CHANNELS = ("brow_l", "brow_r", "brow_angle", "lid_l", "lid_r", "cheek", "mouth_curve")
FACE_ALIASES = {"brows": ("brow_l", "brow_r"), "lids": ("lid_l", "lid_r")}


def _face_channels(kw):
    out = {}
    for k, v in kw.items():
        if k in FACE_ALIASES:
            for kk in FACE_ALIASES[k]:
                out[kk] = float(v)
        elif k in FACE_CHANNELS:
            out[k] = float(v)
        else:
            raise ValueError(f"unknown face channel {k!r}; valid: {', '.join(FACE_CHANNELS + tuple(FACE_ALIASES))}")
    return out


class Face(Action):
    """Keyframed face puppet curves (#33), layered over whatever the body does.
    keys: [{"t": 0.0, "brow_l": 0.6, "lids": 0.3, "d": 0.3}, ...] (t relative to the action start,
    d = transition seconds, default `fade`). Channels: brow_l, brow_r (-1 low .. +1 raised),
    brow_angle (-1 worried .. +1 angry), lid_l, lid_r (0 open .. 1 closed), cheek (0..1 squint/smile
    lift), mouth_curve (-1 frown .. +1 smile); aliases brows, lids. Values hold until changed.
    d: how long the action blocks the timeline (default 0 = does not block)."""

    def __init__(self, keys, d=0.0, fade=0.25):
        if isinstance(keys, dict):
            keys = [keys]
        self.keys = []
        for i, k in enumerate(keys):
            k = dict(k)
            t = float(k.pop("t", 0.0))
            dd = float(k.pop("d", fade))
            self.keys.append((t, dd, _face_channels(k)))
        self.duration = float(d or 0.0)

    def start(self, c, scene):
        super().start(c, scene)
        for t, dd, ch in self.keys:
            c.face(scene.time + t, dd, **ch)

    def pose(self, c):
        return c._idle_pose()


class Tumble(Action):
    """Ragdoll-lite fall (#43): a small position-based-dynamics ragdoll (hip, neck, head, hands,
    feet) thrown by an impulse tumbles under gravity, hits the ground (terrain, box tops) with thud
    sounds and dust, lies for `lie` s, then blends back to standing over `getup` s.
    direction: forward | back | left | right | +1 | -1 (world x); strength ~0.3..2."""
    blend = 1000.0
    abs_y = True
    NAMES = ("hip", "neck", "head", "handF", "handB", "footF", "footB")

    def __init__(self, direction="forward", strength=1.0, lie=0.6, getup=0.55, max_time=2.6, seed=0):
        self.direction, self.strength = direction, float(strength)
        self.lie, self.getup, self.max_time, self.seed = float(lie), float(getup), float(max_time), seed

    def _dir(self, c):
        d = self.direction
        if isinstance(d, str):
            d = {"forward": c.face, "back": -c.face, "backward": -c.face, "left": -1, "right": 1}.get(d)
            if d is None:
                raise ValueError("Tumble direction must be forward, back, left, right, 1 or -1")
        return 1 if d >= 0 else -1

    def start(self, c, scene):
        super().start(c, scene)
        s = c.scale
        self.H0 = _stand_h(c)
        sk = c._skeleton()
        P = getattr(c, "dpose", None) or c.pose
        if sk is None:  # animals: rigid body only
            sk = dict(hip=(0, -35), neck=(30, -55), head=(48, -70), handF=(30, -30), handB=(-25, -30), head_r=c.head_r)
            feet = [(25, 0), (-25, 0)]
        else:
            hip = sk["hip"]

            def foot(th, kn):
                j = (hip[0] + c.THIGH * math.sin(th), hip[1] + c.THIGH * math.cos(th))
                return (j[0] + c.SHIN * math.sin(th - kn), j[1] + c.SHIN * math.cos(th - kn))
            feet = [foot(P["thighF"], P["kneeF"]), foot(P["thighB"], P["kneeB"])]
        loc = [sk["hip"], sk["neck"], sk["head"], sk["handF"], sk["handB"], feet[0], feet[1]]
        self.p = [list(c.to_world(q)) for q in loc]
        dx, S = self._dir(c), self.strength
        rng = random.Random(self.seed)
        top = (0.0, 1.0, 1.15, 0.9, 0.9, -0.55, -0.55)
        self.v = [[c.vx * 0.7 + dx * S * (230 + 260 * w) + rng.uniform(-15, 15),
                   S * (300 + 140 * max(0.0, w)) + rng.uniform(-15, 15)] for w in top]
        hr = sk.get("head_r", c.head_r) if isinstance(sk, dict) else c.head_r
        L = lambda a, b: math.hypot(loc[a][0] - loc[b][0], loc[a][1] - loc[b][1]) * s
        self.rigid = [(0, 1, L(0, 1)), (1, 2, L(1, 2)), (0, 2, L(0, 2), 0.35)]
        arm, leg = (c.UARM + c.LARM) * s, (c.THIGH + c.SHIN) * s
        self.ranges = [(1, 3, 0.35 * arm, arm), (1, 4, 0.35 * arm, arm), (0, 5, 0.5 * leg, leg), (0, 6, 0.5 * leg, leg),
                       (3, 4, 10 * s, 2.2 * arm), (5, 6, 8 * s, 1.6 * leg)]
        br = (18 if getattr(c, "style", "toon") != "blob" else hr * 1.3) * s
        self.rad = [br, br * 0.9, hr * s * 0.85, 7 * s, 7 * s, 7 * s, 7 * s]
        self.stage, self.still, self.cool, self.hits = "fly", 0.0, 0.0, 0
        self.rot0 = 0.0
        self.shadow = getattr(c, "draw_shadow", True)
        scene.event("whoosh", c.x, gain=0.55)
        c.emote("surprised", scene.time, 0.7)
        self._apply(c, scene)

    def _floor(self, scene, x, prev_y):
        f = _ground(scene, x)
        for b in getattr(scene, "boxes", ()):
            top = getattr(b, "y", 0.0) + b.h
            if abs(x - b.x) < b.w / 2 and prev_y >= top - 4 and top > f:
                f = top
        return f

    def _sim(self, c, scene, dt):
        n = max(1, int(math.ceil(dt / (1 / 120))))
        h = dt / n
        p, v = self.p, self.v
        for _ in range(n):
            prev = [list(q) for q in p]
            for q, vv in zip(p, v):
                vv[1] -= G * 0.85 * h
                q[0] += vv[0] * h
                q[1] += vv[1] * h
            impact = 0.0
            for _it in range(6):
                for item in self.rigid:
                    a, b, L = item[:3]
                    w = item[3] if len(item) > 3 else 1.0
                    self._dist(a, b, L, L, w)
                for a, b, lo, hi in self.ranges:
                    self._dist(a, b, lo, hi, 1.0)
                for i, q in enumerate(p):
                    fl = self._floor(scene, q[0], prev[i][1] - self.rad[i]) + self.rad[i]
                    if q[1] < fl:
                        if _it == 0 and i <= 2:
                            impact = max(impact, -v[i][1])
                        q[1] = fl
                        q[0] = lerp(q[0], prev[i][0], 0.45)  # friction
            for i, q in enumerate(p):
                nvx, nvy = (q[0] - prev[i][0]) / h, (q[1] - prev[i][1]) / h
                fl = self._floor(scene, q[0], q[1]) + self.rad[i]
                if q[1] <= fl + 0.5 and v[i][1] < -260:  # small bounce on hard impacts
                    nvy = -v[i][1] * 0.22
                v[i][0], v[i][1] = nvx * (1 - 0.4 * h), nvy * (1 - 0.4 * h)
            if impact > 230 and self.cool <= 0:
                self.cool = 0.14
                self.hits += 1
                g = min(1.0, impact / 900)
                x = p[0][0]
                scene.event("thud", x, gain=0.35 + 0.65 * g)
                scene.particles.dust(x, _ground(scene, x), int(4 + 8 * g), 0)
                if self.hits == 1:
                    scene.camera.shake(3 + 6 * g)
                    c.squash = 0.08
            self.cool -= h

    def _dist(self, a, b, lo, hi, w):
        p = self.p
        dx, dy = p[b][0] - p[a][0], p[b][1] - p[a][1]
        d = math.hypot(dx, dy) or 1e-6
        tgt = clamp(d, lo, hi)
        if tgt == d:
            return
        k = (d - tgt) / d * 0.5 * w
        p[a][0] += dx * k
        p[a][1] += dy * k
        p[b][0] -= dx * k
        p[b][1] -= dy * k

    def _map(self, c):
        """Ragdoll points -> (body rotation, joint angles) of the rig."""
        s, f = c.scale, c.face
        H, N, Hd, hF, hB, fF, fB = self.p
        rot = math.atan2(f * (N[0] - H[0]), N[1] - H[1])
        cr, sr = math.cos(rot), math.sin(rot)
        hip = (0.0, -self.H0)

        def loc(q):
            rx, ry = (q[0] - H[0]) * f, -(q[1] - H[1])
            return (hip[0] + (rx * cr + ry * sr) / s, hip[1] + (-rx * sr + ry * cr) / s)
        P = dict(STAND, torso=0.0)
        if getattr(c, "style", "toon") in ("quadruped", "bird"):
            return rot, P
        _ik_pose(c, P, self.H0, [loc(fF), loc(fB)], [loc(hF), loc(hB)])
        n, hd = loc(N), loc(Hd)
        P["head"] = clamp(math.atan2(hd[0] - n[0], -(hd[1] - n[1])), -1.0, 1.0) * 0.8
        return rot, P

    def _apply(self, c, scene):
        rot, P = self._map(c)
        H = self.p[0]
        c.body_rot = rot
        c.x = H[0]
        c.y = H[1] - self.H0 * c.scale
        c.vy = 0.0
        self.P = P

    def update(self, c, dt, scene):
        self.t += dt
        if self.stage == "fly":
            self._sim(c, scene, dt)
            self._apply(c, scene)
            sp = max(math.hypot(*vv) for vv in self.v)
            self.still = self.still + dt if sp < 45 else 0.0
            if (self.still > 0.2 and self.t > 0.6) or self.t > self.max_time:
                self.stage, self.t1 = "lie", self.t
                if self.strength >= 0.8:
                    c.emote("dizzy", scene.time, self.lie + self.getup * 0.6)
        elif self.stage == "lie" and self.t - self.t1 >= self.lie:
            self.stage, self.t2 = "up", self.t
            self.rot0, self.Pl = _wrap(c.body_rot), dict(self.P)
            self.xl, self.yl = c.x, c.y
            self.ye = self._floor(scene, c.x, c.y + 400)
            scene.event("hop", c.x, gain=0.6)
        if self.stage == "up":
            w = ease((self.t - self.t2) / self.getup)
            c.body_rot = self.rot0 * (1 - w)
            c.y = lerp(self.yl, self.ye, w) + 30 * c.scale * math.sin(math.pi * w)
            self.P = _mix(self.Pl, dict(STAND), w)
            if w >= 1.0:
                c.body_rot, c.y = 0.0, self.ye
                c.squash = 0.12
                return True
        return False

    def pose(self, c):
        P = dict(self.P)
        P["hip"] = -100
        P["hipIK"] = self.H0
        return P


class Fall(Tumble):
    """Simple fall over (Tumble with a softer default impulse)."""

    def __init__(self, direction="forward", strength=0.6, lie=0.8, getup=0.6, max_time=2.4, seed=0):
        super().__init__(direction, strength, lie, getup, max_time, seed)


# Name -> action class, for JSON/script front-ends (toonscript).  Constructor parameters:
#   wait(d) turn(face) look(target, face=True) move(x, gait="walk", speed=None)
#   chase(obj, gait="run", reach=38, timeout=8) jump(dx=0, height=90) kick(ball, power=700, lift=0.55)
#   wave(d) point(d) think(d) laugh(d) cheer(d, hops=True) dance(d) slip()
#   sit(d=2, seat=0) sleep(d=3, seat=0) cry(d=2) clap(d=1.5, rate=4) stomp(d=1.6, period=0.42)
#   carry(obj, d=2, drop=True) push(d=2, obj=None, speed=45) bow(d=1.6) nod(d=1, times=3)
#   headshake(d=1, times=3) facepalm(d=1.6) jumpspin(height=80)
#   point(d, target=None)  throw(obj, power=520, angle=50, d=0.75, spin=8)
#   catch(obj, d=2.5, reach=55, hold=1.2)  reach(target, d=1.2)
#   pose(keys, d=None, loop=False, ease="in_out", hold=0.8)   keys: preset name / dict / key list (POSES)
#   facecamera(d=1.5, yaw=0.0, hold=False)
#   climb(height=None, rungs=8, speed=1.7, obj=None, spacing=28)   obj: Ladder
#   swim(x=None, d=None, speed=85, water=None, rate=1.1)   ride(obj, d=None, lean=None)
#   sleepinbed(d=4, obj=None)  obj: Bed     eat(d=2.4, obj=None, bites=None, finish=True)
#   face(keys, d=0, fade=0.25)  keys: [{t, brow_l, brow_r, brow_angle, lid_l, lid_r, cheek, mouth_curve, d}]
#   tumble(direction="forward", strength=1, lie=0.6, getup=0.55, max_time=2.6, seed=0)  fall(...)
ACTIONS = {}


def _register_actions():
    ACTIONS.update(wait=Wait, turn=Turn, look=Look, move=MoveTo, chase=Chase, jump=Jump, kick=Kick,
                   wave=Wave, point=Point, think=Think, laugh=Laugh, cheer=Cheer, dance=Dance, slip=Slip,
                   sit=Sit, sleep=Sleep, cry=Cry, clap=Clap, stomp=Stomp, carry=Carry, push=Push, bow=Bow,
                   nod=Nod, headshake=HeadShake, facepalm=Facepalm, jumpspin=JumpSpin, throw=Throw,
                   catch=Catch, reach=Reach, pose=Pose, facecamera=FaceCamera,
                   climb=Climb, swim=Swim, ride=Ride, sleepinbed=SleepInBed, sleep_in_bed=SleepInBed, eat=Eat,
                   face=Face, tumble=Tumble, fall=Fall)


_register_actions()


# ---------------------------------------------------------------- smart bones (#4), paper flips (#58),
# view sets (#5), FFD deform (#7), line boil (#71)
PAPER_FLIP_D, PAPER_FLIP_MIN = 0.34, 0.05   # paper turn: duration (s), thinnest x scale
VIEW_FLIP_D, VIEW_FLIP_MIN = 0.28, 0.45     # view change: duration, x squash at the swap
VIEWS = ("side", "front", "back")
POSE_KEYS = tuple(STAND.keys())             # torso head thighF kneeF thighB kneeB armUF elbowF armUB elbowB hip
# extra dial channels: yaw (added to the head-yaw target), eye_x / eye_y (gaze shift), twist (px: front
# shoulder back, back shoulder forward), shoulder_y (px, - = up), spine (px bend of the torso line,
# + = hunched back), chest (torso width / blob body swell factor), hip_x (px hip shift, + = forward)
DIAL_FX = ("yaw", "eye_x", "eye_y", "twist", "shoulder_y", "spine", "chest", "hip_x")
DIAL_CHANNELS = POSE_KEYS + FACE_CHANNELS + tuple(FACE_ALIASES) + DIAL_FX


def _key_value(keys, now):
    """Eased value of a [(t, d, value)] key list at time now (values hold; 0 before the first key)."""
    if not keys:
        return 0.0
    v0, cur = 0.0, None
    for key in keys:
        if key[0] > now:
            break
        if cur is not None:
            v0 = lerp(v0, cur[2], ease((key[0] - cur[0]) / cur[1]) if cur[1] > 0 else 1.0)
        cur = key
    if cur is None:
        return 0.0
    return lerp(v0, cur[2], ease((now - cur[0]) / cur[1]) if cur[1] > 0 else 1.0)


def _dial_spec(name, channels):
    """Normalise {channel: (min, max) | (at -1, at 0, at +1)} -> {channel: (n, z, p)}."""
    out = {}
    for ch, rng in dict(channels).items():
        if ch not in DIAL_CHANNELS:
            raise ValueError(f"dial {name!r}: unknown channel {ch!r}; valid: {', '.join(DIAL_CHANNELS)}")
        rng = tuple(float(v) for v in (rng if isinstance(rng, (list, tuple)) else (0.0, rng)))
        if len(rng) == 2:  # value at 0 .. value at 1; negative dial values extrapolate
            lo, hi = rng
            rng = (2 * lo - hi, lo, hi)
        if len(rng) != 3:
            raise ValueError(f"dial {name!r}: channel {ch!r} needs (min, max) or (at -1, at 0, at +1)")
        for kk in FACE_ALIASES.get(ch, (ch,)):
            out[kk] = rng
    return out


def _dial_map(rng, v):
    n, z, p = rng
    return z + (p - z) * v if v >= 0 else z + (z - n) * v


# Built-in smart bones: one dial drives many joints / face channels (Moho-style).
# head_turn: -1 looks back over the shoulder .. 0 profile .. +1 to the camera (head yaw, torso twist,
# eyes leading, shoulder offset); smile: -1 frown .. +1 big smile (mouth, cheeks, lids, brows);
# shrug_amount 0..1; slouch -1 proud .. +1 slumped (spine curve, head drop); breathe_deep 0..1
# (chest swell, shoulders up, chin up); lean -1 back .. +1 forward (torso + hips counter).
DIALS = {}
_BUILTIN_DIALS = {
    "head_turn": {"yaw": (-2.0, 0.0, -1.0), "twist": (-5.0, 0.0, 6.0), "eye_x": (0.45, 0.0, -0.6),
                  "torso": (-0.04, 0.0, -0.02), "head": (0.05, 0.0, -0.03), "shoulder_y": (1.5, 0.0, -1.5)},
    "smile": {"mouth_curve": (-1.0, 0.0, 1.0), "cheek": (0.0, 0.0, 0.8), "lids": (0.22, 0.0, 0.2),
              "brows": (-0.35, 0.0, 0.18), "brow_angle": (-0.6, 0.0, 0.0), "head": (0.06, 0.0, -0.03)},
    "shrug_amount": {"armUF": (0.0, 0.25), "elbowF": (0.0, 1.55), "armUB": (0.0, 0.35), "elbowB": (0.0, 1.55),
                     "head": (0.0, 0.12), "shoulder_y": (0.0, -8.0), "brows": (0.0, 0.6),
                     "mouth_curve": (0.0, -0.25), "torso": (0.0, -0.03)},
    "slouch": {"torso": (-0.08, 0.0, 0.24), "head": (-0.12, 0.0, 0.32), "hip": (1.0, 0.0, -5.0),
               "spine": (-6.0, 0.0, 10.0), "chest": (0.1, 0.0, -0.04), "shoulder_y": (-2.0, 0.0, 4.0),
               "armUF": (-0.05, 0.0, 0.12), "armUB": (0.05, 0.0, 0.1), "lids": (0.0, 0.0, 0.3),
               "brows": (0.15, 0.0, -0.25)},
    "breathe_deep": {"chest": (0.0, 0.18), "shoulder_y": (0.0, -5.0), "head": (0.0, -0.1), "torso": (0.0, -0.06),
                     "armUF": (0.0, 0.08), "armUB": (0.0, -0.08), "lids": (0.0, 0.35), "brows": (0.0, 0.2),
                     "hip": (0.0, 1.5)},
    "lean": {"torso": (-0.3, 0.0, 0.38), "hip_x": (7.0, 0.0, -9.0), "thighF": (-0.12, 0.0, 0.16),
             "thighB": (-0.12, 0.0, 0.16), "head": (0.12, 0.0, -0.2), "hip": (0.0, 0.0, -3.0),
             "armUB": (0.25, 0.0, -0.2), "armUF": (0.1, 0.0, -0.1)},
}


def define_dial(name: str, channels: dict) -> str:
    """Register a smart bone. channels: {channel: (value at 0, value at 1)} or {channel: (at -1, at 0,
    at +1)}; channels are pose joints (torso, head, hip, thighF, kneeF, thighB, kneeB, armUF, elbowF,
    armUB, elbowB; radians / px), face channels (brow_l, brow_r, brow_angle, lid_l, lid_r, cheek,
    mouth_curve, brows, lids) and dial extras (yaw, eye_x, eye_y, twist, shoulder_y, spine, chest,
    hip_x). Values add on top of whatever the character is doing. Returns the name."""
    DIALS[str(name)] = _dial_spec(name, channels)
    return str(name)


for _n, _c in _BUILTIN_DIALS.items():
    define_dial(_n, _c)


# FFD lattice presets (#7): control-point displacements on a 3x3 Bezier lattice over the character's
# box, as fractions of the box width / height (x right, y down on screen; row 0 = top, row 2 = feet).
def _ffd_preset(name, a, now, seed=0.0):
    z = (0.0, 0.0)
    if name == "squash_head":   # big cartoon head: crown spreads + rises, body tapers, feet stay
        return [[(-0.45 * a, -0.2 * a), (0.0, -0.26 * a), (0.45 * a, -0.2 * a)],
                [(0.08 * a, -0.03 * a), (0.0, 0.0), (-0.08 * a, -0.03 * a)], [z, z, z]]
    if name == "stretch_up":    # tall & thin (volume): crown up, waist pinched
        return [[(0.08 * a, -0.34 * a), (0.0, -0.36 * a), (-0.08 * a, -0.34 * a)],
                [(0.14 * a, -0.1 * a), (0.0, -0.1 * a), (-0.14 * a, -0.1 * a)], [z, z, z]]
    if name == "bulge":         # cartoon swell of the middle (puffed up / just ate)
        return [[(-0.1 * a, -0.05 * a), (0.0, -0.06 * a), (0.1 * a, -0.05 * a)],
                [(-0.42 * a, 0.0), (0.0, 0.0), (0.42 * a, 0.0)], [(-0.06 * a, 0.0), z, (0.06 * a, 0.0)]]
    if name == "squash_down":   # flattened: shorter and wider
        return [[(-0.25 * a, 0.3 * a), (0.0, 0.32 * a), (0.25 * a, 0.3 * a)],
                [(-0.3 * a, 0.12 * a), (0.0, 0.12 * a), (0.3 * a, 0.12 * a)], [(-0.1 * a, 0.0), z, (0.1 * a, 0.0)]]
    if name == "shiver":        # fast wobble (cold / scared), feet planted
        g = []
        for j in range(3):
            row = []
            k = (2 - j) / 2.0
            for i in range(3):
                ph = now * 47.0 + i * 1.9 + j * 2.7 + seed
                row.append((0.035 * a * k * math.sin(ph), 0.012 * a * k * math.sin(ph * 1.31 + 1.0)))
            g.append(row)
        return g
    raise ValueError(f"unknown deform preset {name!r}; valid: {', '.join(DEFORM_PRESETS)} (or a grid)")


DEFORM_PRESETS = ("squash_head", "stretch_up", "bulge", "squash_down", "shiver")


def _norm_grid(grid):
    """[[ [dx, dy], ...cols ], ...rows] (>= 2x2) -> tuple of tuples of (float, float)."""
    rows = [[(float(p[0]), float(p[1])) for p in row] for row in grid]
    if len(rows) < 2 or any(len(r) != len(rows[0]) for r in rows) or len(rows[0]) < 2:
        raise ValueError("deform grid must be a rectangular list of rows of [dx, dy] (at least 2x2)")
    return tuple(tuple(r) for r in rows)


def _bernstein(n, t):
    """Bernstein basis of degree n-1 at t (array) -> list of n arrays."""
    m = n - 1
    return [math.comb(m, i) * t ** i * (1.0 - t) ** (m - i) for i in range(n)]


def _ffd_field(grids, u, v):
    """Summed lattice displacement (dx, dy in box fractions) at normalised points u, v (arrays)."""
    dx = np.zeros_like(u)
    dy = np.zeros_like(u)
    for g in grids:
        rows, cols = len(g), len(g[0])
        bu, bv = _bernstein(cols, u), _bernstein(rows, v)
        for j in range(rows):
            for i in range(cols):
                px, py = g[j][i]
                if px or py:
                    w = bv[j] * bu[i]
                    if px:
                        dx += w * px
                    if py:
                        dy += w * py
    return dx, dy


try:  # optional fast path for the FFD warp
    import cv2 as _cv2
except Exception:  # noqa: BLE001
    _cv2 = None


def _upsample_map(m, step, W, H):
    """Bilinear upsample of a coarse map (sample k at pixel (k + 0.5) * step - 0.5, the same
    convention as cv2.resize) to H x W (separable)."""
    gh, gw = m.shape
    fx = np.clip((np.arange(W, dtype=np.float32) + 0.5) / step - 0.5, 0.0, gw - 1.001)
    ix = fx.astype(np.int32)
    fx -= ix.astype(np.float32)
    a = m[:, ix] * (1.0 - fx) + m[:, ix + 1] * fx
    fy = np.clip((np.arange(H, dtype=np.float32) + 0.5) / step - 0.5, 0.0, gh - 1.001)
    iy = fy.astype(np.int32)
    fy = (fy - iy.astype(np.float32))[:, None]
    return np.ascontiguousarray(a[iy] * (1.0 - fy) + a[iy + 1] * fy, dtype=np.float32)


def _ffd_warp(src, box, grids, step=8):
    """Warp a premultiplied BGRA HxWx4 uint8 array. box = (bx, by, bw, bh): the lattice box in the
    array's pixel coordinates. Inverse mapping: source = p - D(p - D(p)) (one fixed-point step),
    evaluated on a coarse grid (every `step` px) and upsampled; OpenCV remap when available,
    numpy bilinear otherwise."""
    H, W = src.shape[:2]
    bx, by, bw, bh = box
    gw, gh = W // step + 2, H // step + 2
    off = (step - 1) * 0.5  # coarse sample k sits at pixel (k + 0.5) * step - 0.5
    X, Y = np.meshgrid(np.arange(gw, dtype=np.float32) * step + off, np.arange(gh, dtype=np.float32) * step + off)
    u = np.clip((X - bx) / bw, 0.0, 1.0)
    v = np.clip((Y - by) / bh, 0.0, 1.0)
    dx, dy = _ffd_field(grids, u, v)
    u2 = np.clip((X - dx * bw - bx) / bw, 0.0, 1.0)
    v2 = np.clip((Y - dy * bh - by) / bh, 0.0, 1.0)
    dx, dy = _ffd_field(grids, u2, v2)
    ddx, ddy = (dx * -bw).astype(np.float32), (dy * -bh).astype(np.float32)
    if _cv2 is not None:
        size = (gw * step, gh * step)
        mx = _cv2.resize(ddx, size, interpolation=_cv2.INTER_LINEAR)[:H, :W]
        my = _cv2.resize(ddy, size, interpolation=_cv2.INTER_LINEAR)[:H, :W]
        mx += np.arange(W, dtype=np.float32)[None, :]
        my += np.arange(H, dtype=np.float32)[:, None]
        return _cv2.remap(src, mx, my, _cv2.INTER_LINEAR, borderMode=_cv2.BORDER_CONSTANT, borderValue=0)
    mx = _upsample_map(ddx, step, W, H) + np.arange(W, dtype=np.float32)[None, :]
    my = _upsample_map(ddy, step, W, H) + np.arange(H, dtype=np.float32)[:, None]
    # numpy fallback: only rows / columns that can receive content are resampled
    alpha = src[..., 3]
    rows, cols = np.nonzero(alpha.any(axis=1))[0], np.nonzero(alpha.any(axis=0))[0]
    out = np.zeros_like(src)
    if not len(rows):
        return out
    hit = (mx >= cols[0] - 1) & (mx <= cols[-1] + 1) & (my >= rows[0] - 1) & (my <= rows[-1] + 1)
    ys, xs = np.nonzero(hit)
    if not len(ys):
        return out
    sx, sy = mx[ys, xs], my[ys, xs]
    x0 = np.floor(sx).astype(np.int32)
    y0 = np.floor(sy).astype(np.int32)
    fx = (sx - x0)[:, None]
    fy = (sy - y0)[:, None]
    acc = np.zeros((len(ys), 4), np.float32)
    for oy, wy in ((0, 1 - fy), (1, fy)):
        for ox, wx in ((0, 1 - fx), (1, fx)):
            xi, yi = x0 + ox, y0 + oy
            ok = ((xi >= 0) & (xi < W) & (yi >= 0) & (yi < H))[:, None]
            acc += src[np.clip(yi, 0, H - 1), np.clip(xi, 0, W - 1)] * (wx * wy * ok)
    out[ys, xs] = np.clip(acc + 0.5, 0, 255).astype(np.uint8)
    return out


class _BoilCtx:
    """cairo.Context proxy for line boil (#71): every stroke / fill / clip path is re-emitted with its
    points nudged by a smooth device-space noise field that changes each boil epoch, so outlines look
    hand-redrawn. Fills use the same field (shapes and their ink stay together); strokes get a small
    extra wobble of their own. Everything else is delegated to the wrapped context."""

    def __init__(self, ctx, amount, epoch, seed=0):
        self.__dict__["_c"] = ctx
        rng = random.Random(int(epoch) * 7919 + int(seed) * 104729 + 17)
        m = ctx.get_matrix()  # wobble grows gently with the on-screen scale (close-ups boil more)
        zs = math.sqrt(abs(m.xx * m.yy - m.xy * m.yx))
        a = 1.7 * float(amount) * clamp(zs, 0.5, 4.0) ** 0.5
        self.__dict__["_a"] = a
        self.__dict__["_p"] = tuple(rng.uniform(0, 2 * math.pi) for _ in range(8))
        self.__dict__["_f"] = tuple(rng.uniform(0.022, 0.05) for _ in range(4))

    def __getattr__(self, n):
        return getattr(self.__dict__["_c"], n)

    def __setattr__(self, n, v):
        setattr(self.__dict__["_c"], n, v)

    def _off(self, x, y, extra):
        p, f, a = self._p, self._f, self._a
        ox = math.sin(x * f[0] + y * f[1] + p[0]) + 0.5 * math.sin(x * f[2] * 2.1 - y * f[3] + p[1])
        oy = math.sin(y * f[2] - x * f[3] + p[2]) + 0.5 * math.sin(y * f[0] * 1.9 + x * f[1] + p[3])
        if extra:
            ox += 0.45 * math.sin(x * 0.19 + y * 0.07 + p[4]) * math.cos(y * 0.11 + p[5])
            oy += 0.45 * math.sin(y * 0.17 - x * 0.09 + p[6]) * math.cos(x * 0.13 + p[7])
        return ox * a / 1.5, oy * a / 1.5

    def _jitter(self, extra):
        c = self._c
        path = c.copy_path()
        c.new_path()
        u2d, d2u = c.user_to_device, c.device_to_user

        def j(x, y):
            dx, dy = u2d(x, y)
            ox, oy = self._off(dx, dy, extra)
            return d2u(dx + ox, dy + oy)

        for kind, pts in path:
            if kind == cairo.PATH_MOVE_TO:
                c.move_to(*j(*pts))
            elif kind == cairo.PATH_LINE_TO:
                c.line_to(*j(*pts))
            elif kind == cairo.PATH_CURVE_TO:
                a, b, e = j(pts[0], pts[1]), j(pts[2], pts[3]), j(pts[4], pts[5])
                c.curve_to(a[0], a[1], b[0], b[1], e[0], e[1])
            else:
                c.close_path()
        return path

    def _op(self, name, extra, preserve):
        c = self._c
        path = self._jitter(extra)
        getattr(c, name)()
        if preserve:
            c.new_path()
            c.append_path(path)

    def stroke(self):
        self._op("stroke", True, False)

    def stroke_preserve(self):
        self._op("stroke_preserve", True, True)

    def fill(self):
        self._op("fill", False, False)

    def fill_preserve(self):
        self._op("fill_preserve", False, True)

    def clip(self):
        self._op("clip", False, False)

    def clip_preserve(self):
        self._op("clip_preserve", False, True)


def _boil_conf(v, every=3):
    """None/False/0 -> None; number -> {amount, every}; dict passes through (amount, every, seed)."""
    if not v:
        return None
    if isinstance(v, dict):
        c = dict(amount=0.8, every=every, seed=0)
        c.update(v)
    else:
        c = dict(amount=float(v), every=every, seed=0)
    c["every"] = max(1, int(c["every"]))
    return c if c["amount"] > 0 else None


def _seed_of(name):
    return sum((i + 1) * ord(ch) for i, ch in enumerate(str(name))) % 9973


class Dial(Action):
    """Smart bone (#4): ease dial `name` to `value` over d s from the action start (non-blocking unless
    wait=True). Built-ins: head_turn, smile, shrug_amount, slouch, breathe_deep, lean (DIALS);
    custom dials via define_dial(). JSON: {"do": "dial", "who": "bob", "name": "smile", "value": 0.8, "d": 0.4}."""

    def __init__(self, name, value=1.0, d=0.3, wait=False):
        if name not in DIALS:
            raise ValueError(f"unknown dial {name!r}; valid: {', '.join(DIALS)}")
        self.name, self.value, self.d, self.wait = name, float(value), float(d), bool(wait)
        self.duration = self.d if self.wait else 0.0

    def start(self, c, scene):
        super().start(c, scene)
        c.dial(self.name, self.value, scene.time, self.d)

    def pose(self, c):
        return c._idle_pose()


class PaperTurn(Action):
    """Paper-Mario turn (#58): flatten to a sliver, flip, open again. face: +1 / -1, 0 = turn around.
    JSON: {"do": "paperturn", "who": "bob"} (or a classic "turn" with Character(turn_style="paper"))."""

    def __init__(self, face=0, d=PAPER_FLIP_D):
        self.face, self.d = int(face), float(d)
        self.duration = self.d

    def start(self, c, scene):
        super().start(c, scene)
        f = self.face or -int(c.face)
        if f != int(c.face):
            c._start_xflip(scene, self.d, PAPER_FLIP_MIN, face=f)
        else:
            self.duration = 0.0

    def pose(self, c):
        return c._idle_pose()


class View(Action):
    """View set (#5): switch the character's drawing to "side" (classic), "front" (facing the camera:
    symmetric face, legs side by side, arms at the sides) or "back" (back of the head, no face) with a
    quick squash. Toon and blob styles (others stay side). JSON: {"do": "view", "who": "bob",
    "view": "front", "d": 0.28}."""

    def __init__(self, view="front", d=VIEW_FLIP_D):
        if view not in VIEWS:
            raise ValueError(f"unknown view {view!r}; valid: {', '.join(VIEWS)}")
        self.view, self.d = view, float(d)
        self.duration = self.d

    def start(self, c, scene):
        super().start(c, scene)
        if getattr(c, "view", "side") == self.view:
            self.duration = 0.0
            return
        if self.d <= 0:
            c.view = self.view
            return
        c._start_xflip(scene, self.d, VIEW_FLIP_MIN, view=self.view, sound=0.18)
        c.squash = 0.05

    def pose(self, c):
        return c._idle_pose()


class Deform(Action):
    """FFD exaggeration (#7): a preset (squash_head, stretch_up, bulge, squash_down, shiver) or a custom
    lattice grid ([[ [dx, dy] per column ] per row], fractions of the character box, row 0 = top) eased
    in to `amount` (small overshoot) over `attack`, held, and released over `release` by the end of d
    (hold=True keeps it). Non-blocking unless wait=True. JSON: {"do": "deform", "who": "bob",
    "preset": "bulge", "amount": 1, "d": 0.8}."""

    def __init__(self, preset="bulge", amount=1.0, d=0.8, grid=None, attack=0.14, release=0.22,
                 hold=False, wait=False):
        if grid is None and preset not in DEFORM_PRESETS:
            raise ValueError(f"unknown deform preset {preset!r}; valid: {', '.join(DEFORM_PRESETS)} (or grid=)")
        self.grid = _norm_grid(grid) if grid is not None else None
        self.preset = preset if grid is None else (preset if preset not in DEFORM_PRESETS else "custom")
        self.amount, self.d, self.attack, self.release = float(amount), float(d), float(attack), float(release)
        self.hold, self.wait = bool(hold), bool(wait)
        self.duration = self.d if self.wait else 0.0

    def start(self, c, scene):
        super().start(c, scene)
        if self.grid is not None:
            c.deform_grid(self.preset, self.grid)
        t = scene.time
        c.deform(self.preset, self.amount * 1.12, t, self.attack)
        c.deform(self.preset, self.amount, t + self.attack, self.attack * 0.8)
        if not self.hold:
            c.deform(self.preset, 0.0, t + max(self.attack * 1.8, self.d - self.release), self.release)

    def pose(self, c):
        return c._idle_pose()


class WalkInPlace(MoveTo):
    """Step in place for d s (front / back view walking toward / away from the camera, #5): legs and
    arms cycle with a bob, x stays put. grow: scale change per second (+ = coming closer)."""

    def __init__(self, d=2.0, gait="walk", grow=0.0):
        super().__init__(0.0, gait)
        self.duration, self.grow = float(d), float(grow)

    def start(self, c, scene):
        Action.start(self, c, scene)
        self.last_half = math.floor(c.phase / math.pi)

    def update(self, c, dt, scene):
        self.t += dt
        step = self.speed * (ease(self.t / 0.25) * 0.7 + 0.3) * dt
        c.phase += step / (self.stride * c.leg_k()) * math.pi * 2
        if self.grow:
            c.scale = max(0.05, c.scale * (1.0 + self.grow * dt))
        half = math.floor(c.phase / math.pi)
        if half != self.last_half:
            self.last_half = half
            scene.event("step" if self.gait != "run" else "runstep", c.x, gain=0.7)
        return self.t >= self.duration


ACTIONS.update(dial=Dial, paperturn=PaperTurn, paper_turn=PaperTurn, view=View, deform=Deform,
               walkinplace=WalkInPlace, walk_in_place=WalkInPlace)


class _CharacterN:
    """Character mixin: smart bones, paper flips, view sets, FFD deform, line boil (round N)."""

    # ---- smart bones (#4)
    def dial(self, name: str, value: float, t: float = None, d: float = 0.3):
        """Key smart bone `name` to `value` from time t (None = 0) over d s (values hold)."""
        if name not in DIALS:
            raise ValueError(f"unknown dial {name!r}; valid: {', '.join(DIALS)}")
        dk = self.__dict__.setdefault("dial_keys", {})
        dk.setdefault(name, []).append((0.0 if t is None else float(t), max(0.0, float(d)), float(value)))
        dk[name].sort(key=lambda e: e[0])
        return self

    def dial_value(self, name: str, now: float) -> float:
        return _key_value(self.__dict__.get("dial_keys", {}).get(name), now)

    def _apply_dials(self, now):
        pose_off, face_off, fx = {}, {}, {}
        for name, keys in self.dial_keys.items():
            v = _key_value(keys, now)
            if abs(v) < 1e-5 or name not in DIALS:
                continue
            for ch, rng in DIALS[name].items():
                x = _dial_map(rng, v)
                if ch in FACE_CHANNELS:
                    face_off[ch] = face_off.get(ch, 0.0) + x
                elif ch in DIAL_FX:
                    fx[ch] = fx.get(ch, 0.0) + x
                else:
                    pose_off[ch] = pose_off.get(ch, 0.0) + x
        if pose_off:
            P = self.dpose
            for k, x in pose_off.items():
                if k == "hip" and P.get("ik", 0) > 0.5:
                    P["hipIK"] = P.get("hipIK", 0.0) + x
                P[k] = P.get(k, 0.0) + x
        self._dial_face = face_off or None
        self._dial_fx = fx or None

    # ---- deform (#7)
    def deform(self, preset: str, amount: float = 1.0, t: float = None, d: float = 0.2):
        """Key FFD preset (or a custom grid name from deform_grid) to `amount` from t over d s."""
        if preset not in DEFORM_PRESETS and preset not in self.__dict__.get("deform_grids", {}):
            raise ValueError(f"unknown deform {preset!r}; valid: {', '.join(DEFORM_PRESETS)} or a deform_grid name")
        dk = self.__dict__.setdefault("deform_keys", {})
        dk.setdefault(preset, []).append((0.0 if t is None else float(t), max(0.0, float(d)), float(amount)))
        dk[preset].sort(key=lambda e: e[0])
        return self

    def deform_grid(self, name: str, grid):
        """Register a custom lattice: rows (top -> feet) of [dx, dy] per column, fractions of the box."""
        self.__dict__.setdefault("deform_grids", {})[name] = _norm_grid(grid)
        return self

    def _deform_grids(self, now):
        dk = self.__dict__.get("deform_keys")
        if not dk:
            return None
        out = []
        for name, keys in dk.items():
            a = _key_value(keys, now)
            if abs(a) < 1e-3:
                continue
            custom = self.__dict__.get("deform_grids", {}).get(name)
            if custom is not None:
                out.append(tuple(tuple((p[0] * a, p[1] * a) for p in row) for row in custom))
            else:
                out.append(_ffd_preset(name, a, now, _seed_of(self.name) * 0.37))
        return out or None

    # ---- views (#5)
    def set_view(self, view: str, t: float = None, d: float = VIEW_FLIP_D):
        """Draw in "side" / "front" / "back" view: now (t=None, instant) or from time t (squash swap)."""
        if view not in VIEWS:
            raise ValueError(f"unknown view {view!r}; valid: {', '.join(VIEWS)}")
        if t is None:
            self.view = view
        else:
            self.__dict__.setdefault("view_keys", []).append((float(t), view, float(d)))
        return self

    # ---- paper / view flips (#58)
    def _start_xflip(self, scene, d, kmin, face=None, view=None, sound=0.32):
        cur = self.__dict__.get("_xflip")
        if cur is not None:  # finish the running flip at once
            self._end_xflip(cur, True)
        self._xflip = dict(t=0.0, d=max(0.05, float(d)), kmin=float(kmin), face=face, view=view,
                           dface=int(self.face), swapped=False)
        self.paper_k = 1.0
        self._dface = int(self.face)
        if sound and scene is not None:
            scene.event("whoosh", self.x, gain=float(sound))

    def _end_xflip(self, xf, swap=False):
        if not xf["swapped"]:
            if xf["face"] is not None:
                self.face = xf["face"]
            if xf["view"] is not None:
                self.view = xf["view"]
            xf["swapped"] = True
        self._xflip = None
        self.paper_k = 1.0
        self._dface = None
        self._vis_face = int(self.face)

    def _update_n(self, dt, scene, now):
        """Per-frame state of the round-N features (only touches characters that use them)."""
        d = self.__dict__
        for key in d.get("view_keys", ()):
            t, view, dd = key
            if t <= now < t + dt * 1.5 and getattr(self, "view", "side") != view and not d.get("_xflip"):
                if dd > 0:
                    self._start_xflip(scene, dd, VIEW_FLIP_MIN, view=view, sound=0.18)
                    self.squash = 0.05
                else:
                    self.view = view
        if d.get("turn_style") == "paper" and d.get("_xflip") is None:
            vf = d.get("_vis_face")
            if vf is not None and vf != int(self.face):  # facing changed by another action: paper flip it
                target = int(self.face)
                self.face = vf
                self._start_xflip(scene, PAPER_FLIP_D * 0.8, PAPER_FLIP_MIN, face=target)
            self._vis_face = int(self.face)
        xf = d.get("_xflip")
        if xf is not None:
            xf["t"] += dt
            u = clamp(xf["t"] / xf["d"], 0.0, 1.0)
            tri = 1.0 - abs(2.0 * u - 1.0)
            self.paper_k = lerp(1.0, xf["kmin"], ease(tri) ** 0.7)
            if u >= 0.5 and not xf["swapped"]:
                if xf["face"] is not None:
                    self.face = xf["face"]
                if xf["view"] is not None:
                    self.view = xf["view"]
                xf["swapped"] = True
                self._dface = None
                if d.get("turn_style") == "paper":
                    self._vis_face = int(self.face)
            if u >= 1.0:
                self._end_xflip(xf)
        b = _boil_conf(d.get("boil"), d.get("boil_every", 3))
        if b is not None:
            self._boil_epoch = int(round(now / dt)) // b["every"] if dt > 0 else 0

    # ---- drawing wrapper: boil + deform around the classic draw
    def draw(self, ctx, now):
        d = self.__dict__
        b = d.get("boil")
        if b is not None:
            bc = _boil_conf(b, d.get("boil_every", 3))
            if isinstance(ctx, _BoilCtx):
                ctx = ctx._c
            if bc is not None:
                ctx = _BoilCtx(ctx, bc["amount"], d.get("_boil_epoch", 0), bc["seed"] + _seed_of(self.name))
        grids = self._deform_grids(now) if d.get("deform_keys") else None
        if grids:
            return self._draw_deformed(ctx, now, grids)
        return self._draw_core(ctx, now)

    def _deform_box(self):
        """Lattice box in world coords: (x0, x1, y_bottom, y_top) (y up)."""
        sk = self._skeleton()
        s = self.scale
        if sk is None:  # animals
            w, top = 95.0, 150.0
        else:
            top = -sk["crown"][1] + (26 if getattr(self, "hat", None) else 10)
            w = max(55.0, sk["head_r"] * 1.25 + 30)
        return self.x - w * s, self.x + w * s, self.y - 6 * s, self.y + top * s

    def _draw_deformed(self, ctx, now, grids):
        inner = ctx._c if isinstance(ctx, _BoilCtx) else ctx
        x0, x1, yb, yt = self._deform_box()
        pts = [inner.user_to_device(x, -y) for x, y in ((x0, yb), (x1, yb), (x0, yt), (x1, yt))]
        lx0, lx1 = min(p[0] for p in pts), max(p[0] for p in pts)
        ly0, ly1 = min(p[1] for p in pts), max(p[1] for p in pts)
        bw, bh = max(1.0, lx1 - lx0), max(1.0, ly1 - ly0)
        target = inner.get_target()
        try:
            TW, TH = target.get_width(), target.get_height()
        except Exception:  # noqa: BLE001 - not an image surface: draw undeformed
            return self._draw_core(ctx, now)
        # capture = lattice box + the largest control displacement (Bezier FFD stays inside the
        # control points' hull) + room for raised arms / props; more when the body is rotated
        mdx = max((abs(p[0]) for g in grids for row in g for p in row), default=0.0)
        mup = max((-p[1] for g in grids for row in g for p in row), default=0.0)
        mdn = max((p[1] for g in grids for row in g for p in row), default=0.0)
        rk = 0.6 if getattr(self, "body_rot", 0.0) else 0.0
        mx_ = bw * max(0.3 + rk, mdx + 0.06)
        cx0 = int(max(0, math.floor(lx0 - mx_)))
        cx1 = int(min(TW, math.ceil(lx1 + mx_)))
        cy0 = int(max(0, math.floor(ly0 - bh * max(0.22 + rk, mup + 0.06))))
        cy1 = int(min(TH, math.ceil(ly1 + bh * max(0.06 + rk, mdn + 0.04))))
        if cx1 - cx0 < 2 or cy1 - cy0 < 2:
            return self._draw_core(ctx, now)
        w, h = cx1 - cx0, cy1 - cy0
        off = cairo.ImageSurface(cairo.FORMAT_ARGB32, w, h)
        octx = cairo.Context(off)
        m = inner.get_matrix()
        octx.set_matrix(cairo.Matrix(m.xx, m.yx, m.xy, m.yy, m.x0 - cx0, m.y0 - cy0))
        try:
            octx.set_font_face(inner.get_font_face())
        except Exception:  # noqa: BLE001
            pass
        dctx = octx
        if isinstance(ctx, _BoilCtx):
            dctx = _BoilCtx(octx, 0.0, 0)
            dctx.__dict__.update(_a=ctx._a, _p=ctx._p, _f=ctx._f)
        self._draw_core(dctx, now)
        off.flush()
        stride = off.get_stride()
        src = np.ndarray((h, stride // 4, 4), np.uint8, off.get_data())[:, :w]
        warped = _ffd_warp(np.ascontiguousarray(src), (lx0 - cx0, ly0 - cy0, bw, bh), grids)
        out = cairo.ImageSurface(cairo.FORMAT_ARGB32, w, h)
        ost = out.get_stride()
        buf = np.ndarray((h, ost // 4, 4), np.uint8, out.get_data())
        buf[:, :w] = warped
        out.mark_dirty()
        inner.save()
        inner.identity_matrix()
        inner.set_source_surface(out, cx0, cy0)
        inner.paint()
        inner.restore()
        self._ffd_last = (w, h)

    # ---- view sets (#5): front / back drawing (toon + blob), local frame (x forward, y down)
    def _draw_view(self, ctx, now, P, sx, sy, fsg, back):
        blob = self.style == "blob"
        rot = getattr(self, "body_rot", 0.0)
        fxd = self.__dict__.get("_dial_fx") or {}
        if P.get("ik", 0) > 0.5:
            hipH = P["hipIK"]
        else:
            hipH = max(self.leg_extent(P["thighF"], P["kneeF"]), self.leg_extent(P["thighB"], P["kneeB"])) + P["hip"]
        hipH = max(hipH, 16)
        hy = -hipH
        if rot:
            self._rot_pivot = (0.0, hy)
            ctx.translate(0.0, hy)
            ctx.rotate(rot)
            ctx.translate(0.0, -hy)
        ta = P["torso"]
        lc = self.limb_color

        def poly(pts, w, col, ink=True):
            for width, c in (((w + 6, INK), (w, col)) if ink else ((w, col),)):
                ctx.new_path()
                ctx.move_to(*pts[0])
                for p in pts[1:]:
                    ctx.line_to(*p)
                ctx.set_line_width(width)
                ctx.set_line_cap(cairo.LINE_CAP_ROUND)
                ctx.set_line_join(cairo.LINE_JOIN_ROUND)
                ctx.set_source_rgb(*c)
                ctx.stroke()

        def oval(cx, cy, rx, ry, col, lw=3.0):
            ctx.new_path()
            ctx.save()
            ctx.translate(cx, cy)
            ctx.scale(rx, ry)
            ctx.arc(0, 0, 1, 0, 2 * math.pi)
            ctx.restore()
            self._ink_fill(ctx, col, lw)

        def leg(s, th, kn, dark, hx):
            k = (hx * s, hy)
            kn_ = (s * (hx + 1.5), hy + self.THIGH * math.cos(th))
            ft = (s * (hx + 2.5), kn_[1] + self.SHIN * math.cos(th - kn))
            if blob:
                poly([k, kn_, ft], 7.5, lc, ink=False)
            else:
                poly([k, kn_, ft], 17, shade(self.pants, dark))
            sw = 0.0 if back else 3.0
            oval(ft[0] + s * sw, ft[1] - 2, 10.5 if blob else 11.5, 7.0, shade(self.shoes, dark))
            return ft

        def arm(s, au, el, dark, s0):
            sa, sb = abs(math.sin(au)), abs(math.sin(au + el))
            j = (s0[0] + s * (3 + self.UARM * (0.18 + 0.32 * sa)), s0[1] + self.UARM * math.cos(au))
            e = (j[0] + s * (2 + self.LARM * (0.1 + 0.3 * sb)), j[1] + self.LARM * math.cos(au + el))
            if blob:
                poly([s0, j, e], 7.5, lc, ink=False)
                oval(e[0], e[1], 8.5, 8.5, (1, 1, 1) if self.gloves else lc)
            else:
                poly([s0, j, e], 13, shade(self.body, dark))
                oval(e[0], e[1], 8, 8, shade(self.skin, dark))
            return e

        yaw_save = self.sp_yaw.x if hasattr(self, "sp_yaw") else None
        # F limbs on the +x side of the local frame (mirrored by facing)
        legs = (("F", 1, 1.0), ("B", -1, 0.9)) if not back else (("F", 1, 0.9), ("B", -1, 1.0))
        if blob:
            R = self.head_r * 1.55
            bc = (0.0, hy - R * 0.85 * math.cos(ta))
            for nm, s, dk in legs:
                leg(s, P["thigh" + nm], P["knee" + nm], dk, R * 0.3)
            ctx.save()
            ctx.translate(*bc)
            if back:
                self.draw_blob_body(ctx, now, R, face=False)
            else:
                if yaw_save is not None:
                    self.sp_yaw.x = 0.0
                try:
                    self.draw_blob_body(ctx, now, R)
                finally:
                    if yaw_save is not None:
                        self.sp_yaw.x = yaw_save
            ctx.restore()
            sy0 = bc[1] + R * 0.18 + fxd.get("shoulder_y", 0.0)
            for nm, s, dk in legs:
                arm(s, P["armU" + nm], P["elbow" + nm], dk, (s * R * 0.84, sy0))
            self.head_world = (self.x + fsg * bc[0] * sx * self.scale, self.y - bc[1] * sy * self.scale + R * self.scale)
            return
        T = self.TORSO
        neck = (0.0, hy - T * max(0.35, math.cos(ta)))
        for nm, s, dk in legs:
            leg(s, P["thigh" + nm], P["knee" + nm], dk, 10.0)
        poly([(-10.0, hy), (10.0, hy)], 17, self.pants)  # pelvis joins the legs
        chest = 1.0 + fxd.get("chest", 0.0)
        tw = 44 * chest
        poly([(0.0, hy - 3), neck], tw, self.body)
        ctx.new_path()
        ctx.move_to(-tw / 2 + 2, hy + 1)
        ctx.line_to(tw / 2 - 2, hy + 1)
        ctx.set_line_width(7)
        ctx.set_source_rgb(*shade(self.pants, 0.85))
        ctx.stroke()
        if not back:
            self._front_wear(ctx, hy, neck, tw)
        elif self.backpack is not None:
            ctx.new_path()
            ctx.rectangle(-17, neck[1] + 6, 34, (hy - neck[1]) * 0.62)
            self._ink_fill(ctx, self.backpack, 3)
            for s in (-1, 1):
                ctx.move_to(s * 13, neck[1] + 2)
                ctx.line_to(s * 13, neck[1] + 8)
            ctx.set_line_width(5)
            ctx.set_source_rgb(*shade(self.backpack, 0.7))
            ctx.stroke()
        hr = self.head_r
        ha = P["head"] + self.sp_head.x
        hc = (0.0, neck[1] - (hr - 6) * (0.75 + 0.25 * math.cos(ha)))
        sy0 = lerp(hy, neck[1], 0.82) + fxd.get("shoulder_y", 0.0)
        arms = []
        for nm, s, dk in legs:
            arms.append((s, P["armU" + nm], P["elbow" + nm], dk, (s * (tw / 2 - 1), sy0)))
        ctx.save()
        ctx.translate(*hc)
        ctx.rotate(0.12 * math.sin(ha) * (1 if not back else -1))
        if back:
            self._draw_head_back(ctx, now, hr)
        else:
            if yaw_save is not None:
                self.sp_yaw.x = 0.0
            try:
                self.draw_head(ctx, now, hr)
            finally:
                if yaw_save is not None:
                    self.sp_yaw.x = yaw_save
        ctx.restore()
        for a in arms:
            arm(*a)
        sxw = self.x + fsg * hc[0] * sx * self.scale
        syw = self.y - hc[1] * sy * self.scale
        if rot:
            sxw, syw = self.to_world(hc)
        self.head_world = (sxw, syw + hr * self.scale)

    def _front_wear(self, ctx, hy, neck, tw):
        """Tie / apron / scarf / bag strap on the front-view torso."""
        top = neck[1]
        if self.apron is not None:
            ctx.new_path()
            ctx.move_to(-tw * 0.34, top + 14)
            ctx.line_to(tw * 0.34, top + 14)
            ctx.line_to(tw * 0.42, hy + 30)
            ctx.line_to(-tw * 0.42, hy + 30)
            ctx.close_path()
            self._ink_fill(ctx, self.apron, 2.5)
        if self.bag is not None:
            ctx.new_path()
            ctx.move_to(-tw * 0.42, top + 4)
            ctx.line_to(tw * 0.38, hy - 6)
            ctx.set_line_width(5)
            ctx.set_source_rgb(*shade(self.bag, 0.7))
            ctx.stroke()
        if self.tie is not None:
            ctx.new_path()
            ctx.move_to(-3, top + 2)
            ctx.line_to(3, top + 2)
            ctx.line_to(5, top + (hy - top) * 0.62)
            ctx.line_to(0, top + (hy - top) * 0.72)
            ctx.line_to(-5, top + (hy - top) * 0.62)
            ctx.close_path()
            self._ink_fill(ctx, self.tie, 2)
        if self.scarf is not None:
            ctx.new_path()
            ctx.save()
            ctx.translate(0, top + 2)
            ctx.scale(tw * 0.55, 9)
            ctx.arc(0, 0, 1, 0, 2 * math.pi)
            ctx.restore()
            self._ink_fill(ctx, self.scarf, 3)

    def _draw_head_back(self, ctx, now, r):
        """Back of the head: hair over most of it, both ears, no face."""
        hs = self.hair_style
        for s in (-1, 1):
            ctx.new_path()
            ctx.arc(s * r * 0.97, 2, r * 0.18, 0, 2 * math.pi)
            self._ink_fill(ctx, shade(self.skin, 0.9), 3)
        ctx.new_path()
        ctx.arc(0, 0, r, 0, 2 * math.pi)
        ctx.set_source_rgb(*self.skin)
        ctx.fill_preserve()
        ctx.save()
        ctx.clip()
        ctx.new_path()
        ctx.set_source_rgb(*self.hair)
        if hs == "cap":
            ctx.rectangle(-r, -r, 2 * r, r * 0.95)
        else:
            ctx.arc(0, -r * 0.28, r * 1.02, 0, 2 * math.pi)
        ctx.fill()
        ctx.new_path()  # nape shadow
        ctx.arc(0, r * 0.95, r * 0.6, 0, 2 * math.pi)
        ctx.set_source_rgba(*shade(self.skin, 0.7), 0.35)
        ctx.fill()
        ctx.restore()
        ctx.new_path()
        ctx.arc(0, 0, r, 0, 2 * math.pi)
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(3.5)
        ctx.stroke()
        if hs == "tuft":
            lag = self.sp_hair.x * 10
            for a in (-0.35, 0.0, 0.35):
                ctx.new_path()
                x0, y0 = r * math.sin(a), -r * math.cos(a)
                ctx.move_to(x0, y0)
                ctx.curve_to(x0 + 3 + lag * 0.4, y0 - 11, x0 + 10 + lag, y0 - 13, x0 + 12 + lag, y0 - 5)
                ctx.set_line_width(4)
                ctx.set_source_rgb(*INK)
                ctx.stroke()
        elif hs == "ponytail":
            sw = 0.1 * math.sin(self.clock * 5) + self.sp_hair.x * 0.5
            ctx.save()
            ctx.translate(0, -r * 0.2)
            ctx.rotate(sw)
            ctx.new_path()
            ctx.save()
            ctx.scale(r * 0.36, r * 0.72)
            ctx.arc(0, 0.95, 1, 0, 2 * math.pi)
            ctx.restore()
            self._ink_fill(ctx, self.hair, 3)
            ctx.new_path()
            ctx.arc(0, r * 0.1, r * 0.14, 0, 2 * math.pi)
            self._ink_fill(ctx, shade(self.hair, 0.7), 2)
            ctx.restore()
        self._hat_anchor = None
        ys = self.sp_yaw.x if hasattr(self, "sp_yaw") else None
        if ys is not None:
            self.sp_yaw.x = 0.0
        try:
            self._draw_face_hat(ctx, r)
        finally:
            if ys is not None:
                self.sp_yaw.x = ys


# ---------------------------------------------------------------- lip sync
MOUTHS = "ABCDEFX"


def read_audio(path: str, sr: int = 22050) -> tuple:
    """Decode any audio file (wav/mp3/ogg) to mono float32 via ffmpeg."""
    raw = subprocess.run(["ffmpeg", "-v", "error", "-i", path, "-ac", "1", "-ar", str(sr),
                          "-f", "f32le", "-"], capture_output=True, check=True).stdout
    return np.frombuffer(raw, dtype=np.float32), sr


def cues_from_rhubarb(path: str) -> list:
    """Rhubarb Lip Sync TSV output: '<seconds>\\t<shape>' per line."""
    cues = []
    with open(path) as fh:
        for line in fh:
            parts = line.split()
            if len(parts) < 2:
                continue
            try:
                t = float(parts[0])
            except ValueError:
                continue  # header or garbage line
            shape = parts[1][0].upper()
            if shape in MOUTHS:
                cues.append((t, shape))
    cues.sort(key=lambda c: c[0])
    return cues or [(0.0, "X")]


def cues_from_audio(path: str, hop: float = 1 / 60) -> list:
    """Approximate Rhubarb-style mouth shapes from loudness + brightness."""
    x, sr = read_audio(path)
    n = max(1, int(sr * hop))
    if len(x) == 0:
        return [(0.0, "X")]
    frames = max(1, len(x) // n)
    rms, cen, zcr = np.zeros(frames), np.zeros(frames), np.zeros(frames)
    win = np.hanning(n * 2)
    freqs = np.fft.rfftfreq(n * 2, 1 / sr)
    for i in range(frames):
        seg = x[i * n:i * n + n * 2]
        if len(seg) < n * 2:
            seg = np.pad(seg, (0, n * 2 - len(seg)))
        rms[i] = np.sqrt(np.mean(seg ** 2))
        sp = np.abs(np.fft.rfft(seg * win))
        cen[i] = (sp * freqs).sum() / (sp.sum() + 1e-9)
        zcr[i] = np.mean(np.abs(np.diff(np.sign(seg)))) / 2
    e = rms / (np.percentile(rms, 95) + 1e-9)
    cues, last = [], None
    for i in range(frames):
        v = e[i]
        if v < 0.06:
            s = "X"
        elif v < 0.16:
            s = "A"
        elif zcr[i] > 0.18 or cen[i] > 3200:
            s = "B"  # hissy consonants s, t, ch, ee
        elif v > 0.75:
            s = "D"
        elif v > 0.45:
            s = "C" if cen[i] > 1300 else "E"
        elif cen[i] < 900:
            s = "F"
        else:
            s = "B"
        if s != last:
            cues.append((i * hop, s))
            last = s
    # min hold: drop shapes shorter than 2 frames (avoids jitter)
    clean = []
    for j, (t, s) in enumerate(cues):
        nxt = cues[j + 1][0] if j + 1 < len(cues) else t + 1
        if (nxt - t >= 2 * hop or not clean) and (not clean or clean[-1][1] != s):
            clean.append((t, s))
    if clean[-1][1] != "X":  # always close the mouth at the end of the clip
        clean.append((frames * hop, "X"))
    return clean


_EN_SHAPES = {"a": "D", "e": "C", "i": "B", "y": "B", "o": "E", "u": "F", "w": "F",
              "m": "A", "b": "A", "p": "A", "f": "B", "v": "B", "l": "C", "r": "E"}
_RO_SHAPES = {"a": "D", "ă": "C", "â": "B", "î": "B", "e": "C", "i": "B", "o": "E", "u": "F",
              "m": "A", "b": "A", "p": "A", "f": "B", "v": "B", "l": "C", "r": "E", "h": "C",
              "ș": "B", "ş": "B", "ț": "B", "ţ": "B", "j": "B", "s": "B", "z": "B", "t": "B", "d": "B"}


def _ro_units(text):
    """Split Romanian text into sound units -> Rhubarb shapes (handles ce/ci/ge/gi, che/chi/ghe/ghi)."""
    s = text.lower()
    out, i = [], 0
    while i < len(s):
        ch = s[i]
        nxt = s[i + 1] if i + 1 < len(s) else ""
        if ch in ",.!?;:":
            out.append("X")
        elif ch == " ":
            out.append("B")
        elif ch in "cg" and nxt == "h":          # che/chi/ghe/ghi: hard k/g, the 'h' is silent
            out.append("B")
            i += 1
        elif ch in "cg" and nxt in "ei":         # ce/ci/ge/gi: "ch"/"j" sound
            out.append("B")
        elif ch.isalpha():
            out.append(_RO_SHAPES.get(ch, "B"))
        i += 1
    return out


def cues_from_text(text: str, d: float, lang: str = "en") -> list:
    """Fallback lip sync from the letters when there is no audio.
    lang: "en" (default) or "ro" (Romanian letters and digraphs)."""
    if lang == "ro":
        units = _ro_units(text)
    else:
        chars = [ch for ch in text.lower() if ch.isalpha() or ch in " ,.!?"]
        units = ["X" if ch in ",.!?" else ("B" if ch == " " else _EN_SHAPES.get(ch, "B")) for ch in chars]
    if not units:
        return [(0, "X")]
    dt = d * 0.92 / len(units)
    cues = []
    for i, sh in enumerate(units):
        if not cues or cues[-1][1] != sh:
            cues.append((i * dt, sh))
    cues.append((d * 0.92, "X"))
    return cues


# ---------------------------------------------------------------- animals
