# ---------------------------------------------------------------- characters
class Facing(int):
    """Character.face: the facing direction (+1 / -1, behaves as an int) that can also be called
    as Character.face(t, d=0.3, **channels) to key face puppet curves (#33)."""

    def __call__(self, t, d=0.3, **channels):
        return self._c.face_curve(t, d, **channels)

    def __reduce__(self):
        return (int, (int(self),))


class Character(_CharacterN):
    THIGH, SHIN, TORSO, UARM, LARM = 37, 35, 52, 30, 28

    @property
    def face(self):
        f = Facing(self.__dict__.get("_face", 1))
        f._c = self
        return f

    @face.setter
    def face(self, v):
        self.__dict__["_face"] = int(v)

    def face_curve(self, t: float, d: float = 0.3, **channels) -> "Character":
        """Face puppet curves (#33): from time t ease the given channels to new values over d s
        (values hold until changed). brow_l / brow_r (-1 low .. +1 raised), brow_angle (-1 worried
        .. +1 angry), lid_l / lid_r (0 open .. 1 closed), cheek (0..1), mouth_curve (-1 frown ..
        +1 smile); aliases brows / lids. No channels = back to neutral. Also c.face(t, ...)."""
        ch = _face_channels(channels) if channels else {k: 0.0 for k in FACE_CHANNELS}
        fk = self.__dict__.setdefault("face_keys", {})
        for k, v in ch.items():
            fk.setdefault(k, []).append((float(t), max(0.0, float(d)), v))
            fk[k].sort(key=lambda e: e[0])
        return self

    set_face = face_curve

    def face_value(self, ch: str, now: float) -> float:
        """Value of one face channel at time now (continuous, eased between keys)."""
        keys = getattr(self, "face_keys", {}).get(ch)
        if not keys:
            return 0.0
        v0, cur = 0.0, None
        for key in keys:
            if key[0] > now:
                break
            if cur is not None:
                v0 = lerp(v0, cur[2], ease((key[0] - cur[0]) / cur[1]) if cur[1] > 0 else 1.0)
            cur = key
        if cur is None:
            return 0.0
        return lerp(v0, cur[2], ease((now - cur[0]) / cur[1]) if cur[1] > 0 else 1.0)

    def _face_vals(self, now):
        """All face channels at now, or None when every channel is neutral (fast path)."""
        dfo = self.__dict__.get("_dial_face")
        if not getattr(self, "face_keys", None):
            if not dfo:
                return None
            v = {k: dfo.get(k, 0.0) for k in FACE_CHANNELS}
        else:
            v = {k: self.face_value(k, now) for k in FACE_CHANNELS}
            if dfo:
                for k, x in dfo.items():
                    v[k] += x
        if all(abs(x) < 1e-4 for x in v.values()):
            return None
        for k in ("lid_l", "lid_r"):
            v[k] = clamp(v[k], -0.5, 1.0)
        v["cheek"] = clamp(v["cheek"], 0.0, 1.0)
        return v

    def __init__(self, name, x=0, face=1, body="#ff8a3d", pants="#3d5a99", skin="#ffd2a8",
                 shoes="#2b2233", hair="#5a3825", hair_style="tuft", head_r=34, scale=1.0, seed=0,
                 style="toon", shape="round", top=None, limb_color="#2b2233", gloves=True,
                 kind=None, pattern=None, horn=None,
                 hat=None, hat_color=None, glasses=None, glasses_color="#2b2233", scarf=None, apron=None,
                 tie=None, backpack=None, bag=None, facial_hair=None, facial_hair_color=None, blush=False,
                 antenna=False, turn_style=None, view="side", boil=None, boil_every=3):
        """Outfit & accessories (#9), all optional:
          hat: cap | beanie | top_hat | chef | straw | bow | headscarf   (hat_color hex)
          glasses: round | square | sun   (glasses_color)
          scarf / apron / tie / backpack / bag: a colour hex (or True for a default colour);
            the scarf ends are a Verlet chain that flies when the character runs
          facial_hair: mustache | beard | both   (facial_hair_color, default = hair colour)
          blush: True for rosy cheeks;  antenna: True for two springy antennae
          hair_style="long": long hair as chains (in addition to tuft / ponytail / cap)
        Round N: turn_style="paper" (Paper-Mario flip on every turn, #58), view="side" | "front" |
        "back" (#5, toon / blob), boil=0.8 + boil_every=3 (hand-redrawn line boil, #71)."""
        self.name, self.x, self.y, self.vy, self.face = name, x, 0.0, 0.0, face
        self.body, self.pants, self.skin = hex2rgb(body), hex2rgb(pants), hex2rgb(skin)
        self.shoes, self.hair = hex2rgb(shoes), hex2rgb(hair)
        self.hair_style, self.head_r, self.scale = hair_style, head_r, scale
        self.style = style  # "toon" (cartoon person), "stick" (3D stickman), "blob" (fruit/veg/object)
        self.shape, self.top, self.limb_color, self.gloves = shape, top, hex2rgb(limb_color), gloves
        if style == "blob":  # short cartoon limbs on a big body (Kitchen Chaos / fruit stories)
            self.THIGH, self.SHIN, self.UARM, self.LARM, self.TORSO = 21, 20, 22, 20, 30
        self.kind = None
        if style in ("quadruped", "bird"):  # Farm Files animals
            table = QUADRUPEDS if style == "quadruped" else BIRDS
            kind = kind or ("goat" if style == "quadruped" else "chicken")
            if kind not in table:
                raise ValueError(f"unknown {style} kind {kind!r}; valid: {', '.join(sorted(table))}")
            self.kind = kind
            self.spec = dict(table[kind])
            if body == "#ff8a3d":  # constructor default -> use the animal's natural colour
                self.body = hex2rgb(self.spec["color"])
            self.pattern = hex2rgb(pattern or self.spec.get("pattern", "#2b2233"))
            self.horn = hex2rgb(horn or self.spec.get("horn", "#efe2c4"))
            self.THIGH, self.SHIN = self.spec["thigh"], self.spec["shin"]
            self.head_r = self.spec["head"]
            self.shadow_w = self.spec.get("shadow", 42)
        self.pose = dict(STAND)
        self.pose["hipIK"] = 0.0
        self.phase, self.clock, self.squash = 0.0, random.Random(seed).random() * 10, 0.0
        self.queue, self.current = [], None
        self.lines, self.emotes = [], []
        self.blink_off = random.Random(seed + 7).random() * 3
        self.head_world = (x, 150)
        self.look_at, self.look = None, (1.0, 0.0)
        self.vx, self._px, self._pvx = 0.0, x, 0.0
        self.sp_head, self.sp_hair = Spring(160, 12), Spring(90, 7)
        self.smear = 0.0
        self.gestures = []
        self.auto_gestures = True
        self.look_keys = []  # (t, target): scheduled eye targets (used by toonvoice.Timeline)
        self.idle_life = True  # motion pilot: weight shift, glances, fidgets when idle
        self.lang = "en"       # lip-sync language for text-only lines ("en" or "ro")
        self.carry_keys = []   # (t, d, obj): props held in both hands (layered over walking)
        self._carrying = None
        self._look_override = None
        self._idle_seed = random.Random(seed + 101).random() * 100
        # outfit & accessories
        dflt = lambda v, c: None if v in (None, False) else hex2rgb(c if v is True else v)
        self.hat = hat
        self.hat_color = hex2rgb(hat_color) if hat_color else hex2rgb(
            {"cap": "#e63946", "beanie": "#457b9d", "top_hat": "#2b2233", "chef": "#ffffff", "straw": "#e9c46a",
             "bow": "#ff5d8f", "headscarf": "#c0392b"}.get(hat, "#e63946"))
        if hat is not None and hat not in HATS:
            raise ValueError(f"unknown hat {hat!r}; valid: {', '.join(HATS)}")
        if glasses is not None and glasses not in GLASSES:
            raise ValueError(f"unknown glasses {glasses!r}; valid: {', '.join(GLASSES)}")
        if facial_hair is not None and facial_hair not in FACIAL_HAIR:
            raise ValueError(f"unknown facial_hair {facial_hair!r}; valid: {', '.join(FACIAL_HAIR)}")
        self.glasses, self.glasses_color = glasses, hex2rgb(glasses_color)
        self.scarf, self.apron = dflt(scarf, "#e63946"), dflt(apron, "#ffffff")
        self.tie, self.backpack, self.bag = dflt(tie, "#1d3557"), dflt(backpack, "#2a9d8f"), dflt(bag, "#8d5a3b")
        self.facial_hair = facial_hair
        self.facial_hair_color = hex2rgb(facial_hair_color) if facial_hair_color else self.hair
        self.blush, self.antenna = bool(blush), bool(antenna)
        self.chains = {}
        if self.scarf is not None:
            self.chains["scarf"] = Chain(n=7, seg=10.0, gravity=-900, damping=0.08)
        if hair_style == "long":
            self.chains["hair"] = Chain(n=6, seg=9.0, gravity=-1100, damping=0.1, stiff=40)
        if self.antenna:
            self.chains["antL"] = Chain(n=4, seg=8.0, gravity=-200, damping=0.12, stiff=900)
            self.chains["antR"] = Chain(n=4, seg=8.0, gravity=-200, damping=0.12, stiff=900)
        self.wind = 0.0          # extra wind on chains (px/s^2, + = to the right)
        self.reach_keys = []     # (t, d, target): layered arm IK reach (Character.reach)
        self._held = None        # object in the front hand (Throw wind-up)
        self._ik = None          # (mode, local target, weight) computed each frame
        # head turns (#32): head_yaw +1 = profile (classic), 0 = facing the camera,
        # -1 = looking back over the shoulder; values in between = 3/4 views. Spring-smoothed.
        self.head_yaw = 1.0
        self.face_camera = False  # True: the head turns to the audience (head_yaw 0)
        self.head_keys = []       # (t, d, yaw): scheduled head turns (turn_head / FaceCamera)
        self.sp_yaw = Spring(90, 18)
        self.sp_yaw.x = 1.0
        self.body_rot = 0.0       # whole-body rotation about the hip (rad, + = pitch forward)
        self.ground_y = 0.0       # terrain height under the character (Scene sets it with terrain)
        self.face_keys = {}       # face puppet curves (#33): channel -> [(t, d, value)]
        self._mouth_override = None  # mouth shape forced by an action (Eat chewing)
        if turn_style not in (None, "classic", "paper"):
            raise ValueError(f"unknown turn_style {turn_style!r}; valid: classic, paper")
        if view not in VIEWS:
            raise ValueError(f"unknown view {view!r}; valid: {', '.join(VIEWS)}")
        self.turn_style, self.view = turn_style, view
        self.boil, self.boil_every = boil, boil_every
        self.dial_keys, self.deform_keys = {}, {}  # smart bones (#4) / FFD (#7): name -> [(t, d, value)]

    def leg_k(self) -> float:
        """Leg length relative to the standard cartoon person (scales gaits)."""
        return (self.THIGH + self.SHIN) / 72.0

    def __getstate__(self):  # snapshot for parallel render (drop timeline refs)
        d = self.__dict__.copy()
        d["queue"], d["current"], d["look_at"], d["look_keys"] = [], None, None, []
        d["carry_keys"], d["_carrying"] = [], None
        d["reach_keys"], d["_held"] = [], None
        d["_terrain"] = None
        return d

    # timeline API --------------------------------------------------
    def at(self, t: float, action: "Action") -> "Character":
        """Queue an action that starts no earlier than time t (after the previous one ends)."""
        self.queue.append((t, action))
        return self

    def then(self, action: "Action") -> "Character":
        """Queue an action right after the previous one."""
        self.queue.append((None, action))
        return self

    def say(self, text: str, t: float, d: float = None, audio: str = None, cues: str = None,
            gain: float = 1.0, lang: str = None) -> "Character":
        """Speech bubble + lip sync. audio: voice file (ElevenLabs/Piper/...),
        cues: Rhubarb TSV. Without either, lip sync comes from the text."""
        if audio and d is None:
            x, sr = read_audio(audio)
            d = len(x) / sr + 0.25
        d = d or max(1.2, 0.075 * len(text) + 0.6)
        if cues:
            cl = cues_from_rhubarb(cues)
        elif audio:
            cl = cues_from_audio(audio)
        else:
            cl = cues_from_text(text, d, lang or getattr(self, "lang", "en"))
        self.lines.append(dict(t=t, d=d, text=text, audio=audio, cues=cl, gain=gain))
        return self

    def turn_head(self, t: float, yaw: float = 0.0, d: float = None) -> "Character":
        """Turn the head from time t: yaw 0 = to the camera, 0.5 = 3/4, 1 = profile,
        -1 = looking back. d=None keeps it until another key."""
        self.head_keys.append((t, math.inf if d is None else d, clamp(yaw, -1.0, 1.0)))
        return self

    def _yaw_target(self, now: float) -> float:
        tgt = 0.0 if getattr(self, "face_camera", False) else getattr(self, "head_yaw", 1.0)
        best = None
        for t, d, yaw in getattr(self, "head_keys", ()):
            if t <= now < t + d and (best is None or t >= best[0]):
                best = (t, yaw)
        if best is not None:
            tgt = best[1]
        return clamp(tgt, -1.0, 1.0)

    def _yaw_view(self):
        """(profile weight 0..1, mirror sign) of the head right now."""
        if getattr(self, "style", "toon") in ("quadruped", "bird") or not hasattr(self, "sp_yaw"):
            return 1.0, 1
        y = clamp(self.sp_yaw.x, -1.0, 1.0)
        return abs(y), (-1 if y < 0 else 1)

    def _face_xform(self, ctx, r, c):
        """Squeeze the profile face toward the head centre for front / 3/4 views.
        x' = (x - c r) k + c r fp (identity in profile)."""
        fp, sg = self._yaw_view()
        self._face_c = c
        if fp >= 0.999 and sg > 0:
            return
        k = lerp(1.25, 1.0, fp)
        ctx.scale(sg, 1)
        ctx.translate(c * r * fp, 0)
        ctx.scale(k, 1)
        ctx.translate(-c * r, 0)

    def _mouth_shift(self, r):
        fp, _ = self._yaw_view()
        return (getattr(self, "_face_c", 0.48) - 0.48) * r * (1 - fp)

    def _turned_mouth(self, ctx, shape, expr, r):
        dx = self._mouth_shift(r)
        ctx.save()
        ctx.translate(dx, 0)
        self.draw_mouth(ctx, shape, expr, r)
        ctx.restore()

    def _cheeks(self, ctx, r, expr):
        fp, _ = self._yaw_view()
        a = 0.7 if expr == "angry" else 0.35
        fv = getattr(self, "_fv", None)
        cy, cr = r * 0.32, r * 0.13
        if fv:  # cheek channel: rounder, higher, rosier
            cy -= fv["cheek"] * r * 0.08
            cr *= 1 + 0.3 * fv["cheek"]
            a = min(0.8, a + 0.25 * fv["cheek"])
        ctx.arc(r * 0.78, cy, cr, 0, 2 * math.pi)
        ctx.set_source_rgba(1, 0.25, 0.3, a)
        ctx.fill()
        if fp < 0.999:  # the far cheek appears as the head turns to the camera
            c = getattr(self, "_face_c", 0.41)
            ctx.arc(r * (2 * c - 0.78), cy, cr, 0, 2 * math.pi)
            ctx.set_source_rgba(1, 0.25, 0.3, a * (1 - fp))
            ctx.fill()

    def _draw_face_hat(self, ctx, r):
        hat = getattr(self, "hat", None)
        anchor = getattr(self, "_hat_anchor", None) or (0.0, -r, r)
        self._hat_anchor = None
        if not hat:
            return
        fp, sg = self._yaw_view()
        ctx.save()
        ctx.scale(sg, 1)
        self._draw_hat(ctx, hat, (anchor[0] * fp, anchor[1], anchor[2]))
        ctx.restore()

    def carry(self, obj, t: float, d: float = None) -> "Character":
        """Hold `obj` (Ball/Box) in both hands from t for d seconds (None = until the end).
        Layered: the character can walk, run or talk while carrying."""
        self.carry_keys.append((t, d, obj))
        return self

    def reach(self, target, t: float, d: float = 1.0) -> "Character":
        """Layered arm IK: the front hand reaches for target (object or (x, y)) while doing anything."""
        self.reach_keys.append((t, d, target))
        return self

    def gesture(self, kind: str, t: float, d: float = 1.2) -> "Character":
        """Upper-body gesture layered on top of whatever the body is doing
        (walk + wave, run + point ...). kinds: wave, point, shrug, facepalm,
        think, fist, talk, hands_up."""
        self.gestures.append((t, d, kind))
        return self

    def emote(self, name: str, t: float, d: float = 1.5) -> "Character":
        """Expression from t for d seconds: happy, surprised, sad, determined, dizzy,
        angry, scared, sleepy, confused, excited."""
        self.emotes.append((t, d, name))
        return self

    def expression(self, now):
        for t, d, n in self.emotes:
            if t <= now < t + d:
                return n
        return "happy"

    def talking(self, now: float) -> tuple:
        """(text, progress 0..1, mouth shape) of the current line, or (None, 0, 'X')."""
        for ln in self.lines:
            if ln["t"] <= now < ln["t"] + ln["d"]:
                rel = now - ln["t"]
                shape = "X"
                for ct, s in ln["cues"]:
                    if ct <= rel:
                        shape = s
                    else:
                        break
                return ln["text"], rel / ln["d"], shape
        return None, 0, "X"

    # simulation ------------------------------------------------------
    def update(self, dt, scene):
        self.clock += dt
        now = scene.time
        if self.current is None and self.queue:
            t, a = self.queue[0]
            if t is None or now >= t:
                self.queue.pop(0)
                self.current = a
                a.start(self, scene)
        a = self.current
        if a and a.update(self, dt, scene):
            self.current = None
        target = a.pose(self) if a else self._idle_pose()
        k = min(1.0, dt * (a.blend if a else 16.0))
        for key, v in target.items():
            if key == "hip" and v == -100:
                continue
            self.pose[key] += (v - self.pose[key]) * k
        ik_on = target.get("hip") == -100
        self.pose["ik"] = 1.0 if ik_on else 0.0
        if ik_on:
            self.pose["hipIK"] = target["hipIK"]
        # velocity / acceleration for secondary motion
        self.vx = (self.x - self._px) / dt
        ax = (self.vx - self._pvx) / dt
        self._px, self._pvx = self.x, self.vx
        self.sp_head.update(clamp(-ax * 0.00012 * self.face, -0.25, 0.25), dt)
        self.sp_hair.update(clamp(-abs(self.vx) * 0.0016 + self.vy * 0.0012, -0.9, 0.9), dt)
        self.squash *= max(0, 1 - dt * 9)
        if abs(self.squash) < 0.002:
            self.squash = 0
        self.smear = max(0, self.smear - dt)
        self._update_carry(now)
        if getattr(self, "_drop_sound", False):
            self._drop_sound = False
            scene.event("thud", self.x, gain=0.4)
        self.dpose = self._layered_pose(now)
        if self.__dict__.get("dial_keys"):
            self._apply_dials(now)
        elif self.__dict__.get("_dial_fx") is not None or self.__dict__.get("_dial_face") is not None:
            self._dial_fx = self._dial_face = None
        self._place_held()
        self._update_chains(dt, scene)
        for t, tgt in getattr(self, "look_keys", []):
            if t <= now < t + dt * 1.5:
                self.look_at = tgt
        # eyes follow target
        if self.look_at is not None:
            tx = self.look_at.x
            ty = getattr(self.look_at, "y", 0) + (110 if isinstance(self.look_at, Character) else 0)
            dx, dy = tx - self.x, ty - (self.y + 110)
            n = math.hypot(dx, dy) or 1
            self.look = (dx / n * self.face, dy / n)
        elif getattr(self, "idle_life", False) and self.current is None:
            self.look = self._idle_glance()
        else:
            self.look = (1.0, 0.0)
        if getattr(self, "_look_override", None) is not None:
            self.look = self._look_override
        fxd = self.__dict__.get("_dial_fx")
        if fxd and ("eye_x" in fxd or "eye_y" in fxd):
            self.look = (clamp(self.look[0] + fxd.get("eye_x", 0.0), -1.2, 1.2),
                         clamp(self.look[1] + fxd.get("eye_y", 0.0), -1.2, 1.2))
        if hasattr(self, "sp_yaw"):
            if fxd and "yaw" in fxd:
                self.sp_yaw.update(clamp(self._yaw_target(now) + fxd["yaw"], -1.0, 1.0), dt)
            else:
                self.sp_yaw.update(self._yaw_target(now), dt)
        nd = self.__dict__
        if (nd.get("turn_style") == "paper" or nd.get("_xflip") is not None or nd.get("view_keys")
                or nd.get("boil")):
            self._update_n(dt, scene, now)

    # motion pilot (#23) ----------------------------------------------
    def _idle_pose(self):
        """Standing pose with procedural life: breathing, weight shift, fidgets."""
        p = Action.pose(Action(), self)
        if not getattr(self, "idle_life", False):
            return p
        t, sd = self.clock, getattr(self, "_idle_seed", 0.0)
        shift = math.sin(t * 0.55 + sd) * 0.6 + math.sin(t * 0.23 + sd * 1.7) * 0.4  # -1..1, slow
        p["thighF"] += 0.06 * shift
        p["thighB"] -= 0.06 * shift
        p["kneeF"] += 0.05 * max(0.0, shift)
        p["kneeB"] += 0.05 * max(0.0, -shift)
        p["torso"] += 0.025 * shift + 0.01 * math.sin(t * 1.9 + sd)
        p["hip"] += -1.2 * abs(shift)
        p["head"] += 0.04 * math.sin(t * 0.8 + sd * 2.3)
        # occasional fidget: a short hand lift every ~7 s (deterministic per seed)
        f = (t * 0.14 + sd) % 1.0
        if 0.9 < f < 0.98:
            k = math.sin((f - 0.9) / 0.08 * math.pi)
            p["armUF"] += 0.35 * k
            p["elbowF"] += 0.8 * k
        return p

    def _idle_glance(self):
        ph = (self.clock * 0.23 + getattr(self, "_idle_seed", 0.0)) % 1.0
        if ph > 0.86:
            return (-0.8, 0.1)   # glance back
        if ph > 0.78:
            return (0.6, 0.5)    # look up
        return (1.0, 0.0)

    def _update_carry(self, now):
        obj = None
        for t, d, o in getattr(self, "carry_keys", []):
            if t <= now and (d is None or now < t + d):
                obj = o
        prev = getattr(self, "_carrying", None)
        if prev is not None and prev is not obj:
            prev.carried = False  # release: physics takes over again
            if hasattr(prev, "vx"):
                prev.vx, prev.vy = self.vx * 0.6, 60.0
            elif isinstance(prev, Box):  # boxes have no physics: set it down on the ground
                prev.y = 0.0
                self._drop_sound = True
        self._carrying = obj
        if obj is None:
            return
        obj.carried = True

    GESTURES = {
        "wave": lambda t: dict(armUF=2.7, elbowF=0.5 + 0.45 * math.sin(t * 13), head=0.08),
        "point": lambda t: dict(armUF=1.55, elbowF=0.0),
        "shrug": lambda t: dict(armUF=0.35, elbowF=1.7, armUB=0.25, elbowB=1.7, head=0.15),
        "facepalm": lambda t: dict(armUF=0.6, elbowF=2.6, head=0.28),
        "think": lambda t: dict(armUF=0.55, elbowF=2.5, head=-0.18 + 0.05 * math.sin(t * 3)),
        "fist": lambda t: dict(armUF=2.8 + 0.25 * math.sin(t * 10), elbowF=0.5),
        "hands_up": lambda t: dict(armUF=2.6, elbowF=0.4, armUB=2.4, elbowB=0.4),
        "hands_on_hips": lambda t: dict(armUF=-0.55, elbowF=2.25, armUB=-0.5, elbowB=2.2),
        "talk": lambda t: dict(armUF=0.45 + 0.35 * abs(math.sin(t * 4.2)), elbowF=1.3 + 0.4 * math.sin(t * 3.1)),
    }
    UPPER = ("armUF", "elbowF", "armUB", "elbowB", "head")

    def _layered_pose(self, now):
        """Blend explicit/auto gestures over the base pose (upper body only)."""
        P = dict(self.pose)
        g = None
        for t, d, kind in self.gestures:
            if t <= now < t + d:
                w = min(1.0, (now - t) / 0.18, (t + d - now) / 0.22)
                g = (kind, ease(w), now - t)
        if g is None and self.auto_gestures:
            txt, prog, _ = self.talking(now)
            idle = self.current is None or isinstance(self.current, (Wait, Look, Turn))
            if txt and idle:
                w = min(1.0, prog * 8, (1 - prog) * 8)
                g = ("talk", 0.7 * ease(w), now)
        self._gkind, self._gw = (g[0], g[1]) if g else (None, 0.0)
        if g:
            kind, w, tt = g
            for k, v in self.GESTURES[kind](tt).items():
                P[k] = lerp(P[k], v, w)
        if getattr(self, "_carrying", None) is not None:
            P.update(armUF=1.2, elbowF=0.55, armUB=1.15, elbowB=0.6)
            P["torso"] = P["torso"] - 0.06
        self._apply_arm_ik(P, now)
        return P

    # skeleton helpers (#3) -------------------------------------------
    def _skeleton(self, P=None):
        """Local joint positions (character frame: x forward, y down, before facing/scale),
        the same forward kinematics as draw(). None for animals."""
        P = P or getattr(self, "dpose", None) or self.pose
        st = getattr(self, "style", "toon")
        if st in ("quadruped", "bird"):
            return None
        if P.get("ik", 0) > 0.5:
            hipH = P["hipIK"]
        else:
            hipH = max(self.leg_extent(P["thighF"], P["kneeF"]), self.leg_extent(P["thighB"], P["kneeB"])) + P["hip"]
        hipH = max(hipH, 16)
        hip = (0.0, -hipH)
        self._rot_pivot = hip
        ta = P["torso"]
        neck = (hip[0] + self.TORSO * math.sin(ta), hip[1] - self.TORSO * math.cos(ta))
        sh = (lerp(hip[0], neck[0], 0.82), lerp(hip[1], neck[1], 0.82))
        shF = shB = sh
        hr = self.head_r
        ha = ta + P["head"] + self.sp_head.x
        if st == "blob":
            R = self.head_r * 1.55
            bc = (hip[0] + R * 0.85 * math.sin(ta), hip[1] - R * 0.85 * math.cos(ta))
            w = R * (0.55 if getattr(self, "shape", "round") == "tall" else 0.82)
            shF, shB = (bc[0] + w, bc[1] + R * 0.18), (bc[0] - w * 0.85, bc[1] + R * 0.18)
            head, hr = bc, R
            top = {"tall": 1.25, "egg": 1.12, "box": 0.9}.get(getattr(self, "shape", "round"), 1.0)
            crown = (bc[0], bc[1] - R * top)
        else:
            off = (hr + 4) if st == "stick" else (hr - 6)
            head = (neck[0] + off * math.sin(ha), neck[1] - off * math.cos(ha))
            crown = (head[0], head[1] - hr)

        def hand(s0, au, el):
            j = (s0[0] + self.UARM * math.sin(au), s0[1] + self.UARM * math.cos(au))
            return (j[0] + self.LARM * math.sin(au + el), j[1] + self.LARM * math.cos(au + el))

        return dict(hip=hip, neck=neck, shoulderF=shF, shoulderB=shB, head=head, head_r=hr, crown=crown,
                    handF=hand(shF, P["armUF"], P["elbowF"]), handB=hand(shB, P["armUB"], P["elbowB"]))

    def to_world(self, pt):
        """Character-local point -> world (x, y up), including the body rotation (body_rot)."""
        rot = getattr(self, "body_rot", 0.0)
        if rot:
            px, py = getattr(self, "_rot_pivot", (0.0, -60.0))
            c, s = math.cos(rot), math.sin(rot)
            dx, dy = pt[0] - px, pt[1] - py
            pt = (px + dx * c - dy * s, py + dx * s + dy * c)
        return (self.x + self.face * pt[0] * self.scale, self.y - pt[1] * self.scale)

    def to_local(self, wpt):
        lp = ((wpt[0] - self.x) / (self.face * self.scale), -(wpt[1] - self.y) / self.scale)
        rot = getattr(self, "body_rot", 0.0)
        if rot:
            px, py = getattr(self, "_rot_pivot", (0.0, -60.0))
            c, s = math.cos(rot), math.sin(rot)
            dx, dy = lp[0] - px, lp[1] - py
            lp = (px + dx * c + dy * s, py - dx * s + dy * c)
        return lp

    def hand_world(self, front=True):
        sk = self._skeleton()
        if sk is None:  # animals: mouth/beak area
            return self.to_world((40.0, -60.0))
        return self.to_world(sk["handF" if front else "handB"])

    def _ik_goal(self, now):
        """Current hand target: ('point'|'reach', world point) or None."""
        a = self.current
        ht = getattr(a, "hand_target", None) if a is not None else None
        for t, d, tgt in getattr(self, "reach_keys", []):
            if t <= now < t + d:
                ht = ("reach", tgt)
        if not ht:
            return None
        mode, tgt = ht
        if tgt is None:
            return None
        if hasattr(tgt, "x"):
            ty = getattr(tgt, "y", 0.0)
            if isinstance(tgt, Character):
                ty += 100 * tgt.scale
            elif isinstance(tgt, Box):
                ty += tgt.h
            return mode, (tgt.x, ty)
        return mode, (float(tgt[0]), float(tgt[1]))

    def _apply_arm_ik(self, P, now):
        if getattr(self, "style", "toon") in ("quadruped", "bird"):
            return
        goal = self._ik_goal(now)
        if goal is None:
            return
        mode, wpt = goal
        sk = self._skeleton(P)
        s0 = sk["shoulderF"]
        tl = self.to_local(wpt)
        if mode == "point":  # straight arm toward the target: aim far along the direction
            dx, dy = tl[0] - s0[0], tl[1] - s0[1]
            n = math.hypot(dx, dy) or 1.0
            tl = (s0[0] + dx / n * 500, s0[1] + dy / n * 500)
        au, el = arm_ik(s0, tl, self.UARM, self.LARM)
        P["armUF"], P["elbowF"] = au, el

    def _place_held(self):
        """Put carried / held props exactly in the hands (after the pose is final)."""
        sk = self._skeleton()
        held = getattr(self, "_held", None)
        if held is not None:
            hx, hy = self.hand_world(True)
            held.x, held.y = hx + self.face * 4 * self.scale, hy + 2 * self.scale
            if hasattr(held, "vx"):
                held.vx = held.vy = 0.0
        obj = getattr(self, "_carrying", None)
        if obj is None:
            return
        if sk is None:
            hx, hy = self.x + self.face * 45 * self.scale, self.y + 70 * self.scale
        else:
            fx, fy = self.to_world(sk["handF"])
            bx, by = self.to_world(sk["handB"])
            hx, hy = (fx + bx) / 2, (fy + by) / 2
        if isinstance(obj, Box):
            obj.x = hx + self.face * (obj.w / 2 - 8) * self.scale
            obj.y = max(0.0, hy - obj.h * 0.45)
        else:
            size = getattr(obj, "r", None) or getattr(obj, "hh", 15)
            obj.x = hx + self.face * size * 0.7
            obj.y = hy + size * 0.2
            if hasattr(obj, "vx"):
                obj.vx = obj.vy = 0.0

    def _update_chains(self, dt, scene):
        ch = getattr(self, "chains", None)
        if not ch:
            return
        sk = self._skeleton()
        if sk is None:
            return
        wind = getattr(self, "wind", 0.0) + getattr(scene, "wind", 0.0)
        wind -= 5.0 * getattr(self, "vx", 0.0)  # airflow while moving: tails stream out behind
        f = self.face
        if "scarf" in ch:
            nk = sk["neck"]
            a = self.to_world((nk[0] - 10, nk[1] + 6))
            ch["scarf"].update(a, dt, wind, rest_dir=(-0.3 * f, -1.0))
        if "hair" in ch:
            hd, hr = sk["head"], sk["head_r"]
            a = self.to_world((hd[0] - hr * 0.75, hd[1] - hr * 0.1))
            ch["hair"].update(a, dt, wind, rest_dir=(-0.35 * f, -1.0))
        for key, dx in (("antL", -0.3), ("antR", 0.3)):
            if key in ch:
                cr, hr = sk["crown"], sk["head_r"]
                a = self.to_world((cr[0] + dx * hr, cr[1] + 2))
                ch[key].update(a, dt, wind, rest_dir=(f * (0.25 + dx), 1.0))

    # drawing ---------------------------------------------------------
    def leg_extent(self, thigh, knee):
        return self.THIGH * math.cos(thigh) + self.SHIN * math.cos(thigh - knee)

    def _draw_core(self, ctx, now):
        P = getattr(self, "dpose", None) or self.pose
        gy = getattr(self, "ground_y", 0.0)
        rot = getattr(self, "body_rot", 0.0)
        if getattr(self, "draw_shadow", True):
            sh = clamp(1 - (self.y - gy) / 300, 0.3, 1)
            ctx.save()
            ctx.translate(self.x, -gy)
            ctx.scale(getattr(self, "shadow_w", 42) * sh * self.scale, 8 * sh * self.scale)
            ctx.arc(0, 0, 1, 0, 2 * math.pi)
            ctx.set_source_rgba(0, 0, 0, 0.18)
            ctx.fill()
            ctx.restore()

        # speed lines (cartoon motion cue)
        sp = abs(self.vx)
        if sp > 230 and self.y - gy < 5 and getattr(self, "draw_shadow", True) and not rot:
            a = clamp((sp - 230) / 200, 0, 0.6)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            for i, (yy, ln) in enumerate(((-60, 60), (-95, 45), (-125, 70))):
                x0 = self.x - self.face * (40 + i * 8)
                ctx.move_to(x0, yy * self.scale)
                ctx.line_to(x0 - self.face * ln, yy * self.scale)
                ctx.set_source_rgba(1, 1, 1, a)
                ctx.set_line_width(5)
                ctx.stroke()

        self._draw_chains(ctx)
        ctx.save()
        ctx.translate(self.x, -self.y)
        # volume-preserving squash & stretch (+ stretch while flying fast)
        if self.expression(now) == "scared":
            ctx.translate(1.6 * math.sin(now * 61), 0)
        s = self.squash - clamp(abs(self.vy) / 4000, 0, 0.1) * (1 if self.y > 2 else 0)
        sy = 1 - s
        sx = 1 / max(0.6, sy)
        nd = self.__dict__
        fsg = self.face if nd.get("_dface") is None else nd["_dface"]
        pk = nd.get("paper_k")
        if pk is not None and pk != 1.0:  # paper flip / view swap (#58, #5): flatten horizontally
            ctx.scale(fsg * sx * pk * self.scale, sy * self.scale)
        else:
            ctx.scale(fsg * sx * self.scale, sy * self.scale)
        if getattr(self, "style", "toon") in ("quadruped", "bird"):
            if rot:
                ctx.translate(0, -35)
                ctx.rotate(rot)
                ctx.translate(0, 35)
            hc, hr = self._draw_animal(ctx, now, P)
            ctx.restore()
            self.head_world = (self.x + self.face * hc[0] * sx * self.scale,
                               self.y - hc[1] * sy * self.scale + hr * self.scale)
            return
        vw = nd.get("view", "side")
        if vw != "side" and self.style in ("toon", "blob"):  # view sets (#5)
            self._draw_view(ctx, now, P, sx, sy, fsg, vw == "back")
            ctx.restore()
            return
        fxd = nd.get("_dial_fx")

        if P.get("ik", 0) > 0.5:
            hipH = P["hipIK"]
        else:
            hipH = max(self.leg_extent(P["thighF"], P["kneeF"]),
                       self.leg_extent(P["thighB"], P["kneeB"])) + P["hip"]
        hipH = max(hipH, 16)
        hip = (0.0, -hipH)
        if fxd and "hip_x" in fxd:
            hip = (fxd["hip_x"], -hipH)
        if rot:  # whole-body rotation about the hip (swim, lie in bed, ragdoll tumble)
            self._rot_pivot = hip
            ctx.translate(*hip)
            ctx.rotate(rot)
            ctx.translate(-hip[0], -hip[1])
        ta = P["torso"]
        neck = (hip[0] + self.TORSO * math.sin(ta), hip[1] - self.TORSO * math.cos(ta))
        shoulder = (lerp(hip[0], neck[0], 0.82), lerp(hip[1], neck[1], 0.82))

        def limb(start, a1, l1, a2, l2):
            j = (start[0] + l1 * math.sin(a1), start[1] + l1 * math.cos(a1))
            e = (j[0] + l2 * math.sin(a2), j[1] + l2 * math.cos(a2))
            return j, e

        stick = getattr(self, "style", "toon") == "stick"
        blob = getattr(self, "style", "toon") == "blob"
        if blob:
            R = self.head_r * 1.55
            bc = (hip[0] + R * 0.85 * math.sin(ta), hip[1] - R * 0.85 * math.cos(ta))  # body centre
            shoulder = (bc[0] + R * 0.05, bc[1] + R * 0.12)
            sh_w = R * (0.55 if getattr(self, "shape", "round") == "tall" else 0.82)
            blob_sh = {True: (bc[0] + sh_w, bc[1] + R * 0.18), False: (bc[0] - sh_w * 0.85, bc[1] + R * 0.18)}
            blob_hip = {True: (hip[0] + R * 0.22, hip[1]), False: (hip[0] - R * 0.18, hip[1])}

        def stroke_path(pts, w, col):
            if blob:  # thin ink cartoon limbs
                layers = ((7.5, self.limb_color),)
            elif stick:  # shaded tube: dark rim, body colour, highlight stripe
                w = 9.5
                layers = ((w + 3, shade(col, 0.45)), (w, col), (w * 0.35, tuple(min(1, c * 1.25 + 0.15) for c in col)))
            else:
                layers = ((w + 6, INK), (w, col))
            for width, c in layers:
                ctx.new_path()
                ctx.move_to(*pts[0])
                for p in pts[1:]:
                    ctx.line_to(*p)
                ctx.set_line_width(width)
                ctx.set_line_cap(cairo.LINE_CAP_ROUND)
                ctx.set_line_join(cairo.LINE_JOIN_ROUND)
                ctx.set_source_rgb(*c)
                ctx.stroke()

        def blob_(cx, cy, rx, ry, col, rot=0.0):
            ctx.save()
            ctx.translate(cx, cy)
            ctx.rotate(rot)
            ctx.scale(rx, ry)
            ctx.arc(0, 0, 1, 0, 2 * math.pi)
            ctx.restore()
            ctx.set_source_rgb(*col)
            ctx.fill_preserve()
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(3)
            ctx.stroke()

        def leg(th, kn, dark, front):
            h0 = blob_hip[front] if blob else hip
            j, e = limb(h0, th, self.THIGH, th - kn, self.SHIN)
            if front and self.smear > 0:  # smear frame on fast kicks
                ctx.new_path()
                ctx.move_to(*hip)
                for k in range(1, 5):
                    a = th - 0.25 * k
                    ctx.line_to(hip[0] + 70 * math.sin(a), hip[1] + 70 * math.cos(a))
                ctx.close_path()
                ctx.set_source_rgba(*self.pants, 0.35)
                ctx.fill()
            if stick:
                stroke_path([hip, j, e], 17, shade(self.body, dark))
                return
            if blob:
                stroke_path([h0, j, e], 17, self.limb_color)
                blob_(e[0] + 7, e[1] - 2, 12, 7, shade(self.shoes, dark + 0.2 if dark < 1 else 1),
                      rot=(th - kn) * 0.35)
                return
            stroke_path([hip, j, e], 17, shade(self.pants, dark))
            blob_(e[0] + 7, e[1] - 2, 13, 7.5, shade(self.shoes, dark + 0.2 if dark < 1 else 1),
                 rot=(th - kn) * 0.35)

        def arm(au, el, dark):
            s0 = blob_sh[dark >= 1.0] if blob else shoulder
            if fxd:  # smart-bone shoulder twist / lift (#4)
                s0 = (s0[0] + fxd.get("twist", 0.0) * (-1 if dark >= 1.0 else 1), s0[1] + fxd.get("shoulder_y", 0.0))
            j, e = limb(s0, au, self.UARM, au + el, self.LARM)
            stroke_path([s0, j, e], 13, shade(self.body, dark))
            if blob:
                blob_(e[0], e[1], 8.5, 8.5, (1, 1, 1) if self.gloves else self.limb_color)
                return
            if not stick:
                blob_(e[0], e[1], 8, 8, shade(self.skin, dark))

        arm(P["armUB"], P["elbowB"], 0.78)
        leg(P["thighB"], P["kneeB"], 0.8, False)
        if blob:
            leg(P["thighF"], P["kneeF"], 1.0, True)
            ctx.save()
            ctx.translate(*bc)
            ctx.rotate(ta * 0.5 + self.sp_head.x * 0.4)
            self.draw_blob_body(ctx, now, R)
            ctx.restore()
            arm(P["armUF"], P["elbowF"], 1.0)
            ctx.restore()
            if rot:
                hx, hy = self.to_world(bc)
                self.head_world = (hx, hy + R * self.scale)
                return
            self.head_world = (self.x + self.face * bc[0] * sx * self.scale,
                               self.y - bc[1] * sy * self.scale + R * self.scale)
            return
        self._draw_torso_back(ctx, hip, neck, ta)
        if fxd and (fxd.get("spine") or fxd.get("chest")):  # smart-bone spine curve / chest swell (#4)
            sp = fxd.get("spine", 0.0)
            mid = ((hip[0] + neck[0]) / 2 - sp * math.cos(ta), (hip[1] + neck[1]) / 2 - sp * math.sin(ta))
            stroke_path([hip, mid, neck], 40 * (1 + fxd.get("chest", 0.0)), self.body)
        else:
            stroke_path([hip, neck], 40, self.body)
        if stick:
            pass
        else:
            self._torso_details(ctx, hip, neck)
        leg(P["thighF"], P["kneeF"], 1.0, True)
        self._draw_torso_front(ctx, hip, neck, ta, P)
        hr = self.head_r
        ha = ta + P["head"] + self.sp_head.x
        hc = (neck[0] + (hr - 6) * math.sin(ha), neck[1] - (hr - 6) * math.cos(ha))
        if stick:  # neck gap: head floats a little above the torso line
            hc = (neck[0] + (hr + 4) * math.sin(ha), neck[1] - (hr + 4) * math.cos(ha))
        ctx.save()
        ctx.translate(*hc)
        ctx.rotate(ha * 0.6)
        self.draw_head(ctx, now, hr)
        ctx.restore()
        arm(P["armUF"], P["elbowF"], 1.0)
        ctx.restore()
        sxw = self.x + self.face * hc[0] * sx * self.scale
        syw = self.y - hc[1] * sy * self.scale
        if rot:
            sxw, syw = self.to_world(hc)
        self.head_world = (sxw, syw + hr * self.scale)

    # ------------------------------------------------------------ outfit & accessories (#9)
    @staticmethod
    def _ink_fill(ctx, col, lw=2.6):
        ctx.set_source_rgb(*col)
        ctx.fill_preserve()
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(lw)
        ctx.stroke()

    def _draw_chains(self, ctx):
        """World-space chains (scarf ends, long hair, antennae) behind the body."""
        ch = getattr(self, "chains", None)
        if not ch:
            return
        ctx.save()
        ctx.set_line_cap(cairo.LINE_CAP_ROUND)
        ctx.set_line_join(cairo.LINE_JOIN_ROUND)
        for key, c in ch.items():
            if not c.pts:
                continue
            pts = [(x, -y) for x, y in c.pts]
            if key == "scarf":
                widths, col = (13 * self.scale, 9 * self.scale), self.scarf
            elif key == "hair":
                widths, col = (22 * self.scale, 17 * self.scale), self.hair
            else:
                widths, col = (4.5 * self.scale, 2.2 * self.scale), INK
            for w, cc in ((widths[0], INK), (widths[1], col)):
                ctx.new_path()
                ctx.move_to(*pts[0])
                for q in pts[1:]:
                    ctx.line_to(*q)
                ctx.set_line_width(w)
                ctx.set_source_rgb(*cc)
                ctx.stroke()
            if key.startswith("ant"):
                ctx.arc(pts[-1][0], pts[-1][1], 5.5 * self.scale, 0, 2 * math.pi)
                self._ink_fill(ctx, self.body if self.style != "toon" else (1, 0.82, 0.3), 2)
        ctx.restore()

    def _torso_frame(self, ctx, hip, neck, ta):
        """Translate/rotate ctx so (0, 0) is the hip and -y runs up the torso."""
        ctx.translate(*hip)
        ctx.rotate(ta)

    def _draw_torso_back(self, ctx, hip, neck, ta):
        if self.backpack is None:
            return
        ctx.save()
        self._torso_frame(ctx, hip, neck, ta)
        ctx.new_path()
        x0, y0, w, h, r = -36, -self.TORSO * 0.9, 22, self.TORSO * 0.68, 7
        ctx.arc(x0 + w - r, y0 + r, r, -math.pi / 2, 0)
        ctx.arc(x0 + w - r, y0 + h - r, r, 0, math.pi / 2)
        ctx.arc(x0 + r, y0 + h - r, r, math.pi / 2, math.pi)
        ctx.arc(x0 + r, y0 + r, r, math.pi, 1.5 * math.pi)
        ctx.close_path()
        self._ink_fill(ctx, self.backpack, 3)
        ctx.rectangle(x0 + 4, y0 + h * 0.55, w - 8, h * 0.28)
        self._ink_fill(ctx, shade(self.backpack, 0.8), 2)
        ctx.restore()

    def _draw_torso_front(self, ctx, hip, neck, ta, P):
        T = self.TORSO
        ctx.save()
        self._torso_frame(ctx, hip, neck, ta)
        if self.bag is not None:  # strap across the chest + bag at the hip
            ctx.move_to(-14, -T * 0.92)
            ctx.line_to(16, -T * 0.08)
            ctx.set_line_width(5)
            ctx.set_source_rgb(*shade(self.bag, 0.7))
            ctx.stroke()
            ctx.rectangle(10, -T * 0.12, 22, 18)
            self._ink_fill(ctx, self.bag, 2.5)
        if self.apron is not None:  # front panel from the chest down over the thighs
            ctx.move_to(-2, -T * 0.62)
            ctx.line_to(17, -T * 0.62)
            ctx.line_to(22, 34)
            ctx.line_to(-6, 34)
            ctx.close_path()
            self._ink_fill(ctx, self.apron, 2.5)
            ctx.move_to(0, -T * 0.62)
            ctx.line_to(-4, -T * 0.98)
            ctx.set_line_width(2.5)
            ctx.set_source_rgb(*INK)
            ctx.stroke()
            ctx.rectangle(2, 4, 12, 9)  # pocket
            ctx.set_source_rgb(*shade(self.apron, 0.85))
            ctx.fill()
        if self.tie is not None:
            ctx.move_to(17, -T * 0.97)
            ctx.line_to(22, -T * 0.92)
            ctx.line_to(23, -T * 0.4)
            ctx.line_to(19, -T * 0.3)
            ctx.line_to(15, -T * 0.4)
            ctx.close_path()
            self._ink_fill(ctx, self.tie, 2)
        if self.scarf is not None:  # wrap around the neck (ends are a chain)
            ctx.save()
            ctx.translate(2, -T * 0.98)
            ctx.scale(24, 9)
            ctx.arc(0, 0, 1, 0, 2 * math.pi)
            ctx.restore()
            self._ink_fill(ctx, self.scarf, 3)
            for k in (-0.4, 0.0, 0.4):
                ctx.move_to(2 + 24 * k - 2, -T * 0.98 - 7)
                ctx.line_to(2 + 24 * k + 2, -T * 0.98 + 7)
            ctx.set_source_rgba(*shade(self.scarf, 0.7), 0.8)
            ctx.set_line_width(2)
            ctx.stroke()
        ctx.restore()

    def _draw_blob_back(self, ctx, R):
        if getattr(self, "backpack", None) is None:
            return
        ctx.save()
        ctx.rectangle(-R * 1.18, -R * 0.45, R * 0.5, R * 0.8)
        self._ink_fill(ctx, self.backpack, 3)
        ctx.restore()

    def _draw_blob_front(self, ctx, R):
        """Apron / tie / scarf / bag on a blob body (body frame, centre = 0, 0)."""
        if self.apron is not None:
            ctx.save()
            self._blob_path(ctx, R)
            ctx.clip()
            ctx.move_to(-R * 0.35, R * 0.05)
            ctx.line_to(R * 0.75, R * 0.05)
            ctx.line_to(R * 0.95, R * 1.3)
            ctx.line_to(-R * 0.55, R * 1.3)
            ctx.close_path()
            self._ink_fill(ctx, self.apron, 2.5)
            ctx.rectangle(R * 0.05, R * 0.38, R * 0.36, R * 0.22)
            ctx.set_source_rgb(*shade(self.apron, 0.85))
            ctx.fill()
            ctx.restore()
        if self.scarf is not None:
            ctx.save()
            self._blob_path(ctx, R)
            ctx.clip()
            ctx.rectangle(-R * 1.3, R * 0.42, R * 2.6, R * 0.2)
            self._ink_fill(ctx, self.scarf, 2.5)
            ctx.restore()
        if self.tie is not None:
            y0 = R * 0.62
            ctx.move_to(R * 0.3, y0)
            ctx.line_to(R * 0.4, y0 + R * 0.08)
            ctx.line_to(R * 0.38, y0 + R * 0.5)
            ctx.line_to(R * 0.3, y0 + R * 0.6)
            ctx.line_to(R * 0.22, y0 + R * 0.5)
            ctx.line_to(R * 0.2, y0 + R * 0.08)
            ctx.close_path()
            self._ink_fill(ctx, self.tie, 2)
        if self.bag is not None:
            ctx.move_to(-R * 0.5, -R * 0.6)
            ctx.line_to(R * 0.75, R * 0.55)
            ctx.set_line_width(4)
            ctx.set_source_rgb(*shade(self.bag, 0.7))
            ctx.stroke()
            ctx.rectangle(R * 0.6, R * 0.45, R * 0.38, R * 0.3)
            self._ink_fill(ctx, self.bag, 2.5)

    def _draw_face_wear(self, ctx, r, hat=True):
        """Glasses, facial hair, blush and hat in the face frame (eyes at x=0.2r/0.62r, y=-0.08r;
        mouth at 0.48r, 0.42r). The hat uses self._hat_anchor = (x, crown_y, width) when set."""
        if getattr(self, "blush", False):
            for x in (r * 0.05, r * 0.8):
                ctx.save()
                ctx.translate(x, r * 0.3)
                ctx.scale(r * 0.16, r * 0.09)
                ctx.arc(0, 0, 1, 0, 2 * math.pi)
                ctx.restore()
                ctx.set_source_rgba(1, 0.35, 0.45, 0.55)
                ctx.fill()
        fh = getattr(self, "facial_hair", None)
        ctx.save()
        ctx.translate(self._mouth_shift(r) if hasattr(self, "_face_c") else 0.0, 0)
        if fh in ("beard", "both"):
            ctx.move_to(r * 0.02, r * 0.18)
            ctx.curve_to(r * 0.0, r * 0.75, r * 0.3, r * 1.0, r * 0.52, r * 1.0)
            ctx.curve_to(r * 0.75, r * 1.0, r * 0.95, r * 0.7, r * 0.92, r * 0.2)
            ctx.curve_to(r * 0.8, r * 0.62, r * 0.2, r * 0.62, r * 0.02, r * 0.18)
            ctx.close_path()
            self._ink_fill(ctx, self.facial_hair_color, 2.2)
        if fh in ("mustache", "both"):
            for sgn in (-1, 1):
                ctx.save()
                ctx.translate(r * 0.48 + sgn * r * 0.13, r * 0.3)
                ctx.scale(r * 0.15, r * 0.07)
                ctx.arc(0, 0, 1, 0, 2 * math.pi)
                ctx.restore()
                self._ink_fill(ctx, self.facial_hair_color, 2)
        ctx.restore()
        g = getattr(self, "glasses", None)
        if g:
            gc = self.glasses_color
            ctx.set_line_width(max(2.0, r * 0.07))
            for ex in (r * 0.2, r * 0.62):
                ctx.new_path()
                if g == "square":
                    ctx.rectangle(ex - r * 0.2, -r * 0.08 - r * 0.17, r * 0.4, r * 0.32)
                else:
                    ctx.arc(ex, -r * 0.08, r * 0.21, 0, 2 * math.pi)
                if g == "sun":
                    ctx.set_source_rgba(0.08, 0.08, 0.12, 0.92)
                    ctx.fill_preserve()
                ctx.set_source_rgb(*gc)
                ctx.stroke()
                if g == "sun":
                    ctx.move_to(ex - r * 0.08, -r * 0.2)
                    ctx.line_to(ex + r * 0.02, -r * 0.13)
                    ctx.set_source_rgba(1, 1, 1, 0.6)
                    ctx.set_line_width(2)
                    ctx.stroke()
                    ctx.set_line_width(max(2.0, r * 0.07))
            ctx.move_to(r * 0.4, -r * 0.1)
            ctx.line_to(r * 0.42, -r * 0.1)
            ctx.move_to(r * -0.01, -r * 0.1)
            ctx.line_to(r * -0.55, -r * 0.02)
            ctx.set_source_rgb(*gc)
            ctx.stroke()
        if not hat:
            return
        hat = getattr(self, "hat", None)
        anchor = getattr(self, "_hat_anchor", None) or (0.0, -r, r)
        self._hat_anchor = None
        if hat:
            self._draw_hat(ctx, hat, anchor)

    def _draw_hat(self, ctx, hat, anchor):
        cx, top, w = anchor
        c = self.hat_color
        ctx.save()
        ctx.translate(cx, top)
        ctx.new_path()
        if hat == "cap":
            ctx.arc(0, w * 0.28, w * 0.86, math.pi, 2 * math.pi)
            ctx.close_path()
            self._ink_fill(ctx, c, 3)
            ctx.move_to(w * 0.5, w * 0.25)
            ctx.curve_to(w * 1.0, w * 0.2, w * 1.35, w * 0.28, w * 1.45, w * 0.36)
            ctx.line_to(w * 0.5, w * 0.36)
            ctx.close_path()
            self._ink_fill(ctx, shade(c, 0.8), 3)
            ctx.arc(0, -w * 0.58, w * 0.08, 0, 2 * math.pi)
            self._ink_fill(ctx, shade(c, 0.8), 2)
        elif hat == "beanie":
            ctx.arc(0, w * 0.3, w * 0.86, math.pi, 2 * math.pi)
            ctx.close_path()
            self._ink_fill(ctx, c, 3)
            ctx.rectangle(-w * 0.9, w * 0.12, w * 1.8, w * 0.26)
            self._ink_fill(ctx, shade(c, 0.85), 3)
            ctx.arc(0, -w * 0.6, w * 0.18, 0, 2 * math.pi)
            self._ink_fill(ctx, (1, 1, 1), 2.5)
        elif hat == "top_hat":
            ctx.save(); ctx.translate(0, w * 0.22); ctx.scale(w * 1.15, w * 0.16)
            ctx.arc(0, 0, 1, 0, 2 * math.pi); ctx.restore()
            self._ink_fill(ctx, c, 3)
            ctx.rectangle(-w * 0.62, -w * 1.05, w * 1.24, w * 1.25)
            self._ink_fill(ctx, c, 3)
            ctx.rectangle(-w * 0.62, -w * 0.05, w * 1.24, w * 0.2)
            self._ink_fill(ctx, (0.85, 0.2, 0.25), 2)
        elif hat == "chef":
            ctx.rectangle(-w * 0.62, -w * 0.15, w * 1.24, w * 0.42)
            self._ink_fill(ctx, c, 3)
            for dx, dy, rr in ((-0.45, -0.45, 0.42), (0.45, -0.45, 0.42), (0.0, -0.72, 0.5)):
                ctx.new_path()
                ctx.arc(w * dx, w * dy, w * rr, 0, 2 * math.pi)
                self._ink_fill(ctx, c, 3)
            ctx.rectangle(-w * 0.6, -w * 0.32, w * 1.2, w * 0.3)
            ctx.set_source_rgb(*c)
            ctx.fill()
        elif hat == "straw":
            ctx.save(); ctx.translate(0, w * 0.22); ctx.scale(w * 1.55, w * 0.22)
            ctx.arc(0, 0, 1, 0, 2 * math.pi); ctx.restore()
            self._ink_fill(ctx, c, 3)
            ctx.new_path()
            ctx.arc(0, w * 0.2, w * 0.68, math.pi, 2 * math.pi)
            ctx.close_path()
            self._ink_fill(ctx, c, 3)
            ctx.rectangle(-w * 0.68, w * 0.02, w * 1.36, w * 0.16)
            self._ink_fill(ctx, (0.85, 0.25, 0.3), 2)
        elif hat == "bow":
            for sgn in (-1, 1):
                ctx.move_to(0, w * 0.05)
                ctx.line_to(sgn * w * 0.55, -w * 0.25)
                ctx.line_to(sgn * w * 0.55, w * 0.35)
                ctx.close_path()
                self._ink_fill(ctx, c, 2.5)
            ctx.new_path()
            ctx.arc(0, w * 0.05, w * 0.13, 0, 2 * math.pi)
            self._ink_fill(ctx, shade(c, 0.8), 2)
        elif hat == "headscarf":  # Bunica: covers the crown and sides, knot under the chin
            ctx.move_to(-w * 0.98, w * 0.95)
            ctx.curve_to(-w * 1.15, -w * 0.2, -w * 0.6, -w * 0.32, 0, -w * 0.32)
            ctx.curve_to(w * 0.6, -w * 0.32, w * 1.12, -w * 0.15, w * 0.98, w * 0.55)
            ctx.curve_to(w * 0.75, w * 0.1, w * 0.5, -w * 0.02, 0, -w * 0.02)
            ctx.curve_to(-w * 0.55, -w * 0.02, -w * 0.78, w * 0.4, -w * 0.62, w * 1.05)
            ctx.close_path()
            self._ink_fill(ctx, c, 3)
            for dx, dy in ((-0.5, 0.1), (0.1, -0.15), (0.55, 0.12), (-0.8, 0.55)):  # polka dots
                ctx.arc(w * dx, w * dy, w * 0.06, 0, 2 * math.pi)
                ctx.set_source_rgba(1, 1, 1, 0.85)
                ctx.fill()
            ctx.new_path()
            ctx.arc(-w * 0.75, w * 1.12, w * 0.14, 0, 2 * math.pi)
            self._ink_fill(ctx, shade(c, 0.85), 2.5)
        ctx.restore()

    def _torso_details(self, ctx, hip, neck):
        # cel shading on the torso (back side) + belt
        ctx.new_path()
        ctx.move_to(hip[0] - 13, hip[1] - 4)
        ctx.line_to(neck[0] - 13, neck[1] + 4)
        ctx.set_line_width(9)
        ctx.set_line_cap(cairo.LINE_CAP_ROUND)
        ctx.set_source_rgba(*shade(self.body, 0.8), 0.9)
        ctx.stroke()
        ctx.new_path()
        ctx.move_to(hip[0] - 18, hip[1] + 2)
        ctx.line_to(hip[0] + 18, hip[1] + 2)
        ctx.set_line_width(8)
        ctx.set_source_rgb(*shade(self.pants, 0.9))
        ctx.stroke()

    def _blob_path(self, ctx, R):
        sh = self.shape
        if sh == "tall":  # carrot / banana / bottle
            ctx.save(); ctx.scale(R * 0.62, R * 1.25); ctx.arc(0, 0, 1, 0, 2 * math.pi); ctx.restore()
        elif sh == "egg":
            ctx.move_to(0, -R * 1.12)
            ctx.curve_to(R * 0.62, -R * 1.1, R * 0.95, -R * 0.1, R * 0.88, R * 0.35)
            ctx.curve_to(R * 0.8, R * 0.95, -R * 0.8, R * 0.95, -R * 0.88, R * 0.35)
            ctx.curve_to(-R * 0.95, -R * 0.1, -R * 0.62, -R * 1.1, 0, -R * 1.12)
            ctx.close_path()
        elif sh == "box":  # toaster / box / phone
            w, h, rr = R * 1.0, R * 0.9, R * 0.28
            ctx.new_sub_path()
            ctx.arc(w - rr, -h + rr, rr, -math.pi / 2, 0)
            ctx.arc(w - rr, h - rr, rr, 0, math.pi / 2)
            ctx.arc(-w + rr, h - rr, rr, math.pi / 2, math.pi)
            ctx.arc(-w + rr, -h + rr, rr, math.pi, 1.5 * math.pi)
            ctx.close_path()
        else:  # round: potato / orange / apple / tomato
            ctx.save(); ctx.scale(R * 0.95, R * 1.0); ctx.arc(0, 0, 1, 0, 2 * math.pi); ctx.restore()

    def draw_blob_body(self, ctx, now, R, face=True):
        """Big body that is also the face (fruit, vegetable, egg, toaster...). face=False: back view."""
        breath = 1 + 0.015 * math.sin(self.clock * 2.2)
        ctx.save()
        ctx.scale(1 / breath, breath)
        fxd = self.__dict__.get("_dial_fx")
        if fxd and fxd.get("chest"):  # smart-bone swell (#4)
            ctx.scale(1 + 0.55 * fxd["chest"], 1 + 0.25 * fxd["chest"])
        self._draw_blob_back(ctx, R)
        # top decoration behind/above the body
        if self.top in ("leaf", "leaves"):
            for a in (-0.35, 0.0, 0.35):
                ctx.save()
                ctx.translate(0, -R * (1.2 if self.shape == "tall" else 0.95))
                ctx.rotate(a + 0.1 * math.sin(self.clock * 3 + a))
                ctx.move_to(0, 0)
                ctx.curve_to(R * 0.18, -R * 0.2, R * 0.12, -R * 0.55, 0, -R * 0.62)
                ctx.curve_to(-R * 0.12, -R * 0.55, -R * 0.18, -R * 0.2, 0, 0)
                ctx.set_source_rgb(0.35, 0.72, 0.35)
                ctx.fill_preserve()
                ctx.set_source_rgb(*INK)
                ctx.set_line_width(3)
                ctx.stroke()
                ctx.restore()
        elif self.top == "stem":
            ctx.move_to(0, -R * 0.95)
            ctx.curve_to(R * 0.05, -R * 1.15, R * 0.15, -R * 1.25, R * 0.22, -R * 1.3)
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(5)
            ctx.stroke()
        self._blob_path(ctx, R)
        ctx.set_source_rgb(*self.body)
        ctx.fill_preserve()
        ctx.save()
        ctx.clip()
        ctx.arc(-R * 0.55, R * 0.45, R * 1.0, 0, 2 * math.pi)  # cel shade
        ctx.set_source_rgba(*shade(self.body, 0.7), 0.4)
        ctx.fill()
        ctx.arc(R * 0.35, -R * 0.55, R * 0.18, 0, 2 * math.pi)  # highlight
        ctx.set_source_rgba(1, 1, 1, 0.45)
        ctx.fill()
        if self.shape == "round" and self.top is None:  # potato spots
            for (dx, dy) in ((-0.5, -0.4), (0.55, 0.3), (-0.2, 0.6)):
                ctx.arc(R * dx, R * dy, R * 0.06, 0, 2 * math.pi)
                ctx.set_source_rgba(*shade(self.body, 0.6), 0.8)
                ctx.fill()
        if self.shape == "box":  # toaster slots
            for dx in (-0.35, 0.25):
                ctx.rectangle(R * dx, -R * 0.9, R * 0.3, R * 0.12)
                ctx.set_source_rgba(*INK, 0.85)
                ctx.fill()
        ctx.restore()
        self._blob_path(ctx, R)
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(3.8)
        ctx.stroke()
        self._draw_blob_front(ctx, R)
        ctx.restore()
        # face: reuse the cartoon eyes/brows/mouth on a virtual head
        r = R * 0.62
        top = {"tall": 1.25, "egg": 1.12, "box": 0.9}.get(getattr(self, "shape", "round"), 1.0)
        self._hat_anchor = (r * 0.15, -R * top + R * 0.12, R * (0.55 if self.shape == "tall" else 0.8))
        if not face:  # back view: no face, the hat (if any) sits centred
            ys = self.sp_yaw.x
            self.sp_yaw.x = 0.0
            try:
                ctx.save()
                ctx.translate(-r * 0.15, -R * 0.12)
                self._draw_face_hat(ctx, r)
                ctx.restore()
            finally:
                self.sp_yaw.x = ys
            return
        ctx.save()
        ctx.translate(-r * 0.15, -R * 0.12)
        self._cartoon_face(ctx, now, r)
        ctx.restore()

    def _cartoon_face(self, ctx, now, r, mouth=True):
        ctx.save()
        self._face_xform(ctx, r, 0.41)
        expr = self.expression(now)
        txt, prog, shape = self.talking(now)
        blink = ((self.clock + self.blink_off) % 3.6) < 0.13
        big = {"surprised": 1.25, "scared": 1.3, "excited": 1.15}.get(expr, 1.0) * getattr(self, "eye_scale", 1.0)
        lid = 0.42 if expr == "sleepy" else (0.7 if expr == "angry" else 1.0)
        pup = {"scared": 0.05, "excited": 0.11}.get(expr, 0.09)
        lx, ly = self.look
        lx *= self._yaw_view()[0]
        fv = self._fv = self._face_vals(now)
        for ex in (r * 0.2, r * 0.62):
            ey = -r * 0.08
            side = 1 if ex < r * 0.4 else -1
            if fv:
                self._fv_eye(ctx, ex, ey, r, big, 0.12 if blink else lid, pup, lx, ly, blink, fv, side)
            else:
                ctx.save()
                ctx.translate(ex, ey)
                ctx.scale(r * 0.17 * big, r * 0.22 * big * (0.12 if blink else lid))
                ctx.arc(0, 0, 1, 0, 2 * math.pi)
                ctx.restore()
                ctx.set_source_rgb(1, 1, 1)
                ctx.fill_preserve()
                ctx.set_source_rgb(*INK)
                ctx.set_line_width(2.5)
                ctx.stroke()
                if not blink:
                    px, py = ex + lx * r * 0.08, ey - ly * r * 0.1
                    ctx.arc(px, py, r * pup, 0, 2 * math.pi)
                    ctx.set_source_rgb(*INK)
                    ctx.fill()
                    ctx.arc(px + r * 0.03, py - r * 0.05, r * 0.03, 0, 2 * math.pi)
                    ctx.set_source_rgb(1, 1, 1)
                    ctx.fill()
            tilt = {"determined": 5, "sad": -5, "crying": -6, "surprised": -1, "angry": 10, "scared": -7,
                    "sleepy": -2}.get(expr, 0)
            by = ey - r * 0.36 * big - (r * 0.14 if expr == "confused" and side < 0 else 0)
            if fv:
                by -= fv["brow_l" if side > 0 else "brow_r"] * r * 0.16 - fv["cheek"] * r * 0.03
                tilt += 11 * fv["brow_angle"]
                ctx.new_path()
            ctx.move_to(ex - r * 0.15, by - tilt * side * 0.5)
            ctx.line_to(ex + r * 0.15, by + tilt * side * 0.5)
            ctx.set_line_width(3.5)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.set_source_rgb(*INK)
            ctx.stroke()
        self._cheeks(ctx, r, expr)
        if mouth:
            self._turned_mouth(ctx, self._mouth_now(shape, txt), expr, r)
        self._draw_face_wear(ctx, r, hat=False)
        self.draw_expression_extras(ctx, expr, r)
        ctx.restore()
        self._fv = None
        self._draw_face_hat(ctx, r)

    def draw_stick_head(self, ctx, now, r):
        """3D-looking sphere head (radial gradient) with a minimal face."""
        base = self.body
        g = cairo.RadialGradient(r * 0.35, -r * 0.4, r * 0.1, 0, 0, r * 1.05)
        g.add_color_stop_rgb(0, *tuple(min(1, c * 1.2 + 0.25) for c in base))
        g.add_color_stop_rgb(0.65, *base)
        g.add_color_stop_rgb(1, *shade(base, 0.55))
        ctx.arc(0, 0, r, 0, 2 * math.pi)
        ctx.set_source(g)
        ctx.fill()
        expr = self.expression(now)
        txt, prog, shape = self.talking(now)
        blink = ((self.clock + self.blink_off) % 3.6) < 0.13
        lx, ly = self.look
        big = {"surprised": 1.4, "scared": 1.5, "excited": 1.2}.get(expr, 1.0)
        lx *= self._yaw_view()[0]
        ctx.save()
        self._face_xform(ctx, r, 0.375)
        fv = self._fv = self._face_vals(now)
        for ex in (r * 0.15, r * 0.6):
            ey = -r * 0.1
            ctx.save()
            ctx.translate(ex + lx * r * 0.05, ey - ly * r * 0.06)
            hgt = 0.12 if blink else (0.45 if expr == "sleepy" else 1.0)
            if fv:
                hgt *= max(0.1, 1 - 0.9 * clamp(fv["lid_l" if ex < r * 0.4 else "lid_r"], 0, 1)) * (1 - 0.4 * fv["cheek"])
            ctx.scale(r * 0.09 * big, r * 0.13 * big * hgt)
            ctx.arc(0, 0, 1, 0, 2 * math.pi)
            ctx.restore()
            ctx.set_source_rgb(*INK)
            ctx.fill()
            tilt = {"determined": 5, "sad": -5, "crying": -6, "angry": 10, "scared": -7}.get(expr, 0)
            side = 1 if ex < r * 0.4 else -1
            by = ey - r * 0.32 * big - (r * 0.14 if expr == "confused" and side < 0 else 0)
            if fv:
                by -= fv["brow_l" if side > 0 else "brow_r"] * r * 0.16
                tilt += 11 * fv["brow_angle"]
            if tilt or expr in ("confused", "surprised") or fv:
                ctx.move_to(ex - r * 0.13, by - tilt * side * 0.5)
                ctx.line_to(ex + r * 0.13, by + tilt * side * 0.5)
                ctx.set_line_width(3)
                ctx.set_line_cap(cairo.LINE_CAP_ROUND)
                ctx.set_source_rgb(*INK)
                ctx.stroke()
        self._turned_mouth(ctx, self._mouth_now(shape, txt), expr, r)
        self._draw_face_wear(ctx, r, hat=False)
        self.draw_expression_extras(ctx, expr, r)
        ctx.restore()
        self._fv = None
        self._draw_face_hat(ctx, r)

    # ------------------------------------------------------------ animals (Farm Files)
    @staticmethod
    def _ik_back(hip, foot, l1, l2):
        """Knee position of a two-bone limb whose joint bends backwards (hind legs, bird legs)."""
        dx, dy = foot[0] - hip[0], foot[1] - hip[1]
        L = clamp(math.hypot(dx, dy), abs(l1 - l2) + 1e-3, l1 + l2 - 1e-3)
        base = math.atan2(dx, dy)
        a = math.acos(clamp((l1 * l1 + L * L - l2 * l2) / (2 * l1 * L), -1, 1))
        th = base - a
        return (hip[0] + l1 * math.sin(th), hip[1] + l1 * math.cos(th))

    @staticmethod
    def _tube(ctx, pts, w, col, ink=True):
        for width, c in (((w + 5, INK), (w, col)) if ink else ((w, col),)):
            ctx.new_path()
            ctx.move_to(*pts[0])
            for p in pts[1:]:
                ctx.line_to(*p)
            ctx.set_line_width(width)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.set_line_join(cairo.LINE_JOIN_ROUND)
            ctx.set_source_rgb(*c)
            ctx.stroke()

    @staticmethod
    def _ellipse(ctx, cx, cy, rx, ry, rot=0.0):
        ctx.save()
        ctx.translate(cx, cy)
        ctx.rotate(rot)
        ctx.scale(max(rx, 0.1), max(ry, 0.1))
        ctx.arc(0, 0, 1, 0, 2 * math.pi)
        ctx.restore()

    def _fill_ink(self, ctx, col, lw=3.2):
        ctx.set_source_rgb(*col)
        ctx.fill_preserve()
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(lw)
        ctx.stroke()

    def _animal_leg(self, ctx, hip, th, kn, w, col, back=False, hoof=None, toes=None):
        L1, L2 = self.THIGH, self.SHIN
        foot = (hip[0] + L1 * math.sin(th) + L2 * math.sin(th - kn),
                hip[1] + L1 * math.cos(th) + L2 * math.cos(th - kn))
        knee = self._ik_back(hip, foot, L1, L2) if back else \
            (hip[0] + L1 * math.sin(th), hip[1] + L1 * math.cos(th))
        self._tube(ctx, [hip, knee, foot], w, col)
        if hoof:
            self._ellipse(ctx, foot[0] + 1.5, foot[1] - 2, w * 0.62, w * 0.42)
            self._fill_ink(ctx, hoof, 2.5)
        if toes:
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            for dx, dy in ((9, 1), (7, 4), (-6, 1)):
                ctx.move_to(*foot)
                ctx.line_to(foot[0] + dx, foot[1] + dy - 1)
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(w + 3)
            ctx.stroke_preserve()
            ctx.set_source_rgb(*toes)
            ctx.set_line_width(w)
            ctx.stroke()
        return foot

    def _animal_hip(self, P):
        if P.get("ik", 0) > 0.5:
            h = P["hipIK"]
        else:
            h = max(self.leg_extent(P["thighF"], P["kneeF"]), self.leg_extent(P["thighB"], P["kneeB"])) + P["hip"]
        return max(h, 6.0)

    def _draw_animal(self, ctx, now, P):
        if self.style == "bird":
            return self._draw_bird(ctx, now, P)
        return self._draw_quadruped(ctx, now, P)

    def _draw_quadruped(self, ctx, now, P):
        sp = self.spec
        br, blen = sp["br"], sp["blen"]
        hipH = self._animal_hip(P)
        walking = P.get("ik", 0) > 0.5
        breath = 1 + 0.025 * math.sin(self.clock * 2.2)
        tilt = clamp(P["torso"] * 0.35, -0.45, 0.4)
        cs, sn = math.cos(tilt), math.sin(tilt)
        cx, cy = 0.0, -hipH - br * 0.35

        def R(dx, dy):
            return (cx + dx * cs - dy * sn, cy + dx * sn + dy * cs)

        hind, fore = R(-blen * 0.38, br * 0.35), R(blen * 0.38, br * 0.35)
        col, dark = self.body, shade(self.body, 0.78)
        w = max(7.0, br * 0.42)
        hoof = hex2rgb(sp["hoof"]) if sp.get("hoof") else None
        gk, gw = getattr(self, "_gkind", None), getattr(self, "_gw", 0.0)
        # near front leg lifts for wave / point / cheer (animals "gesture" with a hoof)
        lift = None
        if gk in ("wave", "point", "fist", "hands_up") or P["armUF"] > 1.4:
            k = gw if gk else clamp((P["armUF"] - 1.4) / 1.2, 0, 1)
            th = 1.2 + (0.3 * math.sin(now * 12) if gk == "wave" else 0.0)
            lift = (lerp(P["thighB"], th, k), lerp(P["kneeB"], 1.5, k))
        # far legs
        self._animal_leg(ctx, fore, P["thighF"], P["kneeF"], w, dark, hoof=hoof and shade(hoof, 0.8))
        self._animal_leg(ctx, hind, P["thighB"], P["kneeB"], w, dark, back=True, hoof=hoof and shade(hoof, 0.8))
        # tail (spring follow-through + idle wag)
        self._quad_tail(ctx, now, R(-blen * 0.5 - br * 0.45, -br * 0.35), br)
        # body
        rx, ry = blen / 2 + br * 0.55, br * breath
        if sp.get("wool"):
            for i in range(9):
                a = 2 * math.pi * i / 9
                self._ellipse(ctx, cx + rx * 0.82 * math.cos(a), cy + ry * 0.78 * math.sin(a), br * 0.48, br * 0.45, tilt)
                self._fill_ink(ctx, col, 3)
            self._ellipse(ctx, cx, cy, rx * 0.95, ry * 0.92, tilt)
            ctx.set_source_rgb(*col)
            ctx.fill()
        else:
            self._ellipse(ctx, cx, cy, rx, ry, tilt)
            ctx.set_source_rgb(*col)
            ctx.fill_preserve()
            ctx.save()
            ctx.clip()
            pat = self.pattern
            if sp.get("spots"):
                for dx, dy, r_ in ((-0.45, -0.35, 0.38), (0.2, 0.1, 0.32), (0.55, -0.45, 0.22), (-0.1, 0.65, 0.25)):
                    self._ellipse(ctx, *R(rx * dx, ry * dy), br * r_ * 1.25, br * r_, tilt + dx)
                    ctx.set_source_rgb(*pat)
                    ctx.fill()
            if sp.get("stripes"):
                for i in range(4):
                    x0 = -rx * 0.55 + i * rx * 0.32
                    ctx.move_to(*R(x0, -ry))
                    ctx.line_to(*R(x0 + 6, -ry * 0.25))
                ctx.set_source_rgb(*pat)
                ctx.set_line_width(6)
                ctx.stroke()
            if sp["tail"] in ("wag", "up"):  # lighter belly
                self._ellipse(ctx, *R(0, ry * 0.75), rx * 0.7, ry * 0.45, tilt)
                ctx.set_source_rgba(*self.pattern, 0.55)
                ctx.fill()
            self._ellipse(ctx, *R(0, ry * 0.9), rx * 1.1, ry * 0.55, tilt)  # cel shade
            ctx.set_source_rgba(*shade(col, 0.72), 0.45)
            ctx.fill()
            ctx.restore()
            self._ellipse(ctx, cx, cy, rx, ry, tilt)
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(3.5)
            ctx.stroke()
        # near legs
        self._animal_leg(ctx, hind, P["thighF"], P["kneeF"], w, col, back=True, hoof=hoof)
        lt, lk = lift if lift else (P["thighB"], P["kneeB"])
        self._animal_leg(ctx, fore, lt, lk, w, col, hoof=hoof)
        # neck + head
        hr = self.head_r
        talking = self.talking(now)[0] is not None
        bob = 2.5 * math.sin(2 * self.phase) if walking else 0.0
        nod = 0.08 * math.sin(now * 9) if (talking or gk == "talk") else 0.0
        ha = P["head"] * 0.8 + self.sp_head.x + nod
        base = R(blen * 0.42, -br * 0.35)
        nk = sp["neck"]
        hc = (base[0] + nk * 0.55 * math.cos(ha) + nk * math.sin(ha) * 0.4,
              base[1] - nk + nk * 0.55 * math.sin(ha) + bob)
        if nk > 4:
            self._tube(ctx, [base, hc], br * 0.7, col)
        ctx.save()
        ctx.translate(*hc)
        ctx.rotate(ha)
        self._quad_head(ctx, now, hr, gk)
        ctx.restore()
        return hc, hr

    def _quad_tail(self, ctx, now, root, br):
        kind = self.spec["tail"]
        sw = self.sp_hair.x + 0.15 * math.sin(self.clock * 2.5)
        if kind == "wag" and self.expression(now) in ("happy", "excited"):
            sw += 0.4 * math.sin(now * 14)
        x, y = root
        ctx.set_line_cap(cairo.LINE_CAP_ROUND)
        if kind == "curly":
            ctx.new_path()
            for i in range(24):
                a = i * 0.45
                rr = 3 + i * 0.35
                ctx.line_to(x - 6 - rr * math.cos(a + sw), y - rr * math.sin(a + sw))
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(7)
            ctx.stroke_preserve()
            ctx.set_source_rgb(*self.body)
            ctx.set_line_width(3.5)
            ctx.stroke()
            return
        if kind == "puff":
            self._ellipse(ctx, x - 4, y, br * 0.32, br * 0.3)
            self._fill_ink(ctx, self.body, 3)
            return
        length, curl, w, a0 = {"up": (br * 0.7, -1.2, 7, math.pi + 0.9), "long": (br * 1.4, 0.45, 4.5, -0.45),
                               "wag": (br * 1.1, -0.8, 7, math.pi + 0.9),
                               "cat": (br * 2.0, -1.6, 7, math.pi + 0.9)}[kind]
        pts = [(x, y)]
        a = a0 + sw * (0.5 if kind == "long" else 1.0)
        for i in range(1, 7):
            a += curl / 6
            px, py = pts[-1]
            pts.append((px + length / 6 * math.sin(a), py + length / 6 * math.cos(a)))
        self._tube(ctx, pts, w, self.body)
        if kind == "long":  # tuft
            self._ellipse(ctx, pts[-1][0], pts[-1][1] + 3, 5, 8)
            self._fill_ink(ctx, self.pattern, 2.5)

    def _quad_head(self, ctx, now, hr, gk):
        sp = self.spec
        col = self.pattern if sp.get("wool") else self.body
        wig = 0.45 * math.sin(now * 20) if gk == "shrug" else 0.08 * math.sin(self.clock * 1.7)
        # ears (behind the head)
        ears = sp["ears"]
        ctx.save()
        if ears == "pointy":
            for ex in (-0.55, 0.1):
                ctx.move_to(hr * ex, -hr * 0.55)
                ctx.line_to(hr * (ex + 0.2) + wig * 6, -hr * 1.35)
                ctx.line_to(hr * (ex + 0.55), -hr * 0.65)
                ctx.close_path()
                self._fill_ink(ctx, col, 3)
        elif ears == "floppy":
            ctx.save()
            ctx.translate(-hr * 0.45, -hr * 0.45)
            ctx.rotate(0.35 + wig)
            self._ellipse(ctx, 0, hr * 0.55, hr * 0.32, hr * 0.68)
            self._fill_ink(ctx, shade(col, 0.75), 3)
            ctx.restore()
        elif ears == "pig":
            ctx.move_to(-hr * 0.2, -hr * 0.6)
            ctx.line_to(hr * 0.35 + wig * 5, -hr * 1.25)
            ctx.line_to(hr * 0.45, -hr * 0.5)
            ctx.close_path()
            self._fill_ink(ctx, shade(col, 0.9), 3)
        else:  # side ears
            ctx.save()
            ctx.translate(-hr * 0.55, -hr * 0.35)
            ctx.rotate(-0.9 + wig)
            self._ellipse(ctx, 0, -hr * 0.42, hr * 0.2, hr * 0.48)
            self._fill_ink(ctx, shade(col, 0.85), 3)
            ctx.restore()
        ctx.restore()
        # horns
        if sp.get("horns") == "goat":
            for dx in (-0.35, 0.05):
                ctx.move_to(hr * dx, -hr * 0.7)
                ctx.curve_to(hr * (dx - 0.15), -hr * 1.35, hr * (dx - 0.6), -hr * 1.45, hr * (dx - 0.85), -hr * 1.1)
                ctx.set_source_rgb(*INK)
                ctx.set_line_width(hr * 0.3 + 4)
                ctx.set_line_cap(cairo.LINE_CAP_ROUND)
                ctx.stroke_preserve()
                ctx.set_source_rgb(*self.horn)
                ctx.set_line_width(hr * 0.3)
                ctx.stroke()
        elif sp.get("horns") == "cow":
            for dx in (-0.45, 0.25):
                ctx.move_to(hr * dx, -hr * 0.7)
                ctx.curve_to(hr * (dx - 0.1), -hr * 1.05, hr * (dx + 0.15), -hr * 1.2, hr * (dx + 0.3), -hr * 1.25)
                ctx.set_source_rgb(*INK)
                ctx.set_line_width(hr * 0.24 + 4)
                ctx.set_line_cap(cairo.LINE_CAP_ROUND)
                ctx.stroke_preserve()
                ctx.set_source_rgb(*self.horn)
                ctx.set_line_width(hr * 0.24)
                ctx.stroke()
        # head + snout
        self._ellipse(ctx, 0, 0, hr, hr * 0.88)
        self._fill_ink(ctx, col, 3.5)
        sn = sp["snout"]
        if sp.get("pig_snout"):
            self._ellipse(ctx, hr * 0.95, hr * 0.15, hr * 0.22, hr * 0.32)
            self._fill_ink(ctx, shade(col, 0.88), 3)
            for dy in (0.02, 0.28):
                self._ellipse(ctx, hr * 1.0, hr * dy, hr * 0.05, hr * 0.07)
                ctx.set_source_rgb(*INK)
                ctx.fill()
        elif sn > 0.4:
            mcol = hex2rgb(sp["muzzle"]) if sp.get("muzzle") else shade(col, 0.95)
            self._ellipse(ctx, hr * 0.72, hr * 0.28, hr * 0.62 * sn, hr * 0.5 * sn)
            self._fill_ink(ctx, mcol, 3)
            self._ellipse(ctx, hr * (0.72 + 0.45 * sn), hr * 0.12, hr * 0.06, hr * 0.05)
            ctx.set_source_rgb(*INK)
            ctx.fill()
        else:  # cat nose
            ctx.move_to(hr * 0.78, hr * 0.12)
            ctx.line_to(hr * 0.92, hr * 0.12)
            ctx.line_to(hr * 0.85, hr * 0.22)
            ctx.close_path()
            ctx.set_source_rgb(0.9, 0.45, 0.55)
            ctx.fill()
            for dy in (0.15, 0.3):  # whiskers
                ctx.move_to(hr * 0.75, hr * dy)
                ctx.line_to(hr * 1.35, hr * (dy - 0.08))
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(1.6)
            ctx.stroke()
        if sp.get("beard"):
            ctx.move_to(hr * 0.35, hr * 0.7)
            ctx.line_to(hr * 0.6, hr * 1.25 + 2 * math.sin(self.clock * 3))
            ctx.line_to(hr * 0.75, hr * 0.68)
            ctx.close_path()
            self._fill_ink(ctx, self.pattern, 2.5)
        if sp.get("wool"):  # wool tuft on the forehead
            for dx, dy in ((-0.35, -0.75), (0.0, -0.88), (0.35, -0.75)):
                self._ellipse(ctx, hr * dx, hr * dy, hr * 0.3, hr * 0.26)
                self._fill_ink(ctx, self.body, 2.5)
        self._hat_anchor = (hr * 0.28, -hr * 0.86, hr * 0.8)
        ctx.save()
        ctx.translate(-hr * 0.28, -hr * 0.14)
        self._cartoon_face(ctx, now, hr * 0.95)
        ctx.restore()

    def _draw_bird(self, ctx, now, P):
        sp = self.spec
        br = sp["br"]
        hipH = self._animal_hip(P)
        walking = P.get("ik", 0) > 0.5
        breath = 1 + 0.03 * math.sin(self.clock * 2.6)
        tilt = clamp(P["torso"] * 0.4, -0.5, 0.45)
        cs, sn = math.cos(tilt), math.sin(tilt)
        cx, cy = 0.0, -hipH - br * 0.72

        def R(dx, dy):
            return (cx + dx * cs - dy * sn, cy + dx * sn + dy * cs)

        col, pat = self.body, self.pattern
        legc = hex2rgb(sp["leg"])
        airborne = self.y > 2
        flap = 0.55 * math.sin(now * 30) if (airborne or getattr(self, "_gkind", None) == "hands_up") else 0.0
        # far leg + far wing
        self._animal_leg(ctx, (-3, -hipH), P["thighB"], P["kneeB"], 4, shade(legc, 0.8), back=True,
                         toes=shade(legc, 0.8))
        self._bird_wing(ctx, R(br * 0.15, -br * 0.2), br, P["armUB"], flap, shade(pat, 0.85))
        # tail feathers
        tx, ty = R(-br * 1.05, -br * 0.25)
        tk = sp["tail"]
        for i, a in enumerate((-0.9, -0.55, -0.2) if tk == "chicken" else ((-0.35, 0.0, 0.35) if tk == "fan" else (-0.3,))):
            ctx.save()
            ctx.translate(tx, ty)
            ctx.rotate(a - tilt * 0.3 + 0.08 * math.sin(self.clock * 3 + i))
            self._ellipse(ctx, -br * 0.38, 0, br * 0.45, br * 0.16)
            self._fill_ink(ctx, pat if i % 2 else col, 3)
            ctx.restore()
        # body
        self._ellipse(ctx, cx, cy, br * 1.15, br * breath, tilt)
        ctx.set_source_rgb(*col)
        ctx.fill_preserve()
        ctx.save()
        ctx.clip()
        self._ellipse(ctx, *R(0, br * 0.85), br * 1.3, br * 0.6, tilt)
        ctx.set_source_rgba(*shade(col, 0.75), 0.45)
        ctx.fill()
        if sp.get("iridescent"):
            self._ellipse(ctx, *R(br * 0.75, -br * 0.55), br * 0.5, br * 0.35, tilt)
            ctx.set_source_rgba(0.35, 0.7, 0.55, 0.6)
            ctx.fill()
        ctx.restore()
        self._ellipse(ctx, cx, cy, br * 1.15, br * breath, tilt)
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(3.5)
        ctx.stroke()
        # near leg + near wing
        self._animal_leg(ctx, (3, -hipH), P["thighF"], P["kneeF"], 4, legc, back=True, toes=legc)
        self._bird_wing(ctx, R(br * 0.05, -br * 0.15), br, P["armUF"], -flap, pat)
        # neck + head
        hr = self.head_r
        peck = 3.5 * math.sin(2 * self.phase) if walking else 0.0
        talking = self.talking(now)[0] is not None
        ha = P["head"] * 0.7 + self.sp_head.x + (0.06 * math.sin(now * 9) if talking else 0)
        base = R(br * 0.75, -br * 0.55)
        hc = (base[0] + br * 0.15 + peck, base[1] - sp["neck"] - hr * 0.6)
        self._tube(ctx, [base, hc], hr * 1.2, col)
        if sp.get("iridescent"):
            self._tube(ctx, [base, hc], hr * 0.9, (0.45, 0.62, 0.6), ink=False)
        ctx.save()
        ctx.translate(*hc)
        ctx.rotate(ha)
        self._bird_head(ctx, now, hr)
        ctx.restore()
        return hc, hr

    def _bird_wing(self, ctx, pivot, br, armU, flap, col):
        lift = clamp((armU - 0.12) * 0.6, -0.3, 1.9) + flap
        ctx.save()
        ctx.translate(*pivot)
        ctx.rotate(lift)
        ctx.move_to(br * 0.25, 0)
        ctx.curve_to(br * 0.2, -br * 0.55, -br * 0.9, -br * 0.45, -br * 1.15, br * 0.15)
        ctx.curve_to(-br * 0.7, br * 0.45, br * 0.1, br * 0.45, br * 0.25, 0)
        ctx.close_path()
        self._fill_ink(ctx, col, 3)
        for k in (0.35, 0.65):  # feather lines
            ctx.move_to(-br * k, br * 0.05)
            ctx.line_to(-br * (k + 0.25), br * 0.2)
        ctx.set_source_rgba(*INK, 0.5)
        ctx.set_line_width(2)
        ctx.stroke()
        ctx.restore()

    def _bird_head(self, ctx, now, hr):
        sp = self.spec
        if sp.get("comb"):
            for i, dx in enumerate((-0.35, 0.0, 0.32)):
                self._ellipse(ctx, hr * dx, -hr * (0.95 + 0.1 * (i == 1)), hr * 0.24, hr * 0.32)
                self._fill_ink(ctx, (0.9, 0.2, 0.22), 2.5)
        self._ellipse(ctx, 0, 0, hr, hr)
        self._fill_ink(ctx, self.body, 3.2)
        txt, prog, shape = self.talking(now)
        o = {"A": 0.0, "B": 0.25, "C": 0.6, "D": 1.0, "E": 0.5, "F": 0.3}.get(shape, 0.0) if txt else 0.0
        if self.expression(now) in ("surprised", "scared"):
            o = max(o, 0.5)
        bc = hex2rgb(sp["beak"])
        L = 1.75 if sp.get("bill") else 1.5
        ctx.set_line_join(cairo.LINE_JOIN_ROUND)
        ctx.move_to(hr * 0.72, -hr * 0.3)  # upper beak
        ctx.line_to(hr * L, -hr * (0.02 + 0.22 * o))
        ctx.line_to(hr * 0.78, hr * 0.06)
        ctx.close_path()
        self._fill_ink(ctx, bc, 2.6)
        ctx.move_to(hr * 0.78, hr * 0.1)  # lower beak
        ctx.line_to(hr * (L - 0.15), hr * (0.12 + 0.35 * o))
        ctx.line_to(hr * 0.8, hr * 0.34)
        ctx.close_path()
        self._fill_ink(ctx, shade(bc, 0.85), 2.6)
        if sp.get("comb"):  # wattle
            self._ellipse(ctx, hr * 0.78, hr * 0.55, hr * 0.16, hr * 0.26)
            self._fill_ink(ctx, (0.9, 0.2, 0.22), 2.2)
        self._hat_anchor = (hr * 0.5, -hr * 0.82, hr * 0.85)
        ctx.save()
        ctx.translate(-hr * 0.5, -hr * 0.18)
        self._cartoon_face(ctx, now, hr * 1.05, mouth=False)
        ctx.restore()

    def draw_mouth(self, ctx, shape, expr, r):
        mx, my = r * 0.48, r * 0.42
        ctx.new_path()
        fv = getattr(self, "_fv", None)
        mc = fv["mouth_curve"] if fv else 0.0
        if mc and (shape != "X" or expr in ("surprised", "dizzy", "sleepy", "excited", "scared")):
            self._mouth_corners(ctx, mx, my, r, mc, shape)

        def oval(w, h, fill=(0.55, 0.12, 0.2), teeth=False, tongue=False, lw=2.6):
            ctx.save()
            ctx.translate(mx, my)
            ctx.scale(max(w, 0.5), max(h, 0.5))
            ctx.arc(0, 0, 1, 0, 2 * math.pi)
            ctx.restore()
            ctx.set_source_rgb(*fill)
            ctx.fill_preserve()
            ctx.save()
            ctx.clip_preserve()
            if teeth:
                ctx.rectangle(mx - w, my - h, 2 * w, h * 0.55)
                ctx.set_source_rgb(1, 1, 1)
                ctx.fill()
            if tongue:
                ctx.arc(mx + w * 0.15, my + h * 0.9, w * 0.6, 0, 2 * math.pi)
                ctx.set_source_rgb(0.95, 0.45, 0.5)
                ctx.fill()
            ctx.restore()
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(lw)
            ctx.stroke()

        if shape == "A":  # closed M/B/P
            ctx.move_to(mx - r * 0.17, my)
            ctx.line_to(mx + r * 0.19, my)
            ctx.set_line_width(3.6)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.set_source_rgb(*INK)
            ctx.stroke()
        elif shape == "B":  # slightly open, teeth
            oval(r * 0.2, r * 0.075, fill=(1, 1, 1))
        elif shape == "C":
            oval(r * 0.2, r * 0.15, teeth=True)
        elif shape == "D":
            oval(r * 0.24, r * 0.24, teeth=True, tongue=True)
        elif shape == "E":
            oval(r * 0.15, r * 0.17, tongue=True)
        elif shape == "F":
            oval(r * 0.09, r * 0.1, lw=4.2)
        elif expr in ("surprised", "dizzy"):
            oval(r * 0.14, r * 0.16)
        elif expr == "sleepy":
            oval(r * 0.07, r * 0.06)
        elif expr == "excited":
            oval(r * 0.22, r * 0.17, teeth=True, tongue=True)
        elif expr == "scared":
            ctx.move_to(mx - r * 0.2, my)
            for i in range(1, 7):
                ctx.line_to(mx - r * 0.2 + i * r * 0.07, my + (3 if i % 2 else -3))
            ctx.set_line_width(3)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.set_source_rgb(*INK)
            ctx.stroke()
        else:
            d = -1 if expr in ("sad", "angry", "crying") else 1
            if mc:
                d = clamp(d * 0.6 + 1.6 * mc, -1.4, 1.4) if d > 0 else clamp(d + 2.0 * mc, -1.4, 1.4)
            ctx.move_to(mx - r * 0.2, my - d * 3)
            ctx.curve_to(mx - r * 0.1, my + d * r * 0.2, mx + r * 0.12, my + d * r * 0.2,
                         mx + r * 0.22, my - d * 4)
            ctx.set_line_width(3.2)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.set_source_rgb(*INK)
            ctx.stroke()

    def _mouth_corners(self, ctx, mx, my, r, mc, shape):
        """Smile / frown ticks at the mouth corners (mouth_curve over lip-sync shapes)."""
        w = {"A": 0.2, "B": 0.22, "C": 0.22, "D": 0.26, "E": 0.17, "F": 0.11}.get(shape, 0.18) * r
        for sx in (-1, 1):
            ctx.move_to(mx + sx * w, my)
            ctx.line_to(mx + sx * (w + r * 0.07), my - mc * r * 0.11)
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(2.6)
        ctx.set_line_cap(cairo.LINE_CAP_ROUND)
        ctx.stroke()

    def draw_head(self, ctx, now, r):
        if getattr(self, "style", "toon") == "stick":
            return self.draw_stick_head(ctx, now, r)
        hs = self.hair_style
        fp, sg = self._yaw_view()
        bx = fp * sg  # back-of-head offset factor: 1 profile, 0 front, -1 looking back
        if hs == "ponytail":
            sw = 0.12 * math.sin(self.clock * 5) + self.sp_hair.x
            ctx.save()
            ctx.translate(-r * 0.85 * bx, -r * 0.35)
            ctx.rotate(0.5 - sw)
            ctx.scale(r * 0.45, r * 0.75)
            ctx.arc(0, 0.7, 1, 0, 2 * math.pi)
            ctx.restore()
            ctx.set_source_rgb(*self.hair)
            ctx.fill_preserve()
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(3)
            ctx.stroke()
        ctx.arc(0, 0, r, 0, 2 * math.pi)
        ctx.set_source_rgb(*self.skin)
        ctx.fill_preserve()
        ctx.save()
        ctx.clip()
        # cel shade on the back of the head
        ctx.arc(-r * 0.55 * bx, r * 0.25 + r * 0.25 * (1 - fp), r * 0.85, 0, 2 * math.pi)
        ctx.set_source_rgba(*shade(self.skin, 0.75), 0.35 - 0.15 * (1 - fp))
        ctx.fill()
        ctx.set_source_rgb(*self.hair)
        if hs == "cap":
            ctx.rectangle(-r, -r, 2 * r, r * 0.75)
        else:
            ctx.arc(-r * 0.25 * bx, -r * 1.05, r * 0.95, 0, 2 * math.pi)
        ctx.fill()
        ctx.restore()
        ctx.arc(0, 0, r, 0, 2 * math.pi)
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(3.5)
        ctx.stroke()
        if hs == "cap":
            ctx.new_path()
            ctx.move_to(sg * lerp(-r * 0.75, r * 0.2, fp), -r * 0.27)
            ctx.line_to(sg * lerp(r * 0.75, r * 1.35, fp), -r * 0.2 - r * 0.06 * (1 - fp))
            ctx.set_line_width(8)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.set_source_rgb(*INK)
            ctx.stroke_preserve()
            ctx.set_line_width(4)
            ctx.set_source_rgb(*self.hair)
            ctx.stroke()
        elif hs == "tuft":
            lag = self.sp_hair.x * 10
            for a in (-0.5, -0.15, 0.2):
                ctx.new_path()
                x0, y0 = r * math.sin(a), -r * math.cos(a)
                ctx.move_to(x0, y0)
                ctx.curve_to(x0 + 4 + lag * 0.5, y0 - 12, x0 + 14 + lag, y0 - 14, x0 + 16 + lag, y0 - 6)
                ctx.set_line_width(4)
                ctx.set_source_rgb(*INK)
                ctx.stroke()
        ears = [(-r * sg, 1.0)]
        if fp < 0.75:  # the far ear shows as the head turns to the camera
            ears.append((r * sg, min(1.0, (0.75 - fp) / 0.3)))
        for ex_, ea in ears:
            ctx.new_path()
            ctx.arc(ex_, 2, r * 0.18, 0, 2 * math.pi)
            ctx.set_source_rgba(*shade(self.skin, 0.92), ea)
            ctx.fill_preserve()
            ctx.set_source_rgba(*INK, ea)
            ctx.set_line_width(3)
            ctx.stroke()

        ctx.save()
        self._face_xform(ctx, r, 0.41)
        expr = self.expression(now)
        txt, prog, shape = self.talking(now)
        blink = ((self.clock + self.blink_off) % 3.6) < 0.13
        big = {"surprised": 1.25, "scared": 1.3, "excited": 1.15}.get(expr, 1.0) * getattr(self, "eye_scale", 1.0)
        lid = 0.42 if expr == "sleepy" else (0.7 if expr == "angry" else 1.0)
        pup = {"scared": 0.05, "excited": 0.11}.get(expr, 0.09)
        lx, ly = self.look
        lx *= self._yaw_view()[0]
        fv = self._fv = self._face_vals(now)
        for ex in (r * 0.2, r * 0.62):
            ey = -r * 0.08
            if expr == "dizzy":
                ctx.new_path()
                for i in range(30):
                    a = i * 0.45 + self.clock * 10
                    rr = 1 + i * 0.28
                    ctx.line_to(ex + rr * math.cos(a), ey + rr * math.sin(a))
                ctx.set_line_width(2.2)
                ctx.set_source_rgb(*INK)
                ctx.stroke()
                continue
            side = 1 if ex < r * 0.4 else -1
            if fv:
                self._fv_eye(ctx, ex, ey, r, big, 0.12 if blink else lid, pup, lx, ly, blink, fv, side)
            else:
                ctx.save()
                ctx.translate(ex, ey)
                ctx.scale(r * 0.17 * big, r * 0.22 * big * (0.12 if blink else lid))
                ctx.arc(0, 0, 1, 0, 2 * math.pi)
                ctx.restore()
                ctx.set_source_rgb(1, 1, 1)
                ctx.fill_preserve()
                ctx.set_source_rgb(*INK)
                ctx.set_line_width(2.5)
                ctx.stroke()
                if not blink:
                    px, py = ex + lx * r * 0.08, ey - ly * r * 0.1
                    ctx.arc(px, py, r * pup, 0, 2 * math.pi)
                    ctx.set_source_rgb(*INK)
                    ctx.fill()
                    ctx.arc(px + r * 0.03, py - r * 0.05, r * 0.03, 0, 2 * math.pi)
                    ctx.set_source_rgb(1, 1, 1)
                    ctx.fill()
            ctx.new_path()
            by = ey - r * 0.36 * big
            tilt = {"determined": 5, "sad": -5, "crying": -6, "surprised": -1, "angry": 10, "scared": -7,
                    "sleepy": -2}.get(expr, 0)
            if expr == "confused" and side < 0:
                by -= r * 0.14  # one raised brow
            if expr == "sleepy":
                by += r * 0.12
            if fv:
                by -= fv["brow_l" if side > 0 else "brow_r"] * r * 0.16 - fv["cheek"] * r * 0.03
                tilt += 11 * fv["brow_angle"]
            ctx.move_to(ex - r * 0.15, by - tilt * side * 0.5)
            ctx.line_to(ex + r * 0.15, by + tilt * side * 0.5)
            ctx.set_line_width(3.5)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.set_source_rgb(*INK)
            ctx.stroke()
        self._cheeks(ctx, r, expr)
        self._turned_mouth(ctx, self._mouth_now(shape, txt), expr, r)
        self._draw_face_wear(ctx, r, hat=False)
        self.draw_expression_extras(ctx, expr, r)
        ctx.restore()
        self._fv = None
        self._draw_face_hat(ctx, r)

    def _mouth_now(self, shape, txt):
        """Lip-sync shape while talking, else an action's forced shape (chewing), else closed."""
        if txt:
            return shape
        m = getattr(self, "_mouth_override", None)
        return m if m else "X"

    def _fv_eye(self, ctx, ex, ey, r, big, hk, pup, lx, ly, blink, fv, side):
        """One cartoon eye shaped by the face channels: lid closes from the top, cheek lifts the
        lower lid (smile squint), fully closed lids draw a sleeping arc."""
        lid = fv["lid_l" if side > 0 else "lid_r"]
        cheek = fv["cheek"]
        rx, ry = r * 0.17 * big, r * 0.22 * big
        k = hk * (1 - 0.9 * clamp(lid, 0.0, 1.0)) * (1 - 0.25 * min(0.0, lid))
        if k < 0.16 and not blink:  # closed: a soft downward arc
            cy = ey + ry * 0.35
            ctx.new_path()
            ctx.move_to(ex - rx, cy)
            ctx.curve_to(ex - rx * 0.4, cy + ry * 0.45, ex + rx * 0.4, cy + ry * 0.45, ex + rx, cy)
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(3.0)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.stroke()
            return
        ryk = ry * max(k, 0.08)
        cy = ey + (ry - ryk) * 0.6 * clamp(lid, 0.0, 1.0)
        cut = cy + ryk * (1 - 1.5 * cheek) if cheek > 0.01 else None
        ctx.save()
        if cut is not None:
            ctx.rectangle(ex - r, cy - 2 * r, 2 * r, cut - (cy - 2 * r))
            ctx.clip()
        ctx.new_path()
        ctx.save()
        ctx.translate(ex, cy)
        ctx.scale(rx, ryk)
        ctx.arc(0, 0, 1, 0, 2 * math.pi)
        ctx.restore()
        ctx.set_source_rgb(1, 1, 1)
        ctx.fill_preserve()
        ctx.save()
        ctx.clip_preserve()
        if not blink:
            px, py = ex + lx * r * 0.08, ey - ly * r * 0.1
            ctx.new_path()
            ctx.arc(px, py, r * pup, 0, 2 * math.pi)
            ctx.set_source_rgb(*INK)
            ctx.fill()
            ctx.arc(px + r * 0.03, py - r * 0.05, r * 0.03, 0, 2 * math.pi)
            ctx.set_source_rgb(1, 1, 1)
            ctx.fill()
        ctx.restore()
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(2.5)
        ctx.stroke()
        ctx.restore()
        if lid > 0.08:  # heavy upper lid line
            ctx.new_path()
            ctx.save()
            ctx.translate(ex, cy)
            ctx.scale(rx * 1.04, ryk * 1.02)
            ctx.arc(0, 0, 1, math.pi * 1.08, math.pi * 1.92)
            ctx.restore()
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(2.5 + 2.0 * min(1.0, lid))
            ctx.stroke()
        if cut is not None:  # lower lid pushed up by the cheek
            w = rx * 1.05
            ctx.new_path()
            ctx.move_to(ex - w, cut + ryk * 0.15)
            ctx.curve_to(ex - w * 0.4, cut - ryk * 0.35 * cheek, ex + w * 0.4, cut - ryk * 0.35 * cheek,
                         ex + w, cut + ryk * 0.15)
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(2.6)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.stroke()

    def draw_expression_extras(self, ctx, expr, r):
        """Cartoon symbols: sweat drop, tear, '?', sparkles, anger mark, 'z'."""
        t = self.clock
        if expr == "scared":
            y = -r * 0.55 + (t * 30 % 18)
            ctx.move_to(r * 0.95, y - 10)
            ctx.curve_to(r * 1.12, y + 4, r * 1.05, y + 12, r * 0.95, y + 12)
            ctx.curve_to(r * 0.85, y + 12, r * 0.78, y + 4, r * 0.95, y - 10)
            ctx.set_source_rgb(0.55, 0.8, 1)
            ctx.fill_preserve()
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(2)
            ctx.stroke()
        elif expr == "crying":
            for ex in (r * 0.2, r * 0.62):  # two streams of tears + drops
                ctx.move_to(ex, r * 0.08)
                ctx.curve_to(ex - r * 0.05, r * 0.4, ex + r * 0.05, r * 0.6, ex, r * 0.85)
                ctx.set_source_rgba(0.45, 0.75, 1, 0.85)
                ctx.set_line_width(r * 0.09)
                ctx.set_line_cap(cairo.LINE_CAP_ROUND)
                ctx.stroke()
                for i in range(2):
                    y = r * 0.3 + ((t * 40 + i * 17 + ex) % (r * 0.9))
                    ctx.arc(ex + r * 0.12 * (1 if i else -1), y, r * 0.05, 0, 2 * math.pi)
                    ctx.set_source_rgba(0.45, 0.75, 1, 0.9)
                    ctx.fill()
        elif expr == "sad":
            y = r * 0.12 + (t * 25 % 22)
            ctx.arc(r * 0.62, y, r * 0.06, 0, 2 * math.pi)
            ctx.set_source_rgba(0.45, 0.75, 1, 0.9)
            ctx.fill()
        elif expr == "angry":
            ctx.save()
            ctx.translate(r * 0.55, -r * 0.82)
            ctx.scale(1 + 0.1 * math.sin(t * 12), 1 + 0.1 * math.sin(t * 12))
            for a in (0.4, 2.0, 3.6, 5.2):
                ctx.move_to(4 * math.cos(a), 4 * math.sin(a))
                ctx.line_to(11 * math.cos(a + 0.5), 11 * math.sin(a + 0.5))
            ctx.set_source_rgb(0.9, 0.15, 0.2)
            ctx.set_line_width(3.2)
            ctx.set_line_cap(cairo.LINE_CAP_ROUND)
            ctx.stroke()
            ctx.restore()
        elif expr == "confused":
            ctx.select_font_face(FONT, cairo.FONT_SLANT_NORMAL, cairo.FONT_WEIGHT_BOLD)
            ctx.set_font_size(r * 0.9)
            ctx.move_to(r * 0.7, -r * 1.05 + 3 * math.sin(t * 4))
            ctx.text_path("?")
            ctx.set_source_rgb(1, 0.85, 0.3)
            ctx.fill_preserve()
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(2)
            ctx.stroke()
        elif expr == "excited":
            for i in range(3):
                a = t * 3 + i * 2.1
                x, y = r * 0.4 + r * 1.0 * math.cos(a), -r * 0.6 + r * 0.45 * math.sin(a)
                s = 5 + 2 * math.sin(t * 9 + i)
                ctx.move_to(x - s, y)
                ctx.line_to(x + s, y)
                ctx.move_to(x, y - s)
                ctx.line_to(x, y + s)
            ctx.set_source_rgb(1, 0.85, 0.2)
            ctx.set_line_width(2.5)
            ctx.stroke()
        elif expr == "sleepy":
            ctx.select_font_face(FONT, cairo.FONT_SLANT_NORMAL, cairo.FONT_WEIGHT_BOLD)
            for i in range(2):
                k = (t * 0.5 + i * 0.5) % 1
                ctx.set_font_size(r * (0.35 + 0.3 * k))
                ctx.move_to(r * (0.7 + 0.5 * k), -r * (0.8 + 0.9 * k))
                ctx.set_source_rgba(*INK, 1 - k)
                ctx.show_text("z")


# ---------------------------------------------------------------- props
class Ball:
    def __init__(self, x, r=17, color="#ffffff", accent="#e84a5f"):
        self.x, self.y, self.vx, self.vy, self.r = x, r, 0.0, 0.0, r
        self.rot, self.spin, self.squash = 0.0, 0.0, 0.0
        self.color, self.accent = hex2rgb(color), hex2rgb(accent)
        self.trail = []

    def update(self, dt, scene):
        if getattr(self, "carried", False):  # held by a character: no physics
            self.trail = (self.trail + [(self.x, self.y)])[-7:]
            return
        self.vy -= G * dt
        self.x += self.vx * dt
        self.y += self.vy * dt
        gr = _ground(scene, self.x)
        if gr or getattr(scene, "terrain", None) is not None:
            self._terrain_contact(scene, gr, dt)
        elif self.y < self.r:
            self.y = self.r
            if abs(self.vy) > 90:
                g = min(1, abs(self.vy) / 700)
                scene.event("bounce", self.x, gain=g)
                self.squash = 0.35 * g
                self.vy = -self.vy * 0.58
                self.vx *= 0.88
            else:
                self.vy = 0
            self.spin = -self.vx / self.r
        if self.y <= self.r + 0.5 + gr:
            self.vx *= max(0, 1 - 1.4 * dt)
        for b in scene.boxes:
            if b.x - b.w / 2 - self.r < self.x < b.x + b.w / 2 + self.r and self.y < b.h + self.r:
                if self.y > b.h:
                    self.y, self.vy = b.h + self.r, abs(self.vy) * 0.5
                else:
                    self.vx = -self.vx * 0.6
                    self.x = b.x + (b.w / 2 + self.r + 1) * (1 if self.x > b.x else -1)
                    scene.event("bounce", self.x, gain=0.6)
        self.rot += self.spin * dt
        self.squash *= max(0, 1 - dt * 12)
        self.trail = (self.trail + [(self.x, self.y)])[-7:]
        if gr:
            self._gy = gr
        elif getattr(self, "_gy", 0.0):
            self._gy = 0.0

    def _terrain_contact(self, scene, gr, dt):
        """Bounce / roll on a sloped terrain (#61): reflect along the surface normal."""
        if self.y >= self.r + gr:
            return
        m = scene.slope_at(self.x) if hasattr(scene, "slope_at") else 0.0
        L = math.hypot(m, 1.0)
        nx, ny = -m / L, 1.0 / L
        self.y = gr + self.r / ny if ny > 0.2 else gr + self.r
        vn = self.vx * nx + self.vy * ny
        if vn < -90:
            g = min(1, -vn / 700)
            scene.event("bounce", self.x, gain=g)
            self.squash = 0.35 * g
            self.vx -= (1 + 0.58) * vn * nx
            self.vy -= (1 + 0.58) * vn * ny
            self.vx *= 0.9
        elif vn < 0:
            self.vx -= vn * nx
            self.vy -= vn * ny
        self.spin = -self.vx / self.r

    def draw(self, ctx, now):
        gy = getattr(self, "_gy", 0.0)
        sh = clamp(1 - (self.y - gy) / 400, 0.25, 1)
        ctx.save()
        ctx.translate(self.x, -gy)
        ctx.scale(self.r * sh, 4 * sh)
        ctx.arc(0, 0, 1, 0, 2 * math.pi)
        ctx.set_source_rgba(0, 0, 0, 0.18)
        ctx.fill()
        ctx.restore()
        speed = math.hypot(self.vx, self.vy)
        if speed > 350:  # motion trail
            for i, (tx, ty) in enumerate(self.trail[:-1]):
                a = (i + 1) / len(self.trail) * 0.35
                ctx.arc(tx, -ty, self.r * (0.5 + 0.5 * i / len(self.trail)), 0, 2 * math.pi)
                ctx.set_source_rgba(1, 1, 1, a)
                ctx.fill()
        ctx.save()
        ctx.translate(self.x, -self.y)
        if self.squash > 0.01 and self.y < self.r + 6:  # squash on impact (contact at bottom)
            ctx.translate(0, self.r)
            ctx.scale(1 + self.squash, 1 / (1 + self.squash))
            ctx.translate(0, -self.r)
        elif speed > 400:  # stretch along velocity
            ang = math.atan2(-self.vy, self.vx)
            st = clamp((speed - 400) / 2500, 0, 0.25)
            ctx.rotate(ang)
            ctx.scale(1 + st, 1 / (1 + st))
            ctx.rotate(-ang)
        ctx.rotate(self.rot)
        ctx.arc(0, 0, self.r, 0, 2 * math.pi)
        ctx.set_source_rgb(*self.color)
        ctx.fill_preserve()
        ctx.save()
        ctx.clip()
        ctx.set_source_rgb(*self.accent)
        for a in (0, 2.1, 4.2):
            ctx.arc(self.r * 0.7 * math.cos(a), self.r * 0.7 * math.sin(a), self.r * 0.38, 0, 2 * math.pi)
            ctx.fill()
        ctx.restore()
        ctx.arc(0, 0, self.r, 0, 2 * math.pi)
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(3)
        ctx.stroke()
        ctx.restore()


class Box:
    def __init__(self, x, w=60, h=55, color="#c98b4f"):
        self.x, self.w, self.h, self.color = x, w, h, hex2rgb(color)
        self.y = 0

    def draw(self, ctx, now):
        ctx.save()
        ctx.translate(0, -getattr(self, "y", 0.0))
        self._draw_box(ctx)
        ctx.restore()

    def _draw_box(self, ctx):
        x0 = self.x - self.w / 2
        ctx.rectangle(x0, -self.h, self.w, self.h)
        ctx.set_source_rgb(*self.color)
        ctx.fill_preserve()
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(3.5)
        ctx.stroke()
        ctx.move_to(x0 + 6, -self.h + 6)
        ctx.line_to(x0 + self.w - 6, -6)
        ctx.move_to(x0 + self.w - 6, -self.h + 6)
        ctx.line_to(x0 + 6, -6)
        ctx.set_source_rgb(*shade(self.color, 0.7))
        ctx.set_line_width(3)
        ctx.stroke()


# ---------------------------------------------------------------- rigid props (#41) & ropes (#39)
class Prop:
    """Small rigid prop that can be thrown, tumble, bounce, roll and stack.
    kind: apple, orange, ball (round) or can, crate (rectangles). (x, y) is the centre
    (world, y up); y=None rests it on the ground. Stacks on the ground, on Box tops and on
    other props. Picklable. Sounds: "bounce"/"thud" via scene.event with x."""

    KINDS = {
        "apple": dict(shape="round", r=13, color="#e63946", rest=0.35, fric=2.5),
        "orange": dict(shape="round", r=14, color="#f4a261", rest=0.4, fric=2.5),
        "ball": dict(shape="round", r=15, color="#ffffff", rest=0.6, fric=1.2),
        "can": dict(shape="rect", hw=12, hh=17, color="#c0392b", rest=0.25, fric=7.0),
        "crate": dict(shape="rect", hw=22, hh=22, color="#c98b4f", rest=0.15, fric=9.0),
    }

    def __init__(self, kind="apple", x=0.0, y=None, color=None, r=None, hw=None, hh=None):
        if kind not in self.KINDS:
            raise ValueError(f"Prop kind must be one of {sorted(self.KINDS)}")
        k = self.KINDS[kind]
        self.kind, self.shape = kind, k["shape"]
        self.r = r or k.get("r")
        self.hw = hw or k.get("hw", self.r)
        self.hh = hh or k.get("hh", self.r)
        if self.shape == "round":
            self.hw = self.hh = self.r
        else:
            self.r = None
        self.color = hex2rgb(color or k["color"])
        self.restitution, self.friction = k["rest"], k["fric"]
        self.x = float(x)
        self.y = float(self.hh if y is None else y)
        self.vx = self.vy = 0.0
        self.rot = self.omega = 0.0
        self.carried, self.resting = False, y is None
        self._release = None

    # half extents of the (rotated) shape
    def half_h(self):
        if self.shape == "round":
            return self.r
        c, s_ = abs(math.cos(self.rot)), abs(math.sin(self.rot))
        return self.hh * c + self.hw * s_

    def half_w(self):
        if self.shape == "round":
            return self.r
        c, s_ = abs(math.cos(self.rot)), abs(math.sin(self.rot))
        return self.hw * c + self.hh * s_

    def top(self):
        return self.y + self.half_h()

    def _support(self, scene, bottom_prev):
        """Highest surface under the prop that it was above last step."""
        sup, what = _ground(scene, self.x), None
        hw = self.half_w()
        for b in getattr(scene, "boxes", ()):
            if getattr(b, "carried", False):
                continue
            t = getattr(b, "y", 0.0) + b.h
            if abs(self.x - b.x) < b.w / 2 + hw * 0.5 and bottom_prev >= t - 6 and t > sup:
                sup, what = t, b
        for p in getattr(scene, "props", ()):
            if p is self or p.carried or p.y >= self.y:
                continue
            t = p.top()
            if abs(self.x - p.x) < p.half_w() + hw * 0.55 and bottom_prev >= t - 6 and t > sup:
                sup, what = t, p
        return sup, what

    def update(self, dt, scene):
        if self.carried or getattr(self, "hidden", False):
            self.resting = False
            return
        bottom_prev = self.y - self.half_h()
        self.vy -= G * dt
        self.x += self.vx * dt
        self.y += self.vy * dt
        self.rot += self.omega * dt
        sup, what = self._support(scene, bottom_prev)
        hh = self.half_h()
        if self.y - hh <= sup:
            self.y = sup + hh
            if self.vy < -110:
                g = min(1.0, -self.vy / 900)
                kind = "thud" if self.shape == "rect" else "bounce"
                scene.event(kind, self.x, gain=0.25 + 0.6 * g)
                self.vy = -self.vy * self.restitution
                self.vx *= 0.8
                if self.shape == "rect":
                    self.omega = self.omega * 0.4 + self.vx * 0.01
                self.resting = False
            else:
                self.vy = 0.0
                self.vx *= max(0.0, 1 - self.friction * dt)
                if abs(self.vx) < 4:
                    self.vx = 0.0
                if self.shape == "round":
                    if what is None and getattr(scene, "terrain", None) is not None:  # roll downhill
                        self.vx -= G * 0.55 * scene.slope_at(self.x) * dt
                    self.omega = -self.vx / self.r
                else:  # settle on the nearest flat side
                    tgt = round(self.rot / (math.pi / 2)) * (math.pi / 2)
                    self.rot += (tgt - self.rot) * min(1.0, 12 * dt)
                    self.omega *= max(0.0, 1 - 10 * dt)
                    if abs(self.rot - tgt) < 1e-3:
                        self.rot, self.omega = tgt, 0.0
                if isinstance(what, Prop) and what.vx:
                    self.x += what.vx * dt  # ride along on a moving prop
                self.resting = self.vx == 0.0 and self.omega == 0.0
        # side collisions with boxes (walls)
        for b in getattr(scene, "boxes", ()):
            if getattr(b, "carried", False):
                continue
            by0, by1 = getattr(b, "y", 0.0), getattr(b, "y", 0.0) + b.h
            hw = self.half_w()
            if self.y - hh < by1 - 3 and self.y + hh > by0 and abs(self.x - b.x) < b.w / 2 + hw:
                side = 1 if self.x > b.x else -1
                self.x = b.x + side * (b.w / 2 + hw + 0.5)
                if self.vx * side < 0:
                    if abs(self.vx) > 80:
                        scene.event("bounce", self.x, gain=0.4)
                    self.vx = -self.vx * 0.4
                    self.omega *= -0.5

    def draw(self, ctx, now):
        if getattr(self, "hidden", False):
            return
        gy = getattr(self, "_gy", 0.0)
        sh = clamp(1 - (self.y - gy) / 350, 0.25, 1)
        ctx.save()
        ctx.translate(self.x, -gy)
        ctx.scale(self.hw * 1.1 * sh, 3.5 * sh)
        ctx.arc(0, 0, 1, 0, 2 * math.pi)
        ctx.set_source_rgba(0, 0, 0, 0.16)
        ctx.fill()
        ctx.restore()
        ctx.save()
        ctx.translate(self.x, -self.y)
        ctx.rotate(-self.rot)
        bites = getattr(self, "bites", 0)
        if bites:
            self._draw_bitten(ctx, bites)
        else:
            getattr(self, "_draw_" + self.kind)(ctx)
        ctx.restore()

    def _bite_circles(self, bites):
        side = getattr(self, "bite_side", 1)
        R = max(self.hw, self.hh)
        return [(side * R * 0.98, -R * 0.35 + i * R * 0.42, R * 0.36) for i in range(int(bites))]

    def _draw_bitten(self, ctx, bites):
        """Draw the prop with bite marks (Eat): notched outline and the pale inside showing."""
        R = max(self.hw, self.hh) * 1.6
        circles = self._bite_circles(bites)
        ctx.save()
        ctx.new_path()
        ctx.rectangle(-R * 2, -R * 2, R * 4, R * 4)
        for x, y, br in circles:
            ctx.new_sub_path()
            ctx.arc(x, y, br, 0, 2 * math.pi)
        ctx.set_fill_rule(cairo.FILL_RULE_EVEN_ODD)
        ctx.clip()
        ctx.set_fill_rule(cairo.FILL_RULE_WINDING)
        getattr(self, "_draw_" + self.kind)(ctx)
        ctx.restore()
        ctx.save()
        ctx.new_path()
        ctx.arc(0, 0, max(self.hw, self.hh) * 0.97, 0, 2 * math.pi)
        ctx.clip()
        for x, y, br in circles:
            ctx.new_path()
            ctx.arc(x, y, br + 3.5, 0, 2 * math.pi)
            ctx.new_sub_path()
            ctx.arc(x, y, br, 0, 2 * math.pi)
            ctx.set_fill_rule(cairo.FILL_RULE_EVEN_ODD)
            ctx.set_source_rgb(1.0, 0.95, 0.8)
            ctx.fill()
            ctx.set_fill_rule(cairo.FILL_RULE_WINDING)
            ctx.arc(x, y, br, 0, 2 * math.pi)
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(2.0)
            ctx.stroke()
        ctx.restore()

    @staticmethod
    def _ink(ctx, col, lw=2.6):
        ctx.set_source_rgb(*col)
        ctx.fill_preserve()
        ctx.set_source_rgb(*INK)
        ctx.set_line_width(lw)
        ctx.stroke()

    def _draw_apple(self, ctx):
        r = self.r
        ctx.move_to(0, -r * 0.7)
        ctx.curve_to(r * 0.6, -r * 1.15, r * 1.15, -r * 0.6, r * 1.0, r * 0.15)
        ctx.curve_to(r * 0.9, r * 0.85, r * 0.4, r * 1.05, 0, r * 0.88)
        ctx.curve_to(-r * 0.4, r * 1.05, -r * 0.9, r * 0.85, -r * 1.0, r * 0.15)
        ctx.curve_to(-r * 1.15, -r * 0.6, -r * 0.6, -r * 1.15, 0, -r * 0.7)
        ctx.close_path()
        self._ink(ctx, self.color)
        ctx.arc(-r * 0.42, -r * 0.3, r * 0.2, 0, 2 * math.pi)
        ctx.set_source_rgba(1, 1, 1, 0.55)
        ctx.fill()
        ctx.move_to(0, -r * 0.7)
        ctx.line_to(r * 0.12, -r * 1.25)
        ctx.set_source_rgb(0.4, 0.25, 0.12)
        ctx.set_line_width(2.6)
        ctx.stroke()
        ctx.move_to(r * 0.12, -r * 1.1)
        ctx.curve_to(r * 0.5, -r * 1.5, r * 0.9, -r * 1.2, r * 0.75, -r * 1.0)
        ctx.curve_to(r * 0.5, -r * 0.95, r * 0.3, -r * 1.0, r * 0.12, -r * 1.1)
        self._ink(ctx, (0.35, 0.7, 0.3), 1.8)

    def _draw_orange(self, ctx):
        r = self.r
        ctx.arc(0, 0, r, 0, 2 * math.pi)
        self._ink(ctx, self.color)
        for a in range(6):
            ctx.arc(r * 0.55 * math.cos(a * 1.1), r * 0.55 * math.sin(a * 1.1), 0.9, 0, 2 * math.pi)
            ctx.set_source_rgba(*shade(self.color, 0.75), 1)
            ctx.fill()
        ctx.arc(0, -r * 0.95, r * 0.15, 0, 2 * math.pi)
        self._ink(ctx, (0.35, 0.6, 0.25), 1.5)

    def _draw_ball(self, ctx):
        r = self.r
        ctx.arc(0, 0, r, 0, 2 * math.pi)
        self._ink(ctx, self.color, 3)
        ctx.save()
        ctx.arc(0, 0, r, 0, 2 * math.pi)
        ctx.clip()
        ctx.set_source_rgb(0.9, 0.29, 0.37)
        for a in (0, 2.1, 4.2):
            ctx.arc(r * 0.7 * math.cos(a), r * 0.7 * math.sin(a), r * 0.38, 0, 2 * math.pi)
            ctx.fill()
        ctx.restore()

    def _draw_can(self, ctx):
        w, h = self.hw, self.hh
        ctx.rectangle(-w, -h, 2 * w, 2 * h)
        self._ink(ctx, (0.78, 0.8, 0.84))
        ctx.rectangle(-w, -h * 0.55, 2 * w, h * 1.1)
        self._ink(ctx, self.color, 2)
        ctx.arc(-w * 0.3, 0, w * 0.32, 0, 2 * math.pi)
        ctx.set_source_rgba(1, 1, 1, 0.8)
        ctx.fill()
        ctx.rectangle(-w * 0.75, -h * 0.95, w * 0.22, h * 1.9)
        ctx.set_source_rgba(1, 1, 1, 0.35)
        ctx.fill()

    def _draw_crate(self, ctx):
        w, h = self.hw, self.hh
        ctx.rectangle(-w, -h, 2 * w, 2 * h)
        self._ink(ctx, self.color, 3)
        ctx.rectangle(-w + 4, -h + 4, 2 * w - 8, 2 * h - 8)
        ctx.move_to(-w + 5, -h + 5)
        ctx.line_to(w - 5, h - 5)
        ctx.set_source_rgb(*shade(self.color, 0.7))
        ctx.set_line_width(2.5)
        ctx.stroke()


class Rope:
    """Hanging rope prop: a Verlet Chain pinned at `anchor` (a world point, or any object
    with x/y such as a Character's hand via `hand_of`), optionally also pinned at `end`.
    Sways with wind (scene.wind + self.wind)."""

    def __init__(self, anchor=(0.0, 300.0), length=160.0, n=14, end=None, color="#9c6b3c",
                 width=7.0, hand_of=None, wind=0.0):
        self.anchor, self.end, self.hand_of = anchor, end, hand_of
        self.chain = Chain(n, length / (n - 1), gravity=-1400.0, damping=0.04, iters=10)
        self.color, self.width, self.wind = hex2rgb(color), width, wind

    def _anchor(self):
        if self.hand_of is not None:
            return self.hand_of.hand_world(True)
        a = self.anchor
        return (a.x, a.y) if hasattr(a, "x") else tuple(a)

    def update(self, dt, scene):
        ch = self.chain
        ch.update(self._anchor(), dt, self.wind + getattr(scene, "wind", 0.0))
        if self.end is not None:
            e = (self.end.x, self.end.y) if hasattr(self.end, "x") else tuple(self.end)
            pts = ch.pts
            for _ in range(6):
                pts[-1] = e
                for i in range(len(pts) - 1, 0, -1):
                    (x0, y0), (x1, y1) = pts[i - 1], pts[i]
                    dx, dy = x0 - x1, y0 - y1
                    d = math.hypot(dx, dy) or 1e-6
                    diff = (d - ch.seg) / d
                    if i - 1 == 0:
                        continue
                    pts[i - 1] = (x0 - dx * diff * 0.5, y0 - dy * diff * 0.5)
                pts[0] = self._anchor()
            pts[-1] = e

    def draw(self, ctx, now):
        pts = self.chain.pts
        if not pts:
            return
        ctx.save()
        ctx.set_line_cap(cairo.LINE_CAP_ROUND)
        ctx.set_line_join(cairo.LINE_JOIN_ROUND)
        for w, col in ((self.width + 3.5, INK), (self.width, self.color)):
            ctx.move_to(pts[0][0], -pts[0][1])
            for x, y in pts[1:]:
                ctx.line_to(x, -y)
            ctx.set_line_width(w)
            ctx.set_source_rgb(*col)
            ctx.stroke()
        ctx.restore()


# ---------------------------------------------------------------- particles

# ---------------------------------------------------------------- water (#42)
class Puddle:
    """A water puddle on the ground. Characters stepping / landing in it, balls bouncing and
    props dropping into it make ripples, flying droplets and a 'splash' sound.
    x: centre, w: width (px), color: water colour, rain=True: random rain ripples
    (also automatic while a Rain overlay is in the scene), rain_rate: ripples per second."""
    TRIGGERS = {"step": 0.45, "runstep": 0.75, "land": 1.0, "thud": 1.0, "bounce": 0.7, "hop": 0.4,
                "slip": 0.9, "kick": 0.5}

    def __init__(self, x=0.0, w=170.0, color="#5aa9e6", rain=False, rain_rate=5.0, seed=5):
        self.x, self.w = float(x), float(w)
        self.h = max(8.0, self.w * 0.085)
        self.color = hex2rgb(color)
        self.rain, self.rain_rate = bool(rain), float(rain_rate)
        self.ripples = []  # (t0, x, strength)
        self.rng = random.Random(seed)
        self.splashes = 0
        self._now = 0.0

    def contains(self, x: float) -> bool:
        return abs(x - self.x) <= self.w / 2

    def hit(self, x, kind, scene, gain=1.0):
        s = clamp(self.TRIGGERS.get(kind, 0.6) * (0.6 + 0.4 * min(1.0, gain)), 0.15, 1.0)
        self.ripples.append((scene.time, x, s))
        scene.particles.splash(x, 3 + getattr(self, "_gy", 0.0), int(6 + 18 * s), s, self.color)
        self.splashes += 1
        scene.event("splash", x, gain=0.35 + 0.65 * s)

    def update(self, dt, scene):
        self._now = scene.time
        self._gy = _ground(scene, self.x)
        raining = self.rain or any(isinstance(w, Rain) and w.level(scene.time) > 0
                                   for w in getattr(scene, "world_fx", ()))
        if raining:
            n = self.rain_rate * self.w / 170.0 * dt
            while n > 0:
                if self.rng.random() < min(1.0, n):
                    rx = self.x + self.rng.uniform(-0.45, 0.45) * self.w
                    self.ripples.append((scene.time, rx, self.rng.uniform(0.12, 0.25)))
                n -= 1.0
        self.ripples = [r for r in self.ripples if scene.time - r[0] < 1.4]

    def _shape(self, ctx, inset=0.0):
        ctx.save()
        ctx.translate(self.x, -1.0)
        ctx.scale(max(1.0, self.w / 2 - inset), max(1.0, self.h / 2 - inset * 0.3))
        ctx.new_path()
        # slightly irregular outline: a puddle, not a perfect ellipse
        for i in range(25):
            a = i / 24 * 2 * math.pi
            k = 1 + 0.05 * math.sin(3 * a + self.x * 0.01) + 0.03 * math.sin(5 * a)
            ctx.line_to(k * math.cos(a), k * math.sin(a))
        ctx.close_path()
        ctx.restore()

    def draw(self, ctx, now):
        gy = getattr(self, "_gy", 0.0)
        if gy:
            ctx.save()
            ctx.translate(0, -gy)
            self._draw(ctx, now)
            ctx.restore()
        else:
            self._draw(ctx, now)

    def _draw(self, ctx, now):
        c = self.color
        self._shape(ctx)
        g = cairo.LinearGradient(0, -self.h, 0, self.h)
        g.add_color_stop_rgb(0, *tuple(min(1, v * 1.25 + 0.12) for v in c))
        g.add_color_stop_rgb(1, *shade(c, 0.72))
        ctx.set_source(g)
        ctx.fill_preserve()
        ctx.set_source_rgba(*INK, 0.55)
        ctx.set_line_width(2.2)
        ctx.stroke()
        ctx.save()
        self._shape(ctx, 2)
        ctx.clip()
        # sky glint
        ctx.save()
        ctx.translate(self.x - self.w * 0.14, -self.h * 0.12)
        ctx.scale(self.w * 0.2, self.h * 0.12)
        ctx.arc(0, 0, 1, 0, 2 * math.pi)
        ctx.restore()
        ctx.set_source_rgba(1, 1, 1, 0.45)
        ctx.fill()
        for t0, rx, st in self.ripples:
            age = now - t0
            if age < 0:
                continue
            for ring in range(2 if st > 0.3 else 1):
                a = age - ring * 0.18
                if a <= 0:
                    continue
                rad = 4 + a * (60 + 120 * st)
                alpha = max(0.0, 1 - a / (0.6 + 0.7 * st)) * (0.9 if ring == 0 else 0.55)
                if alpha <= 0:
                    continue
                ctx.save()
                ctx.translate(rx, -1.0)
                ctx.scale(rad, rad * self.h / self.w * 1.6)
                ctx.arc(0, 0, 1, 0, 2 * math.pi)
                ctx.restore()
                ctx.set_source_rgba(1, 1, 1, alpha)
                ctx.set_line_width(2.0)
                ctx.stroke()
        ctx.restore()


class Rain:
    """Rain overlay (#42): slanted streaks over the visible part of the world (drawn in front,
    world space). Scene.add(Rain()) also turns on rain ripples in every Puddle.
    intensity: 0..2 (streak count), angle: slant (rad, + = falling to the right).
    start / fade: the rain begins at `start` seconds and fades in over `fade` seconds (add it to
    the scene before render - the overlay list is captured once - and use start to begin later)."""

    def __init__(self, intensity=1.0, color="#e4efff", angle=0.18, speed=900.0, seed=11,
                 start=0.0, fade=1.0):
        self.intensity, self.color = float(intensity), hex2rgb(color)
        self.angle, self.speed, self.seed = float(angle), float(speed), seed
        self.start, self.fade = float(start), max(0.0, float(fade))

    def level(self, now):
        """0..1 rain amount at time `now` (0 before start, ramps up over `fade`)."""
        if now < self.start:
            return 0.0
        return 1.0 if self.fade <= 0 else clamp((now - self.start) / self.fade, 0.0, 1.0)

    def draw_world(self, ctx, now):
        lv = self.level(now)
        if lv <= 0:
            return
        x0, y0, x1, y1 = ctx.clip_extents()
        w, h = x1 - x0, y1 - y0
        if w <= 0 or h <= 0:
            return
        n = int(160 * self.intensity * lv)
        ln = 22.0
        dx, dy = math.sin(self.angle), math.cos(self.angle)
        ctx.set_line_width(2.0)
        ctx.set_line_cap(cairo.LINE_CAP_ROUND)
        ctx.set_source_rgba(*self.color, 0.75)
        for i in range(n):
            u = (i * 0.6180339 + self.seed * 0.137) % 1.0
            v = (i * 0.3819660 + now * self.speed / h * (0.8 + 0.4 * ((i * 0.7548) % 1.0))) % 1.0
            px = x0 + u * (w + h * dx) - h * dx * 0.5
            py = y0 + v * h
            px += (py - y0) * dx / max(dy, 0.1) * 0.15
            ctx.move_to(px, py)
            ctx.line_to(px + dx * ln, py + dy * ln)
        ctx.stroke()


class Particles:
    def __init__(self, seed=3):
        self.p = []
        self.rng = random.Random(seed)

    def __getstate__(self):
        return {"p": copy.deepcopy(self.p), "rng": None}

    def dust(self, x, y, n, dirx):
        for _ in range(n):
            self.p.append(dict(k="dust", x=x + self.rng.uniform(-14, 14), y=y + 4,
                               vx=-dirx * self.rng.uniform(20, 90) + self.rng.uniform(-60, 60),
                               vy=self.rng.uniform(20, 80), life=0.0, max=self.rng.uniform(0.35, 0.6),
                               r=self.rng.uniform(5, 10)))

    def sparkle(self, x, y, n):
        for _ in range(n):
            a = self.rng.uniform(0, 2 * math.pi)
            sp = self.rng.uniform(120, 260)
            self.p.append(dict(k="spark", x=x, y=y, vx=sp * math.cos(a), vy=sp * math.sin(a),
                               life=0.0, max=0.35, r=5))

    def confetti(self, x, y, n):
        cols = ["#ff5d73", "#ffd166", "#06d6a0", "#4cc9f0", "#b388ff"]
        for _ in range(n):
            self.p.append(dict(k="conf", x=x + self.rng.uniform(-300, 300), y=y + self.rng.uniform(0, 80),
                               vx=self.rng.uniform(-60, 60), vy=self.rng.uniform(-40, 120),
                               life=0.0, max=self.rng.uniform(2.0, 3.2), r=self.rng.uniform(5, 9),
                               rot=self.rng.uniform(0, 6), vr=self.rng.uniform(-9, 9),
                               col=hex2rgb(self.rng.choice(cols))))

    def splash(self, x, y, n, power=1.0, color=(0.36, 0.66, 0.9)):
        """Water droplets thrown up and out; they fall back with gravity (#42)."""
        for _ in range(n):
            a = self.rng.uniform(0.35, math.pi - 0.35)
            sp = self.rng.uniform(140, 340) * (0.55 + 0.6 * power)
            self.p.append(dict(k="drop", x=x + self.rng.uniform(-12, 12), y=y, vx=sp * math.cos(a) * 0.8,
                               vy=sp * math.sin(a), life=0.0, max=1.4, r=self.rng.uniform(2.5, 5.0),
                               col=tuple(color)))

    def zzz(self, x, y, size=None):
        """A sleepy 'Z' that drifts up, sways and fades (SleepInBed)."""
        self.p.append(dict(k="zzz", x=x, y=y, vx=14.0, vy=34.0, life=0.0, max=2.2,
                           r=size or self.rng.uniform(15, 21)))

    def update(self, dt):
        floor = getattr(self, "floor", None)
        for q in self.p:
            q["life"] += dt
            q["x"] += q["vx"] * dt
            q["y"] += q["vy"] * dt
            if q["k"] == "zzz":
                q["vx"] = 14.0 + 22.0 * math.sin(q["life"] * 3.0)
                continue
            if q["k"] == "dust":
                q["vx"] *= 1 - 3 * dt
                q["vy"] *= 1 - 3 * dt
            elif q["k"] == "conf":
                q["vy"] = max(q["vy"] - 300 * dt, -140)
                q["vx"] += 40 * math.sin(q["life"] * 4 + q["rot"]) * dt
                q["rot"] += q["vr"] * dt
            elif q["k"] == "drop":
                q["vy"] -= 1500 * dt
                if q["y"] < (floor.at(q["x"]) if floor is not None else 0):
                    q["life"] = q["max"]
        self.p = [q for q in self.p if q["life"] < q["max"]]

    def draw(self, ctx):
        for q in self.p:
            f = q["life"] / q["max"]
            if q["k"] == "dust":
                ctx.arc(q["x"], -q["y"], q["r"] * (1 + f * 1.5), 0, 2 * math.pi)
                ctx.set_source_rgba(0.86, 0.8, 0.68, 0.7 * (1 - f))
                ctx.fill()
            elif q["k"] == "drop":
                sp = math.hypot(q["vx"], q["vy"]) or 1.0
                ctx.save()
                ctx.translate(q["x"], -q["y"])
                ctx.rotate(math.atan2(-q["vy"], q["vx"]))
                ctx.scale(q["r"] * (1 + min(1.2, sp / 400)), q["r"])
                ctx.arc(0, 0, 1, 0, 2 * math.pi)
                ctx.restore()
                ctx.set_source_rgba(*q["col"], 0.9)
                ctx.fill_preserve()
                ctx.set_source_rgba(1, 1, 1, 0.5)
                ctx.set_line_width(1.0)
                ctx.stroke()
            elif q["k"] == "zzz":
                ctx.save()
                ctx.select_font_face(FONT, cairo.FONT_SLANT_NORMAL, cairo.FONT_WEIGHT_BOLD)
                ctx.set_font_size(q["r"] * (0.7 + 0.8 * f))
                ctx.move_to(q["x"], -q["y"])
                ctx.text_path("Z")
                a = min(1.0, f * 6) * (1 - f)
                ctx.set_source_rgba(*INK, a)
                ctx.set_line_width(4)
                ctx.set_line_join(cairo.LINE_JOIN_ROUND)
                ctx.stroke_preserve()
                ctx.set_source_rgba(1, 1, 1, a)
                ctx.fill()
                ctx.restore()
            elif q["k"] == "spark":
                ctx.save()
                ctx.translate(q["x"], -q["y"])
                ctx.rotate(f * 3)
                s = q["r"] * (1 - f)
                for i in range(4):
                    ctx.move_to(0, 0)
                    ctx.line_to(s * 2.2 * math.cos(i * math.pi / 2), s * 2.2 * math.sin(i * math.pi / 2))
                ctx.set_source_rgba(1, 0.85, 0.3, 1 - f)
                ctx.set_line_width(3)
                ctx.stroke()
                ctx.restore()
            else:
                ctx.save()
                ctx.translate(q["x"], -q["y"])
                ctx.rotate(q["rot"])
                ctx.scale(1, abs(math.cos(q["rot"] * 1.3)) + 0.15)
                ctx.rectangle(-q["r"], -q["r"] * 0.5, q["r"] * 2, q["r"])
                ctx.set_source_rgba(*q["col"], min(1, 3 * (1 - f)))
                ctx.fill()
                ctx.restore()


# ---------------------------------------------------------------- terrain (#61)
def _monotone_spline(px, py, xs):
    """Monotone cubic (Fritsch-Carlson) through points: smooth hills without overshoot."""
    px, py = np.asarray(px, float), np.asarray(py, float)
    if len(px) == 1:
        return np.full_like(xs, py[0])
    h = np.diff(px)
    dlt = np.diff(py) / h
    m = np.zeros(len(px))
    m[0], m[-1] = dlt[0], dlt[-1]
    for i in range(1, len(px) - 1):
        if dlt[i - 1] * dlt[i] > 0:
            w1, w2 = 2 * h[i] + h[i - 1], h[i] + 2 * h[i - 1]
            m[i] = (w1 + w2) / (w1 / dlt[i - 1] + w2 / dlt[i])
    xc = np.clip(xs, px[0], px[-1])
    i = np.clip(np.searchsorted(px, xc) - 1, 0, len(px) - 2)
    t = (xc - px[i]) / h[i]
    t2, t3 = t * t, t * t * t
    return ((2 * t3 - 3 * t2 + 1) * py[i] + (t3 - 2 * t2 + t) * h[i] * m[i]
            + (-2 * t3 + 3 * t2) * py[i + 1] + (t3 - t2) * h[i] * m[i + 1])


class Terrain:
    """Ground height h(x) in px (positive = up), sampled into a table so it pickles into render
    workers. Build from a function, from (x, h) points (monotone spline) or with terrain_hills()."""

    def __init__(self, fn=None, points=None, x0=-8000.0, x1=8000.0, step=4.0):
        xs = np.arange(float(x0), float(x1) + step * 0.5, float(step))
        if points is not None:
            pts = sorted((float(a), float(b)) for a, b in points)
            hs = _monotone_spline([p[0] for p in pts], [p[1] for p in pts], xs)
        elif fn is not None:
            hs = np.array([float(fn(x)) for x in xs])
        else:
            hs = np.zeros_like(xs)
        self.x0, self.step = float(x0), float(step)
        self.h = [float(v) for v in hs]
        self.n = len(self.h)

    def at(self, x: float) -> float:
        """Height at x (linear between samples, held flat past the ends)."""
        u = (x - self.x0) / self.step
        if u <= 0:
            return self.h[0]
        if u >= self.n - 1:
            return self.h[-1]
        i = int(u)
        a = self.h[i]
        return a + (self.h[i + 1] - a) * (u - i)

    def slope(self, x: float) -> float:
        """dh/dx at x."""
        return (self.at(x + self.step) - self.at(x - self.step)) / (2 * self.step)

    def at_many(self, xs):
        grid = self.x0 + self.step * np.arange(self.n)
        return np.interp(xs, grid, np.asarray(self.h))

    @staticmethod
    def make(spec):
        """None | Terrain | callable h(x) | [(x, h), ...] | {"points": [...]} | {"hills": {...}} |
        {"amplitude":.., "wavelength":.., "seed":..}  ->  Terrain or None."""
        if spec is None or isinstance(spec, Terrain):
            return spec
        if callable(spec):
            return Terrain(fn=spec)
        if isinstance(spec, dict):
            if "points" in spec:
                return Terrain(points=spec["points"])
            if "hills" in spec:
                return terrain_hills(**dict(spec["hills"]))
            return terrain_hills(**spec)
        return Terrain(points=spec)


def terrain_hills(amplitude: float = 40.0, wavelength: float = 1200.0, seed: int = 0, x_flat=None,
                  flat_fade: float = 300.0) -> Terrain:
    """Rolling cartoon hills: three seeded sine octaves. x_flat=(xa, xb) keeps that range flat (0)
    and fades the hills in over flat_fade px on both sides."""
    r = random.Random(seed)
    ph = [r.uniform(0, 2 * math.pi) for _ in range(3)]
    k = 2 * math.pi / max(1.0, wavelength)

    def h(x):
        v = amplitude * (0.62 * math.sin(k * x + ph[0]) + 0.28 * math.sin(k * x / 0.53 + ph[1])
                         + 0.10 * math.sin(k * x / 0.29 + ph[2]))
        if x_flat is not None:
            xa, xb = x_flat
            d = max(xa - x, x - xb, 0.0)
            v *= ease(d / max(1.0, flat_fade))
        return v
    return Terrain(fn=h)


# ---------------------------------------------------------------- camera
class Camera:
    def __init__(self):
        self.x, self.y, self.zoom = 0.0, 0.0, 1.0
        self.keys = []
        self.sh = 0.0
        self.rng = random.Random(11)

    def at(self, t, follow, zoom=1.0, y=0.0):
        """Smoothly move to frame `follow` (list of objects) from time t."""
        self.keys.append((t, follow, zoom, y, False))
        self.keys.sort(key=lambda k: k[0])
        return self

    def cut(self, t, follow, zoom=1.0, y=0.0):
        """Hard cut: jump instantly to the new framing at time t (Shorts-style editing)."""
        self.keys.append((t, follow, zoom, y, True))
        self.keys.sort(key=lambda k: k[0])
        return self

    def shake(self, amount):
        self.sh = max(self.sh, amount)

    def update(self, dt, now, snap=False):
        key = None
        for k in self.keys:
            if k[0] <= now:
                key = k
        if not key:
            return
        _, follow, zoom, oy = key[:4]
        if not follow:
            return
        if len(key) > 4 and key[4] and getattr(self, "_active", None) is not key:
            snap = True
        self._active = key
        tx = sum(o.x for o in follow) / len(follow)
        k = 1 if snap else min(1, dt * 3.0)
        self._snapped = snap
        self.x += (tx - self.x) * k
        self.y += (oy + sum(getattr(o, "ground_y", 0.0) for o in follow) / len(follow) - self.y) * k
        self.zoom += (zoom - self.zoom) * (1 if snap else min(1, dt * 2.2))
        self.sh *= max(0, 1 - dt * 8)

    def offset(self):
        return (self.rng.uniform(-1, 1) * self.sh, self.rng.uniform(-1, 1) * self.sh)


# ---------------------------------------------------------------- world
WORLD_PRESETS = {
    "day": dict(sky_top="#7ec8ff", sky_bottom="#dff4ff", ground="#7cc66b", hills="#a9dc8e",
                far="#c9e8b8", sun="#fff08c"),
    "sunset": dict(sky_top="#ff7e5f", sky_bottom="#feb47b", ground="#6aa85a", hills="#8fb86a",
                   far="#c98f7a", sun="#ffe29a"),
    "night": dict(sky_top="#0b1d3a", sky_bottom="#2a4a7b", ground="#2f5a3a", hills="#3d6b48",
                  far="#4a5f86", sun="#f4f1c9"),
}


class World:
    def __init__(self, preset="day", seed=5, **over):
        cfg = dict(WORLD_PRESETS[preset])
        cfg.update(over)
        self.preset = preset
        r = random.Random(seed)
        self.sky_top, self.sky_bottom = hex2rgb(cfg["sky_top"]), hex2rgb(cfg["sky_bottom"])
        self.ground, self.hills, self.far = hex2rgb(cfg["ground"]), hex2rgb(cfg["hills"]), hex2rgb(cfg["far"])
        self.sun = hex2rgb(cfg["sun"])
        self.clouds = [(r.uniform(-3000, 3000), r.uniform(-330, -230), r.uniform(0.7, 1.4)) for _ in range(14)]
        self.trees = [(r.uniform(-4000, 4000), r.uniform(0.8, 1.3), r.random()) for _ in range(40)]
        self.flowers = [(r.uniform(-4000, 4000), r.uniform(20, 90),
                         r.choice(["#ff5d73", "#ffd166", "#ffffff", "#b388ff"])) for _ in range(160)]
        self.stars = [(r.random(), r.random() * 0.6, r.uniform(1, 2.5)) for _ in range(120)]

    def draw(self, ctx, W, H, cam, gy, now):
        g = cairo.LinearGradient(0, 0, 0, H)
        g.add_color_stop_rgb(0, *self.sky_top)
        g.add_color_stop_rgb(1, *self.sky_bottom)
        ctx.set_source(g)
        ctx.paint()
        if self.preset == "night":
            for sx, sy, sr in self.stars:
                tw = 0.6 + 0.4 * math.sin(now * 3 + sx * 50)
                ctx.arc(sx * W, sy * H, sr, 0, 2 * math.pi)
                ctx.set_source_rgba(1, 1, 0.9, tw)
                ctx.fill()
        z = cam.zoom
        sun_y = H * (0.17 if self.preset != "sunset" else 0.42)
        ctx.arc(W * 0.82, sun_y, 55, 0, 2 * math.pi)
        ctx.set_source_rgb(*self.sun)
        ctx.fill()
        ctx.arc(W * 0.82, sun_y, 80, 0, 2 * math.pi)
        ctx.set_source_rgba(*self.sun, 0.25)
        ctx.fill()

        def layer(par, fn):
            ctx.save()
            ctx.translate(W / 2, gy)
            ctx.scale(z ** par, z ** par)
            ctx.translate(-cam.x * par, cam.y * par)
            fn()
            ctx.restore()

        def clouds():
            a = 0.92 if self.preset != "night" else 0.25
            for x, y, s in self.clouds:
                xx = x + now * 12 * s
                ctx.set_source_rgba(1, 1, 1, a)
                for dx, dy, rr in ((0, 0, 34), (36, 8, 26), (-34, 8, 24), (14, -18, 26)):
                    ctx.arc(xx + dx * s, y + dy * s, rr * s, 0, 2 * math.pi)
                    ctx.fill()

        deep = 0 if getattr(self, "terrain", None) is None else 2400  # valleys: no sky under the hills

        def far_hills():
            ctx.move_to(-8000, deep)
            for i in range(-80, 81):
                x = i * 100
                ctx.line_to(x, -120 - 60 * math.sin(x * 0.0021) - 30 * math.sin(x * 0.0057 + 1))
            ctx.line_to(8000, deep)
            ctx.close_path()
            ctx.set_source_rgb(*self.far)
            ctx.fill()

        def hills():
            ctx.move_to(-8000, deep)
            for i in range(-160, 161):
                x = i * 50
                ctx.line_to(x, -60 - 40 * math.sin(x * 0.0043 + 2) - 15 * math.sin(x * 0.011))
            ctx.line_to(8000, deep)
            ctx.close_path()
            ctx.set_source_rgb(*self.hills)
            ctx.fill()
            dk = 0.55 if self.preset == "night" else 1.0
            for x, s, v in self.trees:
                ctx.rectangle(x - 5 * s, -70 * s, 10 * s, 40 * s)
                ctx.set_source_rgb(*shade((0.45, 0.32, 0.22), dk))
                ctx.fill()
                ctx.arc(x, -82 * s, 32 * s, 0, 2 * math.pi)
                ctx.set_source_rgb(*shade((0.36, 0.68, 0.36), (0.85 + 0.3 * v) * dk))
                ctx.fill()

        layer(0.08, clouds)
        layer(0.25, far_hills)
        layer(0.55, hills)

        T = getattr(self, "terrain", None)

        def ground_terrain():
            x0 = cam.x - W / (2 * z) - 60
            x1 = cam.x + W / (2 * z) + 60
            xs = np.arange(x0, x1 + 8, 8.0)
            hs = T.at_many(xs)

            def band(off0, off1, col):
                ctx.new_path()
                ctx.move_to(xs[0], -hs[0] + off0)
                for x, h in zip(xs[1:], hs[1:]):
                    ctx.line_to(x, -h + off0)
                if off1 is None:
                    ctx.line_to(xs[-1], 2400)
                    ctx.line_to(xs[0], 2400)
                else:
                    for x, h in zip(xs[::-1], hs[::-1]):
                        ctx.line_to(x, -h + off1)
                ctx.close_path()
                ctx.set_source_rgb(*col)
                ctx.fill()
            band(0, None, self.ground)
            band(0, 6, shade(self.ground, 0.85))
            band(70, None, shade(self.ground, 0.92))
            for x, y, c in self.flowers:
                if x0 <= x <= x1:
                    ctx.arc(x, y - T.at(x), 4, 0, 2 * math.pi)
                    ctx.set_source_rgb(*hex2rgb(c))
                    ctx.fill()

        def ground():
            if T is not None:
                return ground_terrain()
            ctx.rectangle(-8000, 0, 16000, 2000)
            ctx.set_source_rgb(*self.ground)
            ctx.fill()
            ctx.rectangle(-8000, 0, 16000, 6)
            ctx.set_source_rgb(*shade(self.ground, 0.85))
            ctx.fill()
            ctx.rectangle(-8000, 70, 16000, 2000)
            ctx.set_source_rgb(*shade(self.ground, 0.92))
            ctx.fill()
            for x, y, c in self.flowers:
                ctx.arc(x, y, 4, 0, 2 * math.pi)
                ctx.set_source_rgb(*hex2rgb(c))
                ctx.fill()

        layer(1.0, ground)


# ---------------------------------------------------------------- scene
_WORKER = {}


def _worker_init(static_blob):
    _WORKER["static"] = pickle.loads(static_blob)
    pick_font()


def _worker_render(snap_blob):
    st = _WORKER["static"]
    if isinstance(snap_blob, tuple):  # motion blur (#70): ("mb", prev, cur, samples, shutter)
        _, a, b, n, shutter = snap_blob
        return _render_blur(st, pickle.loads(a), pickle.loads(b), n, shutter)
    snap = pickle.loads(snap_blob)
    surf = cairo.ImageSurface(cairo.FORMAT_ARGB32, st["W"], st["H"])
    draw_frame(surf, st, snap)
    surf.flush()
    return bytes(surf.get_data())


# ---------------------------------------------------------------- motion blur (#70)
_MB_SKIP = frozenset(("dial_keys", "deform_keys", "deform_grids", "view_keys", "_xflip", "lines", "emotes", "gestures", "head_keys", "face_keys", "look_keys", "carry_keys",
                      "reach_keys", "queue", "spec", "cues", "ripples", "trail", "h", "keys", "stars",
                      "clouds", "trees", "flowers"))


def _lerp_state(a, b, k, memo):
    """Interpolate two snapshots of the same objects (floats only; everything else from b)."""
    tb = type(b)
    if tb is float:
        return a + (b - a) * k if type(a) in (float, int) else b
    key = id(b)
    if key in memo:
        return memo[key]
    if tb is dict:
        out = {}
        memo[key] = out
        if type(a) is dict:
            for kk, v in b.items():
                out[kk] = v if (kk in _MB_SKIP or kk not in a) else _lerp_state(a[kk], v, k, memo)
        else:
            out.update(b)
        return out
    if tb is list:
        if type(a) is list and len(a) == len(b):
            out = []
            memo[key] = out
            out.extend(_lerp_state(x, y, k, memo) for x, y in zip(a, b))
            return out
        return b
    if tb is tuple:
        if type(a) is tuple and len(a) == len(b):
            return tuple(_lerp_state(x, y, k, memo) for x, y in zip(a, b))
        return b
    d = getattr(b, "__dict__", None)
    if d is not None and type(a) is tb and hasattr(a, "__dict__"):
        o = copy.copy(b)
        memo[key] = o
        ad = a.__dict__
        for kk, v in d.items():
            if kk in _MB_SKIP or kk not in ad:
                continue
            if type(v) in (float, dict, list, tuple) or getattr(v, "__dict__", None) is not None:
                o.__dict__[kk] = _lerp_state(ad[kk], v, k, memo)
        return o
    return b


def _blur_snaps(a, b, n, shutter):
    """n sub-frame states spread over the last `shutter` fraction of the frame interval a -> b."""
    out = []
    for j in range(n):
        k = 1.0 - shutter + shutter * (j + 1) / n
        out.append(b if k >= 1.0 else _lerp_state(a, b, k, {}))
    return out


def _render_blur(st, a, b, n, shutter, surf=None):
    """Render the sub-frame states and average them (numpy) -> BGRA bytes."""
    surf = surf or cairo.ImageSurface(cairo.FORMAT_ARGB32, st["W"], st["H"])
    acc = None
    snaps = _blur_snaps(a, b, n, shutter)
    for s in snaps:
        draw_frame(surf, st, s)
        surf.flush()
        px = np.frombuffer(surf.get_data(), dtype=np.uint8)
        acc = px.astype(np.uint16) if acc is None else acc + px
    acc += len(snaps) // 2
    return (acc // len(snaps)).astype(np.uint8).tobytes()


def draw_frame(surf, st, snap):
    ctx = cairo.Context(surf)
    W, H, gy = st["W"], st["H"], st["gy"]
    cam = snap["cam"]
    now = snap["time"]
    st["world"].draw(ctx, W, H, cam, gy, now)
    ox, oy = snap["shake"]
    ctx.save()
    ctx.translate(W / 2 + ox, gy + oy)
    ctx.scale(cam.zoom, cam.zoom)
    ctx.translate(-cam.x, cam.y)
    bc = st.get("boil")  # line boil (#71): outlines of props / characters re-drawn every k frames
    wctx = ctx if not bc else _BoilCtx(ctx, bc["amount"], int(round(now * bc["fps"])) // bc["every"], bc["seed"])
    for b in snap.get("boxes", st["boxes"]):
        b.draw(wctx, now)
    for e in snap.get("extras", ()):
        e.draw(wctx, now)
    for p in snap.get("props", ()):
        if not p.carried:
            p.draw(wctx, now)
    for ch in sorted(snap["chars"], key=lambda c: c.scale):
        ch.draw(wctx, now)
    for e in snap.get("extras", ()):  # parts in front of the characters (vehicle doors, blankets, water)
        df = getattr(e, "draw_front", None)
        if df is not None:
            df(wctx, now)
    for b in snap["balls"]:
        b.draw(wctx, now)
    for p in snap.get("props", ()):
        if p.carried:
            p.draw(wctx, now)
    snap["particles"].draw(ctx)
    # world-space overlays in front of everything (lights, splashes, foreground props):
    # objects with draw_world(ctx, now) drawn with the camera transform applied
    for w in st.get("world_fx", ()):
        w.draw_world(ctx, now)
    ctx.restore()
    # set foreground (e.g. a counter edge, hay, a doorframe) drawn over the characters
    if hasattr(st["world"], "draw_foreground"):
        st["world"].draw_foreground(ctx, W, H, cam, gy, now)
    for ch in snap["chars"]:
        txt, prog, _ = ch.talking(now)
        if txt and st.get("bubbles", True):
            hx, hy = ch.head_world
            sx = W / 2 + (hx - cam.x) * cam.zoom
            sy = gy - (hy - cam.y) * cam.zoom - 24
            bubble(ctx, W, sx, sy, txt, prog)
    for fx in st.get("fx", ()):  # screen effects (toonfx): transitions, flashes...
        fx.draw(ctx, W, H, now)
    draw_subtitles(ctx, W, H, st, snap["chars"], now)
    for t, d, txt in st["captions"]:
        if t <= now < t + d:
            a = min(1, (now - t) * 4, (t + d - now) * 4)
            caption(ctx, W, H, txt, a)


def draw_subtitles(ctx, W, H, st, chars, now):
    """Subtitles for whoever speaks now (character lines and narration)."""
    if not st.get("subtitles"):
        return
    for t, d, text, _a, _g in st.get("narration", []):
        if t <= now < t + d:
            subtitle(ctx, W, H, text, (now - t) / d, accent=st.get("accent") or (1, 0.85, 0.3))
            return
    for ch in chars:
        txt, prog, _ = ch.talking(now)
        if txt:
            subtitle(ctx, W, H, txt, prog, accent=ch.body)
            return


def bubble(ctx, W, x, y, text, prog):
    ctx.select_font_face(FONT, cairo.FONT_SLANT_NORMAL, cairo.FONT_WEIGHT_BOLD)
    fs = max(20, W * 0.024)
    ctx.set_font_size(fs)
    ext = ctx.text_extents(text)
    pad = fs * 0.6
    w, h = ext.x_advance + pad * 2, fs + pad * 1.4
    pop = 1 + 0.25 * max(0, 1 - prog * 12)
    bx = clamp(x - w / 2, 10, W - w - 10)
    by = y - h - 18
    ctx.save()
    ctx.translate(x, y)
    ctx.scale(pop, pop)
    ctx.translate(-x, -y)
    r = h / 2

    def shape(inset=0.0):
        ctx.new_path()
        ctx.arc(bx + r, by + r, r - inset, math.pi / 2, 3 * math.pi / 2)
        ctx.arc(bx + w - r, by + r, r - inset, -math.pi / 2, math.pi / 2)
        ctx.close_path()

    shape()
    ctx.move_to(clamp(x - 10, bx + r, bx + w - r), by + h - 2)
    ctx.line_to(x, y)
    ctx.line_to(clamp(x + 12, bx + r, bx + w - r), by + h - 2)
    ctx.set_source_rgb(1, 1, 1)
    ctx.fill_preserve()
    ctx.set_source_rgb(*INK)
    ctx.set_line_width(3.5)
    ctx.stroke()
    shape(1)
    ctx.set_source_rgb(1, 1, 1)
    ctx.fill()
    # typewriter reveal
    n = max(1, int(len(text) * clamp(prog * 3.2, 0, 1)))
    ctx.move_to(bx + pad - ext.x_bearing, by + h / 2 + fs * 0.36)
    ctx.set_source_rgb(*INK)
    ctx.show_text(text[:n])
    ctx.restore()


def caption(ctx, W, H, text, a):
    ctx.select_font_face(FONT, cairo.FONT_SLANT_NORMAL, cairo.FONT_WEIGHT_BOLD)
    fs = W * 0.06
    ctx.set_font_size(fs)
    ext = ctx.text_extents(text)
    while ext.width > W * 0.9:
        fs *= 0.9
        ctx.set_font_size(fs)
        ext = ctx.text_extents(text)
    x = (W - ext.width) / 2 - ext.x_bearing
    y = H * 0.16
    ctx.move_to(x, y)
    ctx.text_path(text)
    ctx.set_source_rgba(*INK, a)
    ctx.set_line_width(fs * 0.16)
    ctx.set_line_join(cairo.LINE_JOIN_ROUND)
    ctx.stroke_preserve()
    ctx.set_source_rgba(1, 0.86, 0.3, a)
    ctx.fill()


def subtitle(ctx, W, H, text, prog, accent=(1, 0.85, 0.3), y_ratio=0.86):
    """Burned-in subtitle, word by word: spoken words white, current word in
    the accent colour, upcoming words hidden (TikTok/Shorts style)."""
    words = text.split()
    if not words:
        return
    ctx.select_font_face(FONT, cairo.FONT_SLANT_NORMAL, cairo.FONT_WEIGHT_BOLD)
    fs = W * 0.058
    ctx.set_font_size(fs)
    # word timing proportional to length
    lens = [len(w) + 1 for w in words]
    tot = sum(lens)
    acc, cur = 0, 0
    p = clamp(prog / 0.92, 0, 1)
    for i, L in enumerate(lens):
        if p * tot >= acc:
            cur = i
        acc += L
    shown = words[:cur + 1]
    # wrap into lines that fit 88% of the width
    lines, line = [], []
    for w in shown:
        trial = " ".join(line + [w])
        if line and ctx.text_extents(trial).x_advance > W * 0.88:
            lines.append(line)
            line = [w]
        else:
            line.append(w)
    lines.append(line)
    lines = lines[-2:]
    y = H * y_ratio - (len(lines) - 1) * fs * 1.15
    for li, ln in enumerate(lines):
        full = " ".join(ln)
        x = (W - ctx.text_extents(full).x_advance) / 2
        for wi, w in enumerate(ln):
            is_cur = li == len(lines) - 1 and wi == len(ln) - 1
            ctx.move_to(x, y)
            ctx.text_path(w)
            ctx.set_source_rgb(*INK)
            ctx.set_line_width(fs * 0.18)
            ctx.set_line_join(cairo.LINE_JOIN_ROUND)
            ctx.stroke_preserve()
            ctx.set_source_rgb(*(accent if is_cur else (1, 1, 1)))
            ctx.fill()
            x += ctx.text_extents(w + " ").x_advance
        y += fs * 1.15


class Scene:
    def __init__(self, width=1280, height=720, fps=30, duration=10.0, world=None, ground_ratio=0.78,
                 sfx_dir=None, subtitles=False, bubbles=True, terrain=None, motion_blur=None, boil=None,
                 boil_every=3):
        """boil (#71): global line boil for characters, props, balls and boxes — an amount (e.g. 0.8,
        ~1.4 px wobble) or {"amount", "every", "seed"}; boil_every: re-draw every k frames. Off by default."""
        self.W, self.H, self.fps, self.duration = width, height, fps, duration
        self.world = world or World()
        self.camera = Camera()
        self.particles = Particles()
        self.characters, self.balls, self.boxes = [], [], []
        self.props, self.extras = [], []  # rigid Props, Ropes (#39/#41)
        self.wind = 0.0  # global wind (px/s^2) for chains: scarves, hair, ropes
        self.events, self.captions, self.cues = [], [], []
        self.event_pos = []  # (pan -1..1, attenuation) per event, aligned with self.events
        self.cam_track = []  # (t, camera x, half visible width) for voice panning
        self.time = 0.0
        self.gy = height * ground_ratio
        self.sfx_dir = sfx_dir
        self.objects = {}
        self.subtitles, self.bubbles = subtitles, bubbles
        self.narration = []  # (t, d, text, audio) voice-over lines without a character
        # soundtrack (#80): True (classic loop) / False / mood name / track file / folder;
        # music_dir: where '<mood>_*' tracks are looked up (default: the music/ folder)
        self.music = True
        self.music_dir = None
        # terrain (#61): height function h(x), None = flat;  motion blur (#70): None = off
        self.terrain = None
        self.motion_blur = motion_blur
        self.boil, self.boil_every = boil, boil_every
        if terrain is not None:
            self.set_terrain(terrain)

    def set_terrain(self, terrain) -> "Terrain":
        """Hills / slopes (#61): a function h(x) (px, + = up), (x, h) points (smooth spline), a Terrain
        (e.g. terrain_hills(amplitude, wavelength, seed)) or None for flat ground. Characters walk on
        it (feet planted, body leaning into slopes), balls / props land and roll on it, the World
        ground follows it."""
        T = Terrain.make(terrain)
        self.terrain = T
        self.particles.floor = T
        if hasattr(self.world, "draw"):
            try:
                self.world.terrain = T
            except AttributeError:
                pass
        return T

    def ground_at(self, x: float) -> float:
        """Ground height at world x (0 on flat ground)."""
        T = getattr(self, "terrain", None)
        return T.at(x) if T is not None else 0.0

    def slope_at(self, x: float) -> float:
        """Ground slope dh/dx at x (0 on flat ground)."""
        T = getattr(self, "terrain", None)
        return T.slope(x) if T is not None else 0.0

    def add(self, obj, id: str = None):
        """Add a Character / Ball / Box / Prop / Rope / Puddle / Rain; `id` is used by JSON scenes."""
        if isinstance(obj, Prop):
            self.props.append(obj)
        elif isinstance(obj, (Rope, Puddle)):
            self.extras.append(obj)
        elif isinstance(obj, Rain):
            if not hasattr(self, "world_fx"):
                self.world_fx = []
            self.world_fx.append(obj)
        elif isinstance(obj, Character):
            self.characters.append(obj)
        elif isinstance(obj, Ball):
            self.balls.append(obj)
        elif isinstance(obj, Box):
            self.boxes.append(obj)
        elif callable(getattr(obj, "update", None)) and callable(getattr(obj, "draw", None)):
            self.extras.append(obj)  # duck-typed extra: drawn behind characters, in snapshots
        self.objects[id or getattr(obj, "name", str(len(self.objects)))] = obj
        return obj

    def event(self, kind: str, x: float = None, gain: float = 1.0) -> None:
        """Log a sound event at the current time (mixed into the soundtrack).
        x (world) gives stereo position + distance attenuation relative to the camera."""
        self.events.append((self.time, kind, gain))
        self.event_pos.append((None, 1.0) if x is None else self._pan(x))
        if x is not None and kind in Puddle.TRIGGERS:
            for e in getattr(self, "extras", ()):
                if isinstance(e, Puddle) and e.contains(x):
                    e.hit(x, kind, self, gain)

    def _pan(self, x):
        cam = self.camera
        half = self.W / 2 / max(cam.zoom, 0.05)
        dx = (x - cam.x) / half
        pan = clamp(dx, -1.0, 1.0)
        att = 1.0 / (1.0 + 0.45 * max(0.0, abs(dx) - 0.6))  # gentle fall-off outside the frame
        return (pan, att)

    def narrate(self, text: str, t: float, audio: str = None, d: float = None, gain: float = 1.0) -> float:
        """Voice-over line (no character). Returns its duration; shown as subtitles."""
        if audio and d is None:
            x, sr = read_audio(audio)
            d = len(x) / sr + 0.2
        d = d or max(1.2, 0.07 * len(text) + 0.5)
        self.narration.append((t, d, text, audio, gain))
        return d

    def caption(self, text: str, t: float, d: float = 2.0) -> None:
        """Big title text at the top of the frame."""
        self.captions.append((t, d, text))

    def cue(self, t: float, fn) -> None:
        """Call fn(scene) once at time t."""
        self.cues.append([t, fn, False])

    def confetti(self, t, n=160):
        self.cue(t, lambda s: (s.particles.confetti(s.camera.x, 380, n), s.event("pop")))

    def step(self, dt):
        for c in self.cues:
            if not c[2] and self.time >= c[0]:
                c[2] = True
                c[1](self)
        T = getattr(self, "terrain", None)
        if T is None:
            for ch in self.characters:
                ch.update(dt, self)
        else:  # characters move along the terrain during their own update (y stays world height)
            for ch in self.characters:
                if not getattr(ch, "_tplaced", False):
                    ch._tplaced = True
                    ch.y += T.at(ch.x)
                ch._terrain = T
                x0, a0 = ch.x, ch.current
                ch.update(dt, self)
                if not (getattr(a0, "abs_y", False) or getattr(ch.current, "abs_y", False)):
                    ch.y += T.at(ch.x) - T.at(x0)
                ch.ground_y = T.at(ch.x)
        for b in self.balls:
            b.update(dt, self)
        for p in sorted(getattr(self, "props", ()), key=lambda p: p.y):  # bottom-up: stacking
            p.update(dt, self)
        for e in getattr(self, "extras", ()):
            e.update(dt, self)
        self.particles.update(dt)
        self.camera.update(dt, self.time, snap=self.time == 0)
        if hasattr(self, "cam_track"):
            self.cam_track.append((self.time, self.camera.x, self.W / 2 / max(self.camera.zoom, 0.05)))
            for ch in self.characters:  # pan each line toward where its speaker stands when it starts
                for ln in ch.lines:
                    if "pan" not in ln and ln["t"] <= self.time:
                        ln["pan"] = self._pan(ch.x)[0] * 0.35
        self.time += dt

    def static(self):
        return dict(W=self.W, H=self.H, gy=self.gy, world=self.world, boxes=self.boxes,
                    captions=self.captions, subtitles=self.subtitles, bubbles=self.bubbles,
                    narration=self.narration, fx=getattr(self, "fx", []), accent=getattr(self, "accent", None),
                    world_fx=getattr(self, "world_fx", []), terrain=getattr(self, "terrain", None),
                    **self._boil_static())

    def _boil_static(self):
        bc = _boil_conf(getattr(self, "boil", None), getattr(self, "boil_every", 3))
        if bc is None:
            return {}
        bc["fps"] = self.fps
        return {"boil": bc}

    # motion blur (#70) -------------------------------------------------
    def _mb_conf(self, mb=None):
        mb = getattr(self, "motion_blur", None) if mb is None else mb
        if not mb:
            return None
        if mb is True:
            mb = {}
        elif isinstance(mb, (int, float)):
            mb = {"samples": int(mb)}
        c = dict(samples=5, shutter=0.5, mode="auto", threshold=900.0)
        c.update(mb)
        if "auto" in c:  # toonscript form {"samples", "shutter", "auto": bool}
            c["mode"] = "auto" if c.pop("auto") else "always"
        if c["mode"] not in ("auto", "always"):
            raise ValueError("motion_blur mode must be 'auto' or 'always'")
        c["samples"] = int(c["samples"])
        c["shutter"] = clamp(float(c["shutter"]), 0.05, 1.0)
        return c if c["samples"] >= 2 else None

    _MB_KEYS = ("torso", "head", "thighF", "kneeF", "thighB", "kneeB", "armUF", "elbowF", "armUB", "elbowB")

    def _motion_probe(self):
        """Cheap per-frame state used to measure on-screen speed."""
        P = []
        for ch in self.characters:
            pose = getattr(ch, "dpose", None) or ch.pose
            P.append((ch.x, ch.y, getattr(ch, "body_rot", 0.0), ch.scale,
                      tuple(pose.get(k, 0.0) for k in self._MB_KEYS)))
        objs = [(o.x, getattr(o, "y", 0.0)) for o in list(self.balls) + list(getattr(self, "props", ()))
                + [e for e in getattr(self, "extras", ()) if hasattr(e, "x") and hasattr(e, "y")]]
        cam = self.camera
        return P, objs, (cam.x, cam.y, cam.zoom)

    def motion_speed(self, a, b, dt) -> float:
        """Fastest on-screen motion between two probes (px/s): characters (body, limbs, rotation),
        balls / props / extras and the camera."""
        (ca, oa, ka), (cb, ob, kb) = a, b
        z = kb[2]
        v = math.hypot(kb[0] - ka[0], kb[1] - ka[1]) * z + abs(kb[2] - ka[2]) * self.W * 0.5
        for p, q in zip(ca, cb):
            s = q[3]
            v = max(v, math.hypot(q[0] - p[0], q[1] - p[1]) * z, abs(_wrap(q[2] - p[2])) * 90 * s * z)
            if len(p[4]) == len(q[4]):
                v = max(v, max(abs(_wrap(y - x)) for x, y in zip(p[4], q[4])) * 55 * s * z)
        for p, q in zip(oa, ob):
            v = max(v, math.hypot(q[0] - p[0], q[1] - p[1]) * z)
        return v / max(dt, 1e-6) * 720.0 / max(1, min(self.W, self.H))  # px/s at a 720p-equivalent size

    def snapshot(self):
        cam = Camera()
        cam.x, cam.y, cam.zoom = self.camera.x, self.camera.y, self.camera.zoom
        cam.keys, cam.rng = [], None
        return dict(time=self.time, cam=cam, shake=self.camera.offset(),
                    chars=self.characters, balls=self.balls, particles=self.particles,
                    boxes=self.boxes,  # boxes can move (carried / pushed)
                    props=getattr(self, "props", []), extras=getattr(self, "extras", []))

    def render(self, out: str = "scene.mp4", music=None, preview_png: dict = None,
               workers: int = None, crf: int = 20, motion_blur=None) -> str:
        """Simulate + draw every frame, encode H.264 and mux the soundtrack. preview_png maps
        frame index -> PNG path. workers>1 renders frames in parallel processes.
        music: None = use self.music; otherwise True / False / mood / file / folder.
        motion_blur (#70; default self.motion_blur, off): N samples or {"samples": N, "shutter": 0.5,
        "mode": "auto" | "always", "threshold": 900 (screen px/s, measured at 720p size)}. Sub-frame states are interpolated between
        the previous and current frame and averaged; auto blurs only frames where something moves
        faster than threshold on screen (others are rendered exactly as without blur)."""
        music = getattr(self, "music", True) if music is None else music
        mb = self._mb_conf(motion_blur)
        self.mb_frames = []
        dt = 1.0 / self.fps
        n = int(self.duration * self.fps)
        workers = workers or min(8, os.cpu_count() or 1)
        if "fork" not in mp.get_all_start_methods():
            workers = 1
        tmp_video = out + ".video.mp4"
        cmd = ["ffmpeg", "-y", "-loglevel", "error", "-f", "rawvideo", "-pix_fmt", "bgra",
               "-s", f"{self.W}x{self.H}", "-r", str(self.fps), "-i", "-",
               "-c:v", "libx264", "-preset", "veryfast", "-crf", str(crf), "-pix_fmt", "yuv420p", tmp_video]
        proc = subprocess.Popen(cmd, stdin=subprocess.PIPE)
        st = self.static()
        preview_png = preview_png or {}

        def emit(i, data):
            proc.stdin.write(data)
            if i in preview_png:
                s = cairo.ImageSurface.create_for_data(bytearray(data), cairo.FORMAT_ARGB32,
                                                      self.W, self.H)
                s.write_to_png(preview_png[i])

        mbs = dict(prev=None, probe=None)

        def frame_job(i):
            """Step one frame -> (snapshot blob, blur job or None)."""
            self.step(dt)
            if mb is None:
                return None, None
            blob = pickle.dumps(self.snapshot())  # one snapshot per frame (camera shake draws once)
            probe = self._motion_probe()
            job = None
            if mbs["prev"] is not None and not getattr(self.camera, "_snapped", False):
                fast = mb["mode"] == "always" or self.motion_speed(mbs["probe"], probe, dt) > mb["threshold"]
                if fast:
                    job = ("mb", mbs["prev"], blob, mb["samples"], mb["shutter"])
                    self.mb_frames.append(i)
            mbs["prev"], mbs["probe"] = blob, probe
            return blob, job

        if workers <= 1:
            surf = cairo.ImageSurface(cairo.FORMAT_ARGB32, self.W, self.H)
            for i in range(n):
                blob, job = frame_job(i)
                if job is not None:
                    emit(i, _render_blur(st, pickle.loads(job[1]), pickle.loads(job[2]), job[3], job[4], surf))
                    continue
                draw_frame(surf, st, self.snapshot() if blob is None else pickle.loads(blob))
                surf.flush()
                emit(i, bytes(surf.get_data()))
        else:
            ctxmp = mp.get_context("fork")
            with ctxmp.Pool(workers, _worker_init, (pickle.dumps(st),)) as pool:
                batch, idx, i = [], [], 0
                while i < n:
                    blob, job = frame_job(i)
                    batch.append(job if job is not None else (blob or pickle.dumps(self.snapshot())))
                    idx.append(i)
                    i += 1
                    if len(batch) >= workers * 4 or i == n:
                        for j, data in zip(idx, pool.map(_worker_render, batch)):
                            emit(j, data)
                        batch, idx = [], []
                        print(f"\rframe {i}/{n}", end="", file=sys.stderr)
        proc.stdin.close()
        proc.wait()
        print(file=sys.stderr)
        wav = out + ".wav"
        lines = [(ln["t"], ln["audio"], ln["gain"], ln.get("pan")) for c in self.characters for ln in c.lines
                 if ln["audio"]]
        lines += [(t, a, g) for t, d, txt, a, g in self.narration if a]
        speech = [(ln["t"], ln["d"]) for c in self.characters for ln in c.lines]
        speech += [(t, d) for t, d, *_ in self.narration]
        Audio(self.duration, self.sfx_dir, getattr(self, "music_dir", None)).build(self.events, music, lines, speech,
                                                 positions=getattr(self, "event_pos", None)).save(wav)
        subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", tmp_video, "-i", wav,
                        "-c:v", "copy", "-c:a", "aac", "-b:a", "192k", "-shortest",
                        "-movflags", "+faststart", out], check=True)
        os.remove(tmp_video)
        os.remove(wav)
        return out


# ---------------------------------------------------------------- audio
# Music library (#80): drop free / CC0 tracks named <mood>_*.mp3|ogg|wav into music/
# (see music/README.md); moods without a track use these procedural loops.
MUSIC_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "music")
MOODS = {
    "happy": dict(bpm=122, root=60, prog=[(0, 4, 7), (7, 11, 14), (9, 12, 16), (5, 9, 12)]),
    "calm": dict(bpm=72, root=62, prog=[(0, 4, 7, 11), (5, 9, 12, 16), (2, 5, 9, 12), (7, 11, 14, 17)]),
    "tense": dict(bpm=100, root=57, prog=[(0, 3, 7), (0, 3, 6), (1, 5, 8), (0, 3, 7)]),
    "funny": dict(bpm=136, root=62, prog=[(0, 4, 7), (5, 9, 12), (7, 11, 14), (0, 4, 7)]),
    "epic": dict(bpm=88, root=50, prog=[(0, 3, 7), (8, 12, 15), (3, 7, 10), (10, 14, 17)]),
    "sad": dict(bpm=64, root=57, prog=[(0, 3, 7), (5, 8, 12), (8, 12, 15), (7, 11, 14)]),
}


def _onepole(x: np.ndarray, lp: float) -> np.ndarray:
    """y[k] = (1-lp)*y[k-1] + lp*x[k]  (scipy lfilter, or truncated-IR convolution)."""
    try:
        from scipy.signal import lfilter
        return lfilter([lp], [1.0, -(1.0 - lp)], x)
    except ImportError:
        taps = int(min(len(x), max(1, math.ceil(math.log(1e-7) / math.log(max(1e-9, 1 - lp))))))
        h = lp * (1 - lp) ** np.arange(taps)
        return np.convolve(x, h)[:len(x)]


def _box_same(x: np.ndarray, k: int) -> np.ndarray:
    """Same result as np.convolve(x, ones(k)/k, mode='same') in O(N) via a running sum."""
    n = len(x)
    padded = np.concatenate([np.zeros(k - 1), x, np.zeros(k - 1)])
    cs = np.concatenate([[0.0], np.cumsum(padded)])
    full = (cs[k:] - cs[:-k]) / k  # length n + k - 1
    off = (k - 1) // 2
    return full[off:off + n]


class Audio:
    SR = 44100

    def __init__(self, duration, sfx_dir=None, music_dir=None):
        n = int(duration * self.SR) + self.SR
        self.duration = float(duration)
        self.music_dir = music_dir if music_dir is not None else MUSIC_DIR
        self.music_source = None  # what build() used: 'procedural', 'mood:<name>', or a file path
        self.sfx, self.music_buf, self.voice = np.zeros(n), np.zeros(n), np.zeros(n)
        # stereo: panned sounds go to L/R buffers; centred ones stay in the mono buffers above
        self.sfxL, self.sfxR, self.voiceL, self.voiceR = (np.zeros(n) for _ in range(4))
        self.rng = np.random.default_rng(1)
        self.samples = {}
        if sfx_dir and os.path.isdir(sfx_dir):
            for f in sorted(os.listdir(sfx_dir)):
                if f.lower().endswith((".wav", ".ogg", ".mp3", ".flac")):
                    kind = os.path.splitext(f)[0].split("_")[0].split("-")[0].lower()
                    x, _ = read_audio(os.path.join(sfx_dir, f), self.SR)
                    self.samples.setdefault(kind, []).append(x.astype(np.float64))

    def t(self, d):
        return np.arange(int(d * self.SR)) / self.SR

    @staticmethod
    def add(buf, at, sig, gain=1.0):
        i = int(at * Audio.SR)
        j = min(len(buf), i + len(sig))
        if 0 <= i < len(buf):
            buf[i:j] += sig[:j - i] * gain

    def noise(self, d: float, lp: float = 0.2) -> np.ndarray:
        """Low-passed white noise, peak-normalised. One-pole filter
        y[k] = y[k-1] + lp * (x[k] - y[k-1]), vectorised."""
        n = self.rng.standard_normal(len(self.t(d)))
        if len(n) == 0:
            return n
        out = _onepole(n, lp)
        return out / (np.max(np.abs(out)) + 1e-9)

    def synth(self, kind):
        t = self.t
        if kind in ("step", "runstep"):
            d = 0.06
            return self.noise(d, 0.15) * np.exp(-t(d) * 70) * (0.3 if kind == "step" else 0.45)
        if kind == "jump":
            d = 0.3
            f = 260 + 700 * t(d) / d
            return 0.35 * np.sin(2 * np.pi * np.cumsum(f) / self.SR) * np.exp(-t(d) * 7)
        if kind in ("land", "thud"):
            d = 0.25
            f = 110 * np.exp(-t(d) * 6) + 45
            body = np.sin(2 * np.pi * np.cumsum(f) / self.SR) * np.exp(-t(d) * 14)
            return 0.7 * body + 0.2 * self.noise(d, 0.1) * np.exp(-t(d) * 30)
        if kind == "kick":
            d = 0.18
            f = 180 * np.exp(-t(d) * 18) + 70
            return 0.7 * np.sin(2 * np.pi * np.cumsum(f) / self.SR) * np.exp(-t(d) * 20) + \
                0.3 * self.noise(d, 0.5) * np.exp(-t(d) * 45)
        if kind == "bounce":
            d = 0.12
            return 0.4 * np.sin(2 * np.pi * 150 * t(d)) * np.exp(-t(d) * 30)
        if kind == "hop":
            d = 0.12
            f = 500 + 500 * t(d) / d
            return 0.12 * np.sin(2 * np.pi * np.cumsum(f) / self.SR) * np.exp(-t(d) * 18)
        if kind == "slip":
            d = 0.45
            f = 1400 * np.exp(-t(d) * 4) + 200
            return 0.22 * np.sin(2 * np.pi * np.cumsum(f) / self.SR) * np.exp(-t(d) * 3)
        if kind == "clap":
            d = 0.09
            return 0.55 * self.noise(d, 0.6) * np.exp(-t(d) * 55)
        if kind == "chomp":  # crunchy bite: two short filtered noise bursts
            d = 0.16
            tt = t(d)
            out = 0.45 * self.noise(d, 0.45) * np.exp(-tt * 45)
            i = int(0.05 * self.SR)
            out[i:] += 0.3 * self.noise(d, 0.6)[:len(out) - i] * np.exp(-tt[:len(out) - i] * 60)
            return out
        if kind == "whoosh":
            d = 0.35
            env = np.sin(np.pi * t(d) / d) ** 2
            return 0.25 * self.noise(d, 0.08) * env
        if kind == "splash":
            d = 0.55
            tt = t(d)
            body = self.noise(d, 0.35) * np.exp(-tt * 9) * 0.45 + self.noise(d, 0.85) * np.exp(-tt * 16) * 0.25
            for k, (at, f0) in enumerate(((0.02, 520), (0.09, 760), (0.16, 640), (0.24, 900))):
                bt = self.t(0.09)
                f = f0 * (1 + 1.6 * bt / 0.09)  # rising 'bloop' of a bubble
                blip = np.sin(2 * np.pi * np.cumsum(f) / self.SR) * np.exp(-bt * 40) * 0.18
                i = int(at * self.SR)
                body[i:i + len(blip)] += blip[:len(body) - i]
            return body
        if kind == "pop":
            out = np.zeros(int(0.8 * self.SR))
            for k, fr in enumerate((1047, 1319, 1568, 2093)):
                s = np.sin(2 * np.pi * fr * t(0.4)) * np.exp(-t(0.4) * 9) * 0.15
                i = int(k * 0.07 * self.SR)
                out[i:i + len(s)] += s[:len(out) - i]
            return out
        return np.zeros(10)

    def music(self):
        bpm, beat = 112, 60 / 112
        prog = [(60, 64, 67), (55, 59, 62), (57, 60, 64), (53, 57, 60)]
        total = len(self.music_buf) / self.SR
        tt, bar = 0.0, 0
        while tt < total:
            chord = prog[bar % 4]
            for b in range(4):
                f = 440 * 2 ** ((chord[0] - 24 - 69) / 12)
                d = beat * 0.9
                self.add(self.music_buf, tt + b * beat, np.sin(2 * np.pi * f * self.t(d)) * np.exp(-self.t(d) * 3), 0.5)
            for k in range(8):
                note = chord[k % 3] + (12 if k >= 4 else 0)
                f = 440 * 2 ** ((note - 69) / 12)
                d = beat * 0.45
                ph = 2 * np.pi * f * self.t(d)
                self.add(self.music_buf, tt + k * beat / 2,
                         (np.sin(ph) + 0.3 * np.sin(2 * ph)) * np.exp(-self.t(d) * 8), 0.16)
            tt += 4 * beat
            bar += 1

    # ------------------------------------------------------------ music library (#80)
    def _tone(self, f, d, timbre="pluck"):
        """One synthesized note (frequency f Hz, d s) for the procedural mood loops."""
        tt = self.t(d)
        if len(tt) == 0:
            return tt
        ph = 2 * np.pi * f * tt
        if timbre == "pluck":
            sig = (np.sin(ph) + 0.35 * np.sin(2 * ph) + 0.12 * np.sin(3 * ph)) * np.exp(-tt * 9)
        elif timbre == "piano":
            sig = (np.sin(ph) + 0.4 * np.sin(2 * ph) * np.exp(-tt * 6) + 0.1 * np.sin(3 * ph)) * np.exp(-tt * 2.6)
        elif timbre == "pad":
            sig = (np.sin(ph) + 0.6 * np.sin(ph * 1.004) + 0.4 * np.sin(ph * 0.5 * 1.002) + 0.15 * np.sin(2 * ph))
            sig *= np.minimum(1.0, tt / (0.35 * d + 1e-3)) * np.minimum(1.0, (d - tt) / (0.3 * d + 1e-3))
        elif timbre == "saw":
            sig = sum(np.sin(k * ph) / k for k in range(1, 9))
            sig *= np.minimum(1.0, tt / 0.03) * np.exp(-tt * 1.5) * np.minimum(1.0, (d - tt) / 0.05 + 1e-3)
        elif timbre == "brass":
            bright = np.minimum(1.0, tt / 0.12)
            sig = sum(np.sin(k * ph) * (bright ** (k * 0.5)) / k for k in range(1, 7))
            sig *= np.minimum(1.0, tt / 0.06) * np.minimum(1.0, (d - tt) / 0.08 + 1e-3)
        elif timbre == "square":
            sig = sum(np.sin(k * ph) / k for k in (1, 3, 5, 7)) * np.exp(-tt * 7)
        elif timbre == "bell":
            sig = (np.sin(ph) + 0.5 * np.sin(2.76 * ph) * np.exp(-tt * 4)) * np.exp(-tt * 3.5)
        elif timbre == "bass":
            sig = (np.sin(ph) + 0.25 * np.sin(2 * ph)) * np.exp(-tt * 4) * np.minimum(1.0, tt / 0.01)
        else:
            sig = np.sin(ph) * np.exp(-tt * 5)
        return np.clip(np.minimum(1.0, (d - tt) / 0.015), 0, 1) * sig

    def _drum(self, kind):
        tt = self.t(0.3)
        if kind == "kick":
            f = 50 + 90 * np.exp(-tt * 30)
            return np.sin(2 * np.pi * np.cumsum(f) / self.SR) * np.exp(-tt * 9)
        if kind == "hat":
            n = self.t(0.05)
            x = self.rng.standard_normal(len(n))
            x = np.diff(x, prepend=0.0)  # crude high-pass
            return 0.25 * x / (np.max(np.abs(x)) + 1e-9) * np.exp(-n * 70)
        if kind == "snare":
            n = self.t(0.18)
            x = self.rng.standard_normal(len(n))
            return (0.6 * x / (np.max(np.abs(x)) + 1e-9) + 0.4 * np.sin(2 * np.pi * 190 * n)) * np.exp(-n * 22)
        if kind == "boom":  # epic low drum
            tt = self.t(0.9)
            f = 38 + 60 * np.exp(-tt * 12)
            return np.sin(2 * np.pi * np.cumsum(f) / self.SR) * np.exp(-tt * 4)
        return np.zeros(10)

    def mood_music(self, mood: str) -> np.ndarray:
        """Procedural loop for a mood (happy, calm, tense, funny, epic, sad) into music_buf.
        Different tempo, mode, progression and instruments per mood; peak-normalised to 0.9."""
        if mood not in MOODS:
            raise ValueError(f"unknown music mood {mood!r}; valid: {', '.join(MOODS)}")
        m = MOODS[mood]
        bpm = m["bpm"]
        beat = 60.0 / bpm
        buf = self.music_buf
        buf[:] = 0
        total = len(buf) / self.SR
        root = m["root"]
        hz = lambda note: 440 * 2 ** ((note - 69) / 12)
        tt, bar = 0.0, 0
        while tt < total:
            ch = [root + x for x in m["prog"][bar % len(m["prog"])]]
            if mood == "happy":
                for b in range(4):  # bouncy bass on the beat, plucked arpeggio in 8ths, hats
                    self.add(buf, tt + b * beat, self._tone(hz(ch[0] - 24 + (7 if b % 2 else 0)), beat * 0.8, "bass"), 0.55)
                    self.add(buf, tt + b * beat + beat / 2, self._drum("hat"), 0.5)
                for k in range(8):
                    note = ch[k % 3] + (12 if k in (3, 4, 7) else 0)
                    self.add(buf, tt + k * beat / 2, self._tone(hz(note), beat * 0.45, "pluck"), 0.17)
                self.add(buf, tt, self._drum("kick"), 0.5)
                self.add(buf, tt + 2 * beat, self._drum("kick"), 0.4)
            elif mood == "calm":  # long pad chords + a sparse bell melody
                for v in ch:
                    self.add(buf, tt, self._tone(hz(v - 12), beat * 4.1, "pad"), 0.12)
                for b in (0, 1.5, 3):
                    note = ch[int(b * 2) % 3] + 12
                    self.add(buf, tt + b * beat, self._tone(hz(note), beat * 1.8, "bell"), 0.1)
            elif mood == "tense":  # low saw ostinato in 8ths, pulsing, tritone stabs, heartbeat kick
                for k in range(8):
                    note = ch[0] - 24 + (1 if k % 4 == 3 else 0)
                    self.add(buf, tt + k * beat / 2, self._tone(hz(note), beat * 0.42, "saw"), 0.16)
                self.add(buf, tt + 3.5 * beat, self._tone(hz(ch[0] - 6), beat * 0.4, "saw"), 0.12)
                self.add(buf, tt, self._drum("kick"), 0.45)
                self.add(buf, tt + beat * 0.35, self._drum("kick"), 0.3)
                for v in ch:
                    self.add(buf, tt, self._tone(hz(v), beat * 4.0, "pad"), 0.05)
            elif mood == "funny":  # oom-pah: bass on 1 & 3, staccato chord on 2 & 4, chromatic run
                for b in range(4):
                    if b % 2 == 0:
                        self.add(buf, tt + b * beat, self._tone(hz(ch[0] - 24 + (7 if b == 2 else 0)), beat * 0.5, "square"), 0.4)
                    else:
                        for v in ch:
                            self.add(buf, tt + b * beat, self._tone(hz(v), beat * 0.25, "square"), 0.12)
                        self.add(buf, tt + b * beat, self._drum("snare"), 0.25)
                if bar % 2 == 1:
                    for k, step in enumerate((0, 1, 2, 3)):
                        self.add(buf, tt + 3 * beat + k * beat / 4, self._tone(hz(ch[2] + 12 + step), beat * 0.22, "pluck"), 0.16)
            elif mood == "epic":  # brass chords, booming drums, driving 8th strings
                for v in ch:
                    self.add(buf, tt, self._tone(hz(v - 12), beat * 3.8, "brass"), 0.14)
                for k in range(8):
                    self.add(buf, tt + k * beat / 2, self._tone(hz(ch[0] - 12), beat * 0.4, "saw"), 0.09)
                for b in (0, 1.5, 2, 3):
                    self.add(buf, tt + b * beat, self._drum("boom"), 0.55 if b == 0 else 0.35)
                self.add(buf, tt + 3 * beat, self._drum("snare"), 0.3)
            elif mood == "sad":  # slow piano arpeggio + soft pad, minor
                for k, idx in enumerate((0, 1, 2, 1)):
                    self.add(buf, tt + k * beat, self._tone(hz(ch[idx]), beat * 1.6, "piano"), 0.2)
                self.add(buf, tt, self._tone(hz(ch[0] - 12), beat * 4.0, "piano"), 0.18)
                for v in ch:
                    self.add(buf, tt, self._tone(hz(v), beat * 4.1, "pad"), 0.045)
            tt += 4 * beat
            bar += 1
        buf /= (np.max(np.abs(buf)) + 1e-9) / 0.9
        self.music_source = "mood:" + mood
        return buf

    def find_track(self, spec):
        """Resolve a music spec to an audio file: a file path, a folder (first track, or the first
        '<mood>_*' track when spec is 'folder' and mood is unknown), or a mood name looked up as
        <music_dir>/<mood>_*.mp3|ogg|wav|flac. Returns None when nothing matches."""
        exts = (".mp3", ".ogg", ".wav", ".flac", ".m4a")
        if not isinstance(spec, str):
            return None
        if os.path.isfile(spec):
            return spec
        if os.path.isdir(spec):
            files = sorted(f for f in os.listdir(spec) if f.lower().endswith(exts))
            return os.path.join(spec, files[0]) if files else None
        d = self.music_dir
        if spec in MOODS and d and os.path.isdir(d):
            files = sorted(f for f in os.listdir(d) if f.lower().endswith(exts)
                           and (f.lower().startswith(spec + "_") or f.lower().startswith(spec + "-")
                                or os.path.splitext(f.lower())[0] == spec))
            if files:
                return os.path.join(d, files[0])
        return None

    def load_track(self, path, fade_in=0.6, fade_out=1.8, xfade=1.0):
        """Loop (with crossfades) or trim a music file to the scene length, fade in/out."""
        x, _ = read_audio(path, self.SR)
        x = x.astype(np.float64)
        n = len(self.music_buf)
        nd = min(n, int(self.duration * self.SR)) or n
        if len(x) == 0:
            return self.music_buf
        x = x / (np.max(np.abs(x)) + 1e-9) * 0.9
        out = np.zeros(n)
        xf = int(min(xfade * self.SR, len(x) // 4))
        pos = 0
        while pos < nd:
            seg = x.copy()
            if pos > 0 and xf > 0:
                seg[:xf] *= np.linspace(0, 1, xf)
            if pos + len(seg) < nd and xf > 0:
                seg[-xf:] *= np.linspace(1, 0, xf)
            j = min(n, pos + len(seg))
            out[pos:j] += seg[:j - pos]
            pos += max(1, len(seg) - xf)
        fi, fo = int(fade_in * self.SR), int(min(fade_out, self.duration / 3) * self.SR)
        if fi:
            out[:fi] *= np.linspace(0, 1, fi)
        if fo:
            out[max(0, nd - fo):nd] *= np.linspace(1, 0, nd - max(0, nd - fo))
        out[nd:] = 0
        self.music_buf[:] = out
        self.music_source = path
        return self.music_buf

    def make_music(self, spec=True):
        """Fill music_buf from a spec: True (classic loop), a mood name, a file, or a folder.
        A mood uses <music_dir>/<mood>_* when such a track exists, else the procedural loop."""
        if spec is True:
            self.music()
            self.music_source = "procedural"
            return self.music_buf
        path = self.find_track(spec)
        if path:
            return self.load_track(path)
        if isinstance(spec, str) and spec.lower() in MOODS:
            return self.mood_music(spec.lower())
        if isinstance(spec, str) and (os.sep in spec or os.path.splitext(spec)[1]):
            raise FileNotFoundError(f"music track/folder not found: {spec!r}")
        raise ValueError(f"music must be True/False, a mood ({', '.join(MOODS)}), a file or a folder; got {spec!r}")

    @staticmethod
    def pan_gains(pan):
        """Equal-power pan, normalised so the centre is (1, 1) (mono-compatible)."""
        th = (clamp(pan, -1, 1) * 0.8 + 1) * math.pi / 4
        return math.cos(th) * math.sqrt(2), math.sin(th) * math.sqrt(2)

    def _add_panned(self, mono, left, right, at, sig, gain, pan):
        if pan is None or abs(pan) < 1e-3:
            self.add(mono, at, sig, gain)
        else:
            gl, gr = self.pan_gains(pan)
            self.add(left, at, sig, gain * gl)
            self.add(right, at, sig, gain * gr)

    def build(self, events, music=True, lines=(), speech=(), positions=None):
        """events: (t, kind, gain); positions: optional aligned (pan, attenuation) list;
        lines: (t, path, gain) or (t, path, gain, pan)."""
        cache = {}
        pick = random.Random(4)
        positions = list(positions or [])
        for idx, (at, kind, gain) in enumerate(events):
            pan, att = positions[idx] if idx < len(positions) else (None, 1.0)
            if kind in self.samples:
                sig = pick.choice(self.samples[kind])
                sig = sig / (np.max(np.abs(sig)) + 1e-9) * 0.6
            else:
                if kind not in cache:
                    cache[kind] = self.synth(kind)
                sig = cache[kind]
            self._add_panned(self.sfx, self.sfxL, self.sfxR, at, sig, gain * att, pan)
        for ln in lines:
            at, path, gain = ln[:3]
            pan = ln[3] if len(ln) > 3 else None
            x, _ = read_audio(path, self.SR)
            x = x.astype(np.float64)
            x = x / (np.max(np.abs(x)) + 1e-9) * 0.9
            self._add_panned(self.voice, self.voiceL, self.voiceR, at, x, gain, pan)
        if music:
            self.make_music(music)
            # duck music under dialogue
            env = np.ones(len(self.music_buf))
            for at, d in speech:
                i, j = int(at * self.SR), int((at + d) * self.SR)
                env[max(0, i):j] = 0.35
            k = int(0.15 * self.SR)
            env = _box_same(env, k)
            self.music_buf *= env * 0.35
        return self

    def save(self, path):
        base = self.sfx * 0.8 + self.music_buf + self.voice
        L = base + self.sfxL * 0.8 + self.voiceL
        R = base + self.sfxR * 0.8 + self.voiceR
        st = np.stack([L, R], axis=1)
        st = np.tanh(st * 1.1) * 0.95  # soft clip, never exceeds int16
        st = (st * 32767).astype(np.int16)
        with wave.open(path, "wb") as w:
            w.setnchannels(2)
            w.setsampwidth(2)
            w.setframerate(self.SR)
            w.writeframes(st.tobytes())


# ---------------------------------------------------------------- JSON scenes
def scene_from_json(path_or_dict, base_dir: str = None) -> "Scene":
    """Build a Scene from a JSON description (see example_scene.json)."""
    if isinstance(path_or_dict, str):
        base_dir = base_dir or os.path.dirname(os.path.abspath(path_or_dict))
        spec = json.load(open(path_or_dict))
    else:
        spec = path_or_dict
    base_dir = base_dir or "."
    res = lambda p: p if (p is None or os.path.isabs(p)) else os.path.join(base_dir, p)
    W, H = spec.get("size", [1280, 720])
    wcfg = dict(spec.get("world", {}))
    world = World(wcfg.pop("preset", "day"), **wcfg)
    sc = Scene(W, H, spec.get("fps", 30), spec.get("duration", 10), world,
               spec.get("ground_ratio", 0.78), res(spec.get("sfx_dir")))
    for b in spec.get("balls", []):
        sc.add(Ball(b.get("x", 0), b.get("r", 17)), b.get("id", "ball"))
    for b in spec.get("boxes", []):
        sc.add(Box(b.get("x", 0), b.get("w", 60), b.get("h", 55)), b.get("id"))
    chars = spec.get("characters", [])
    for c in chars:
        opts = {k: v for k, v in c.items() if k not in ("id", "actions", "lines", "emotes")}
        sc.add(Character(c["id"], **opts), c["id"])
    O = sc.objects

    def obj(i):
        if i not in O:
            raise KeyError(f"unknown id {i!r} in scene JSON (known: {', '.join(map(str, O))})")
        return O[i]

    def make(a):
        k = a["do"]
        if k == "move":
            return MoveTo(a["x"], a.get("gait", "walk"), a.get("speed"))
        if k == "chase":
            return Chase(obj(a["target"]), a.get("gait", "run"), a.get("reach", 38), a.get("timeout", 8))
        if k == "jump":
            return Jump(a.get("dx", 0), a.get("height", 90))
        if k == "kick":
            return Kick(obj(a.get("ball", "ball")), a.get("power", 700), a.get("lift", 0.55))
        if k == "turn":
            return Turn(a.get("face", 1))
        if k == "look":
            return Look(O.get(a.get("target")), a.get("face", True))
        simple = dict(wait=Wait, wave=Wave, point=Point, think=Think, cheer=Cheer, dance=Dance, laugh=Laugh)
        if k == "slip":
            return Slip()
        if k not in simple:
            raise ValueError(f"unknown action {k!r}; use one of: move, chase, jump, kick, turn, look, "
                             f"slip, {', '.join(simple)}")
        return simple[k](a.get("d", 1.0))

    for c in chars:
        ch = O[c["id"]]
        for a in c.get("actions", []):
            act = make(a)
            ch.at(a["at"], act) if "at" in a else ch.then(act)
        for ln in c.get("lines", []):
            ch.say(ln["text"], ln["t"], ln.get("d"), res(ln.get("audio")), res(ln.get("cues")))
        for e in c.get("emotes", []):
            ch.emote(e["name"], e["t"], e.get("d", 1.5))
    for k in spec.get("camera", [{"t": 0, "follow": [chars[0]["id"]] if chars else []}]):
        sc.camera.at(k["t"], [obj(i) for i in k["follow"]], k.get("zoom", 1.0), k.get("y", 0))
    for cap in spec.get("captions", []):
        sc.caption(cap["text"], cap["t"], cap.get("d", 2))
    for cf in spec.get("confetti", []):
        sc.confetti(cf["t"], cf.get("n", 160))
    return sc


if __name__ == "__main__":
    if len(sys.argv) >= 3:
        scene_from_json(sys.argv[1]).render(sys.argv[2])
        print("wrote", sys.argv[2])
    else:
        print("usage: python3 toonengine.py scene.json out.mp4")
